  ui_story_5035_50350101_138_dialog_content = "พวกเขากำลังสะกดจิตจริงๆ ... \"สัมผัสประสบการณ์การเผชิญหน้าอาถรรพณ์ที่แท้จริงจนคอแห้งเพราะเสียงร้องแห่งความสิ้นหวัง\"!",
  ui_story_5035_50350101_139_dialog_content = "(อย่าบอกนะว่าบ้านผีสิง Andersen คือ...)",
  ui_story_5035_50350101_140_dialog_content = "คุณคิดอย่างไร? ฟังดูไม่น่าสนใจเหรอ?",
  ui_story_5035_50350101_141_dialog_content = "ไม่! แม้แต่ทางสายย่อยเพียงอย่างเดียวก็ฟังดูซ้ำซากจำเจและโลดโผน!",
  ui_story_5035_50350101_142_dialog_content = "เฮ้, PlayerName, คุณไม่สนใจเลยเหรอ? การเผชิญหน้าอาถรรพณ์ที่แท้จริงแม้ว่า...",
  ui_story_5035_50350101_143_dialog_content = "(ดูเหมือนว่า Vice จะสนใจที่จะไปมาก...)",
  ui_story_5035_50350101_144_dialog_content = "รอง แล้วพวกเราล่ะ...",
  ui_story_5035_50350101_145_dialog_content = "และอย่าละเลยงานพิมพ์เล็ก ๆ PlayerName!",
  ui_story_5035_50350101_146_dialog_content = "\"Grand Opening Special: ลด 50% เมื่อซื้อบัตร 2 ใบ\"?",
  ui_story_5035_50350101_147_dialog_content = "ถูกตัอง, PlayerName! ฮี่ฮี่ฮี่",
  ui_story_5035_50350101_148_dialog_content = "ว่าแล้วเชียว!!!",
  ui_story_5035_50350201_1_dialog_content = "<color=#e8d9bb>Umbraton Outskirts: บ้านผีสิง Andersen</color>",
  ui_story_5035_50350201_2_dialog_content = "สถานที่แห่งนี้แน่นอนว่าอยู่ห่างไกลออกไป",
  ui_story_5035_50350201_3_dialog_content = "นั่นคือวิธีสร้างบรรยากาศบ้านผีสิง!",
  ui_story_5035_50350201_4_dialog_content = "มันดูน่าขนลุกในแวบแรก",
  ui_story_5035_50350201_5_dialog_content = "ประตูที่ทรุดโทรมนั้นควรเป็นทางเข้า",
  ui_story_5035_50350201_6_dialog_content = "มาเร็ว, PlayerNameและเตรียมตั๋วของคุณให้พร้อมด้วย",
  ui_story_5035_50350201_7_dialog_content = "โอ้? นี่ใช่มิสเตอร์เนวิเกเตอร์เหรอ?",
  ui_story_5035_50350201_8_dialog_content = "ฉันรู้สึกเมื่อเห็นชื่อบ้านผีสิง",
  ui_story_5035_50350201_9_dialog_content = "ยินดีที่ได้พบคุณอีกครั้ง ไมนอส! คุณรับหน้าที่บัตเลอร์ที่นี่ด้วยหรือเปล่า",
  ui_story_5035_50350201_10_dialog_content = "ใช่. ฉันขอโทษที่ไม่ได้ต้อนรับคุณเป็นพิเศษ",
  ui_story_5035_50350201_11_dialog_content = "กรุณาแสดงตั๋วของคุณ ถ้าคุณต้องการ PlayerName.",
  ui_story_5035_50350201_12_dialog_content = "คุณสุภาพเหมือนเดิม คุณไมนอส",
  ui_story_5035_50350201_13_dialog_content = "นี่คือ Vice เพื่อนที่ดีของฉัน",
  ui_story_5035_50350201_14_dialog_content = "สวัสดีคนรับตั๋ว! สโลแกนจริงหรือ? เราจะประสบปรากฏการณ์เหนือธรรมชาติจริงหรือไม่?",
  ui_story_5035_50350201_15_dialog_content = "เอ่อ และ เธอเป็นแฟนตัวยงของอาถรรพณ์",
  ui_story_5035_50350201_16_dialog_content = "ใช่ แน่นอน นางสาวไวซ์ เป็นของแท้หรือรับประกันคืนเงิน",
  ui_story_5035_50350201_17_dialog_content = "รู้สึกอิสระที่จะกรีดร้องออกมาและมีประสบการณ์ที่ยอดเยี่ยมและน่ากลัว",
  ui_story_5035_50350201_18_dialog_content = "ฉันรอคอยมัน!",
  ui_story_5035_50350201_19_dialog_content = "ยังไงก็ตาม นี่คือกิจการล่าสุดของ Nina หรือไม่?",
  ui_story_5035_50350201_20_dialog_content = "ถูกต้อง. เธอเพิ่งหันมาสนใจอสังหาริมทรัพย์และตั้งบ้านผีสิงแห่งนี้ให้เป็นสถานที่ท่องเที่ยว",
  ui_story_5035_50350201_21_dialog_content = "แม้ว่าสิ่งต่าง ๆ จะไม่เป็นไปตามที่เธอวางแผนไว้ แต่นี่เป็นทรัพย์สินแรกของเธอ",
  ui_story_5035_50350201_22_dialog_content = "แน่นอน ฉันต้องทำทุกวิถีทางเพื่อสนับสนุนมัน",
  ui_story_5035_50350201_23_dialog_content = "คฤหาสน์ที่คุณเห็นก่อนคุณถูกเลือกโดยเราสองคนหลังจากการคัดกรองอย่างพิถีพิถัน",
  ui_story_5035_50350201_24_dialog_content = "การซื้อบ้านหลังใหญ่เช่นนี้จะต้องเสียค่าใช้จ่ายเป็นจำนวนมาก",
  ui_story_5035_50350201_25_dialog_content = "ไม่ได้จริงๆ มันมีราคาไม่แพงผิดปกติ",
  ui_story_5035_50350201_26_dialog_content = "แม้แต่การปรับปรุงบ้านผีสิงก็มีค่าใช้จ่ายน้อยมาก",
  ui_story_5035_50350201_27_dialog_content = "นั่นเป็นเหตุผลที่ฉันเชื่อมั่นในความสำเร็จทางการเงินของโครงการนี้",
