  ui_story_5035_50350301_86_dialog_content = "อ๊ะ!",
  ui_story_5035_50350301_87_dialog_content = "เป็นการหลอกลวงที่จะขายตั๋ว ฉันไม่ได้ตกหลุมรักมัน",
  ui_story_5035_50350301_88_dialog_content = "แต่เห็นได้ชัดว่าคุณสนใจมันมาก ...",
  ui_story_5035_50350301_89_dialog_content = "อ่าฮะ ดูเหมือนคุณหญิงซาดีจะเป็นคนค่อนข้างทื่อๆ",
  ui_story_5035_50350301_90_dialog_content = "คุณไม่มีเวลามากพอที่จะตัดสินใจ ไมนอส เรากำลังสำรวจสถานที่อยู่แล้ว",
  ui_story_5035_50350301_91_dialog_content = "งั้นก็ช่วยตัวเอง",
  ui_story_5035_50350301_92_dialog_content = "ตกลง. โกลดี้ ซาดี ไปกันเถอะ",
  ui_story_5035_50350301_93_dialog_content = "ซาดี...?",
  ui_story_5035_50350301_94_dialog_content = "ฉัน เอ่อ ทำบางอย่างหาย ฉันต้องไปหามัน",
  ui_story_5035_50350301_95_dialog_content = "เหมาะกับตัวเอง คุณไม่ได้อยู่ในสองสามฉากต่อไป",
  ui_story_5035_50350301_96_dialog_content = "มากับ Minos หลังจากที่คุณหามันเจอ",
  ui_story_5035_50350301_97_dialog_content = "ใช่ ฉันจะทำให้แน่ใจว่า",
  ui_story_5035_50350301_98_dialog_content = "ไปช่วยซาดีออกไประหว่างรอลิลิก้า",
  ui_story_5035_50350301_99_dialog_content = "ใช่ เธอควรจะกลับมาเมื่อถึงเวลานั้น",
  ui_story_5035_50350301_100_dialog_content = "<color=#e8d9bb>สับเปลี่ยน สับเปลี่ยน...</color>",
  ui_story_5035_50350301_101_dialog_content = "ฉันได้ยินเธอมา!",
  ui_story_5035_50350301_102_dialog_content = "อยู่ตรงนี้ ลิลิก้า!",
  ui_story_5035_50350301_103_dialog_content = "...?",
  ui_story_5035_50350301_104_dialog_content = "(Eclipsian) ... พูดกับฉันเหรอ?",
  ui_story_5035_50350301_105_dialog_content = "II- มันกำลังพูดอะไรบางอย่าง!",
  ui_story_5035_50350301_106_dialog_content = "Eclipsites เหล่านี้ไม่เคยหายไป?",
  ui_story_5035_50350301_107_dialog_content = "คุณกำลังขาดประเด็น คุณทั้งคู่!",
  ui_story_5035_50350301_108_dialog_content = "เราต้องพาพวกเขาออกไปจากที่นี่!",
  ui_story_5035_50350302_1_dialog_content = "พวกเขาเข้ามาได้ยังไง...?",
  ui_story_5035_50350302_2_dialog_content = "คุณนีน่ากับฉันได้ตรวจสอบความปลอดภัยของบ้านก่อนจะเปิดธุรกิจ",
  ui_story_5035_50350302_3_dialog_content = "แต่เลย์เอาต์ของบ้านหลังนี้ซับซ้อน ถ้าพวกมันเข้ามาทางทางเข้าอื่น ฉันก็จะไม่สามารถตรวจพบได้ในทันที",
  ui_story_5035_50350302_4_dialog_content = "(หวังว่าคุณนีน่าจะปลอดภัยที่ทางเข้านะ...)",
  ui_story_5035_50350302_5_dialog_content = "มีใครเจ็บมั้ย?",
  ui_story_5035_50350302_6_dialog_content = "ไม่ มันง่ายที่จะเอาชนะ Eclipsites",
  ui_story_5035_50350302_7_dialog_content = "ว่าแต่คุณเสียอะไรไปรึเปล่า ซาดี้?",
  ui_story_5035_50350302_8_dialog_content = "เอ่อ...",
  ui_story_5035_50350302_9_dialog_content = "นั่นเป็นเพียงข้ออ้างที่จะขับไล่จอนนี่",
  ui_story_5035_50350302_10_dialog_content = "ฉันหมายถึง ฉันเป็นคนบ้าๆบอๆ ดังนั้นไม่มีทางที่ของของฉันจะหาย",
  ui_story_5035_50350302_11_dialog_content = "ฉันแค่เบื่อที่จะติดตามจอนนี่ไปรอบๆ และฟังเขาเทศนา",
  ui_story_5035_50350302_12_dialog_content = "งั้นเหรอ?",
  ui_story_5035_50350302_13_dialog_content = "และฉันก็บังเอิญทำแผนที่ตำแหน่งภาพยนตร์ของเขาตอนที่ฉันพูด",
  ui_story_5035_50350302_14_dialog_content = "(เดี๋ยวก่อน นั่นมันขโมย!)",
  ui_story_5035_50350302_15_dialog_content = "II แค่อยากรู้เกี่ยวกับสถานที่ในแผนภูมิ แต่ฉันไม่สามารถคิดหัวหรือก้อยได้",
  ui_story_5035_50350302_16_dialog_content = "ดังนั้นฉันจึงโยนข้ออ้างที่จะอยู่เบื้องหลัง",
  ui_story_5035_50350302_17_dialog_content = "มาช่วยฉันและลองคิดดูว่ามีอะไรอยู่ในนั้น",
  ui_story_5035_50350302_18_dialog_content = "อา ฉันเข้าใจแล้ว!",
  ui_story_5035_50350302_19_dialog_content = "ซาดี คุณต้องการเข้าร่วมทีมสำรวจของเราใช่ไหม",
  ui_story_5035_50350302_20_dialog_content = "ว-อะไร?",
  ui_story_5035_50350302_21_dialog_content = "ไม่มีทาง! เลิกพูดไร้สาระสักที ฉันมีสามัญสำนึกแล้ว!",
  ui_story_5035_50350302_22_dialog_content = "<anim type=Shake>ทั้งหมด<size=45> นั่น </size>เป็น <size=45>ปลอม</size> สามารถ <size=30>ไม่เคย</size> ทำ <size=45>เอ</size> นักเลงที่แท้จริง <size=45>กรี๊ด!</size>♪</anim>",
  ui_story_5035_50350302_23_dialog_content = "<anim type=Shake><size=50>ฉัน</size> แค่ <size=45>ที่นี่</size> ขอบเขต<size=30> ถ้า </size>บ้านผีสิง<size=45> เป็นยาเสพติด!</size>♪</anim>",
  ui_story_5035_50350302_24_dialog_content = "<anim type=Shake>ไม่เหมือน<size=45> คุณ </size>คำราม, <size=30>ฉัน</size> จะ<size=45> ไม่เคย</size> ตกสำหรับ <size=45>การแสดงความสามารถนี้!</size>♪</anim>",
  ui_story_5035_50350302_25_dialog_content = "(เธอตื่นเต้นไปหมด)",
  ui_story_5035_50350302_26_dialog_content = "ในกรณีนั้นเรามาดูสถานที่เหล่านี้กันดีไหม?",
  ui_story_5035_50350302_27_dialog_content = "เอานี่ไป",
  ui_story_5035_50350302_28_dialog_content = "ใช่... ดูเหมือนว่าจะมีสามแห่ง",
  ui_story_5035_50350302_29_dialog_content = "ดิ <color=#FFB400>ห้องนอนชั้นหนึ่ง</color>, <color=#FFB400>โชว์รูมชั้นสอง</color>, และ <color=#FFB400>ชั้นใต้ดิน</color>.",
  ui_story_5035_50350302_30_dialog_content = "อืม ทั้งสามห้องมีภาพที่สวยงามและเหมาะมากสำหรับการถ่ายทำ",
  ui_story_5035_50350302_31_dialog_content = "ไปตรวจสอบพวกเขาตามลำดับ!",
  ui_story_5035_50350302_32_dialog_content = "พิจารณา? สอบอะไร?",
  ui_story_5035_50350302_33_dialog_content = "นี่หมายความว่าทีมสำรวจของฉันกำลังกระโจนเข้าสู่การปฏิบัติหรือไม่?",
  ui_story_5035_50350302_34_dialog_content = "ฉันถ่ายทำซีเควนซ์เปิดเสร็จแล้ว พวกคุณมาทำอะไรที่นี่?",
  ui_story_5035_50350302_35_dialog_content = "คุณกลับมาแล้ว ลิลิก้า!",
  ui_story_5035_50350302_36_dialog_content = "นี่คือ Sadie สมาชิกคนล่าสุดของทีมของเรา!",
  ui_story_5035_50350302_37_dialog_content = "ฉันไม่ได้เป็นส่วนหนึ่งของเรื่องนี้",
  ui_story_5035_50350302_38_dialog_content = "สวัสดี ซาดี! ฉันชื่อลิลิก้า ฉันชอบถ่าย ล่าผี และอาหารทะเล!",
  ui_story_5035_50350302_39_dialog_content = "อย่าลากฉันเข้ามาในนี้...",
  ui_story_5035_50350302_40_dialog_content = "ที่นี่ยิ้มให้กล้องและขอให้เราพบตำแหน่งที่แท้จริงของอาถรรพณ์!",
  ui_story_5035_50350302_41_dialog_content = "ฉันบอกว่าฉันไม่ต้องการ... ยินดีที่ได้รู้จัก.",
