  ui_story_5035_50350302_43_dialog_content = "สมาชิกทีมทั้งหมดรวมตัวกัน!",
  ui_story_5035_50350302_44_dialog_content = "แล้วคุณทำอะไรคืบหน้าหรือยัง?",
  ui_story_5035_50350302_45_dialog_content = "ใช่! Sadie คว้าแผนผังสถานที่จากทีมงานฝ่ายผลิต และเราตัดสินใจเดินตามเส้นทาง",
