  ui_story_5035_50350302_52_dialog_content = "และในส่วนของ Special Thank! และบนหน้าปกของวีดิโอเทป...",
  ui_story_5035_50350302_53_dialog_content = "...",
  ui_story_5035_50350302_54_dialog_content = "เราควรรีบไปยังสถานที่แรก!",
