  ui_story_5035_50350302_56_dialog_content = "Into the Haunted House เริ่มถ่ายทำอย่างเป็นทางการแล้ว! กรี๊ดให้สุดหัวใจทุกคน!",
  ui_story_5035_50350401_1_dialog_content = "<color=#e8d9bb>บ้านผีสิง Andersen: ทางเดินชั้นหนึ่ง</color>",
  ui_story_5035_50350401_2_dialog_content = "(การพลิกผันทั้งหมดนี้ทำให้ฉันเวียนหัว...)",
  ui_story_5035_50350401_3_dialog_content = "เดี๋ยวก่อน ทุกคน อีกสองทางเดินข้างหน้า และเราจะมาถึง",
