  ui_story_5035_50350401_9_dialog_content = "เลดี้แอสเตอร์คือใคร?",
  ui_story_5035_50350401_10_dialog_content = "เอ้า ไปเลย นิทรรศการเบื้องหลัง!",
  ui_story_5035_50350401_11_dialog_content = "เอาไปใส่ในวิดีโอน่าจะช่วยสร้างบรรยากาศสยองได้!",
  ui_story_5035_50350401_12_dialog_content = "ยืนตรงนี้ ไมนอส ใช่อีกเล็กน้อย",
  ui_story_5035_50350401_13_dialog_content = "ไม่เป็นไรใช่ไหม ลิลิก้า?",
