  ui_story_5035_50350401_16_dialog_content = "Lady Astor ไม่มีญาติสนิท เธออาศัยอยู่ที่นี่คนเดียวกับคนรับใช้ของเธอ",
  ui_story_5035_50350401_17_dialog_content = "เธอเป็นคนประหลาดและมีอาการหวาดระแวงอย่างรุนแรง",
  ui_story_5035_50350401_18_dialog_content = "ทันทีที่พระอาทิตย์ตกดิน เธอมักจะกังวลว่ามีสิ่งที่ไม่สะอาดเข้ามาในบ้านและพยายามจะฆ่าเธอ...",
  ui_story_5035_50350401_19_dialog_content = "อ๊ากกก!",
  ui_story_5035_50350401_20_dialog_content = "ม-อะไรนะ รอง!",
  ui_story_5035_50350401_21_dialog_content = "เฮ้ ฉันสบายดี ฉันอดไม่ได้ที่จะกรีดร้องในช่วงเวลาสำคัญแบบนั้น",
  ui_story_5035_50350401_22_dialog_content = "แล้วไง แล้วไง",
  ui_story_5035_50350401_23_dialog_content = "แล้ว...",
