  ui_story_5035_50350401_25_dialog_content = "เธอเพิ่มหน้าต่างและบันไดที่ไร้จุดหมายจำนวนมาก และนอนในห้องนอนคนละห้องกันทุกคืน",
  ui_story_5035_50350401_26_dialog_content = "เทียนข้างเตียงของเธอจะแผดเผาตลอดทั้งคืน ฉายเงาไหล่ที่สั่นเทาของเธอบนผนัง",
  ui_story_5035_50350401_27_dialog_content = "หวา!",
