  ui_story_5035_50350401_29_dialog_content = "ในที่สุดเธอก็เสียชีวิตในกองไฟ",
  ui_story_5035_50350401_30_dialog_content = "เทียนทำให้ห้องลุกเป็นไฟ และ Lady Astor ก็หนีไปด้วยความตื่นตระหนก",
