  ui_story_5035_50350401_33_dialog_content = "สมมุติว่าเจ้าของเดิมยังคงได้ยินเสียงคนใช้วิ่งอยู่ในตอนกลางคืน",
  ui_story_5035_50350401_34_dialog_content = "ฉันตรวจดูบ้านทั้งหลังแล้วแต่ก็ยังไม่แน่ใจนักว่าศพของพวกมันไม่ได้นอนอยู่ตามซอกซอกที่ยังไม่ได้ค้นพบ...",
