  ui_story_5035_50350401_46_dialog_content = "ใช่-",
  ui_story_5035_50350401_47_dialog_content = "-ฮะ?",
  ui_story_5035_50350401_48_dialog_content = "ห้องนี้ดู... ธรรมดา แม้จะโทรมไปหน่อย",
  ui_story_5035_50350401_49_dialog_content = "แต่การจัดแสงนั้นสมบูรณ์แบบสำหรับการสร้างบรรยากาศที่น่าสยดสยอง",
  ui_story_5035_50350401_50_dialog_content = "โปรดส่งแผนภูมิให้ฉันด้วย Sadie เพื่อที่ฉันจะได้เห็นว่ามีการวางแผนสำหรับฉากนี้กี่ฉาก",
  ui_story_5035_50350401_51_dialog_content = "เอานี่ไป",
  ui_story_5035_50350401_52_dialog_content = "อืม ฉันเห็น...",
  ui_story_5035_50350401_53_dialog_content = "เฮ้ ทุกคน มาดูนี่สิ!",
  ui_story_5035_50350401_54_dialog_content = "มันเป็นทีวีจำลองที่เหมือนจริงมาก!",
  ui_story_5035_50350401_55_dialog_content = "มาถ่ายรูปหมู่กันเถอะ!",
  ui_story_5035_50350401_56_dialog_content = "นั่นไม่ใช่อุปกรณ์สำหรับบ้านผีสิงหรือส่วนหนึ่งของฉากภาพยนตร์",
  ui_story_5035_50350401_57_dialog_content = "เป็นสิ่งหนึ่งที่รอดชีวิตจากไฟได้",
  ui_story_5035_50350401_58_dialog_content = "(ว้าว เท่าที่ฉันรู้ คุณจะพบแต่สิ่งเหล่านั้นใน Illumina...)",
  ui_story_5035_50350401_59_dialog_content = "ฮึ่ม ไม่มีอะไรมากไปกว่าของที่ระลึกธรรมดาทั่วไป",
  ui_story_5035_50350401_60_dialog_content = "อย่าประมาทโทรทัศน์! มันสามารถเป็นพร็อพสะบัดสยองขวัญที่มีประสิทธิภาพหากใช้อย่างเหมาะสม",
  ui_story_5035_50350401_61_dialog_content = "ตัวอย่างเช่น คุณสามารถเห็นเงาสะท้อนของบุคคลที่ไม่รู้จักบนหน้าจอมืด...",
  ui_story_5035_50350401_62_dialog_content = "หรือผู้หญิงผมยาวน่ากลัวจะคลานออกมาได้...",
  ui_story_5035_50350401_63_dialog_content = "มาเลย มาถ่ายรูปข้างๆกัน!",
  ui_story_5035_50350401_64_dialog_content = "<color=#e8d9bb>ซ่า...</color>",
  ui_story_5035_50350401_65_dialog_content = "อืม...",
  ui_story_5035_50350401_66_dialog_content = "ไม่มีทาง ไม่มีทาง...!",
  ui_story_5035_50350401_67_dialog_content = "อย่าบอกนะว่า...",
  ui_story_5035_50350401_68_dialog_content = "<color=#e8d9bb>กสสสสสสสสสสสส...</color>",
  ui_story_5035_50350401_69_dialog_content = "สวัสดี",
  ui_story_5035_50350401_70_dialog_content = "อ๊ากกกกก มาแล้ว!!!!",
  ui_story_5035_50350401_71_dialog_content = "มาแล้วจ้า! น่าตื่นเต้นแค่ไหน! ฉันต้องได้รับมันในเทป!",
  ui_story_5035_50350401_72_dialog_content = "สวัสดี คุณเป็นส่วนหนึ่งของนักแสดง คนในทางที่ผิดในหน้ากาก หรือวิญญาณของวิดีโอเทปหรือไม่?",
  ui_story_5035_50350401_73_dialog_content = "(ไม่มีสิ่งที่เรียกว่าวิญญาณของวิดีโอเทป!)",
  ui_story_5035_50350401_74_dialog_content = "คุณไม่รู้จักฉัน แต่ฉันรู้จักคุณ",
  ui_story_5035_50350401_75_dialog_content = "ไม่เป็นไร ฉันรู้จักคุณแล้ว พูดสวัสดีกับกล้อง! ชีส!",
  ui_story_5035_50350401_76_dialog_content = "ฉันอยากเล่นเกม.",
  ui_story_5035_50350401_77_dialog_content = "ได้สิ ไม่มีปัญหา!",
  ui_story_5035_50350401_78_dialog_content = "(ทำไมเธอถึงตื่นเต้นกับมัน...)",
  ui_story_5035_50350401_79_dialog_content = "ถ้าคุณถามฉัน เห็นได้ชัดว่ามันถ่ายทำไว้ล่วงหน้า",
  ui_story_5035_50350401_80_dialog_content = "เพื่อนสวมหน้ากากคนนั้นไม่เคยตอบคำถามของลิลิกา",
  ui_story_5035_50350401_81_dialog_content = "ไม่จำเป็นสำหรับฉันที่จะตอบคำถามทุกข้อ",
  ui_story_5035_50350401_82_dialog_content = "?!",
  ui_story_5035_50350401_83_dialog_content = "เพราะปริศนาทั้งสามของฉันรอคุณอยู่",
  ui_story_5035_50350401_84_dialog_content = "เอาล่ะ มาเริ่มเกมกันเถอะ",
  ui_story_5035_50350401_85_dialog_content = "ห้องนี้ถูกล็อคอยู่ข้างหลังคุณทันทีที่คุณเข้ามา",
  ui_story_5035_50350401_86_dialog_content = "<color=#e8d9bb>สั่น...</color>",
  ui_story_5035_50350401_87_dialog_content = "มันไม่ขยับ... ต-นั่นมันพูดความจริง!",
  ui_story_5035_50350401_88_dialog_content = "เพียงเพื่อให้คุณไม่ได้เสียเปรียบทั้งหมด ...",
  ui_story_5035_50350401_89_dialog_content = "ฉันจะให้คำใบ้แก่คุณว่าฉันซ่อนกุญแจไว้ที่ไหน",
  ui_story_5035_50350401_90_dialog_content = "ไม่ว่าคุณจะอยู่หรือตายขึ้นอยู่กับคุณ",
  ui_story_5035_50350401_91_dialog_content = "เอ่อ ไมนอส นี่มันเกิดอะไรขึ้น?",
  ui_story_5035_50350401_92_dialog_content = "พ่อบ้านต้องสงบสติอารมณ์ตลอดเวลา PlayerNameแต่ฉันต้องเสียใจที่บอกคุณว่า...",
  ui_story_5035_50350401_93_dialog_content = "การพัฒนาในปัจจุบันนี้ไม่อยู่ในข้อตกลงใดๆ ของฉัน",
  ui_story_5035_50350401_94_dialog_content = "ฟังให้ดีตอนนี้: คำถามที่ 1 ใครเป็นเจ้าของคฤหาสน์นี้?",
  ui_story_5035_50350401_95_option_content = "เลดี้แอสเตอร์",
  ui_story_5035_50350401_96_dialog_content = "ไม่อยากจะเชื่อเลย...",
  ui_story_5035_50350401_97_dialog_content = "คุณลืมไปหมดแล้วว่าใครเป็นผู้ให้ชีวิตใหม่ในบ้านหลังนี้",
  ui_story_5035_50350401_98_dialog_content = "แย่จังที่คุณจะไม่มีโอกาสขอโทษเธอด้วยตัวเองในตอนนี้",
  ui_story_5035_50350401_99_dialog_content = "อย่าลืมคิดถึงคุณนีน่า PlayerName...",
  ui_story_5035_50350401_100_option_content = "นางสาวนีน่า",
  ui_story_5035_50350401_101_dialog_content = "ไม่อยากจะเชื่อเลย...",
  ui_story_5035_50350401_102_dialog_content = "คุณละเลยเจ้าของเดิมโดยสิ้นเชิง",
  ui_story_5035_50350401_103_dialog_content = "คุณสามารถแสดงความเคารพเมื่อคุณเห็นเธอในนรก",
  ui_story_5035_50350401_104_dialog_content = "ฉันเล่าเรื่องของ Lady Astor ให้คุณฟังเมื่อสิบนาทีที่แล้ว PlayerName...",
  ui_story_5035_50350401_105_dialog_content = "ไม่ยุติธรรม! นี่เป็นสถานการณ์ที่ไม่ชนะ!",
  ui_story_5035_50350401_106_dialog_content = "คำถามที่ 2 คฤหาสน์นี้มีกี่ประตู?",
  ui_story_5035_50350401_107_dialog_content = "(ดี คำถามที่ควรมีคำตอบที่เป็นรูปธรรม...)",
  ui_story_5035_50350401_108_dialog_content = "ฉันไว้ใจคุณ ไมนอส",
  ui_story_5035_50350401_109_dialog_content = "โชคดีที่ฉันมีแผนที่บ้านไว้เผื่อไว้ ให้ฉันตรวจสอบก่อน...",
  ui_story_5035_50350401_110_dialog_content = "ใครจะรู้ว่า? ฉันไม่คิดว่าแม้แต่คุณทำ คุณหน้ากากคืบคลาน!",
  ui_story_5035_50350401_111_dialog_content = "...",
  ui_story_5035_50350401_112_dialog_content = "อ๊ะ ไม่นะ!",
  ui_story_5035_50350401_113_dialog_content = "ไม่ตอบก็ยังเป็นคำตอบ เสียดายที่มันผิด",
