  ui_story_5035_50350401_115_dialog_content = "คุณควรพิจารณาว่าผู้ดูของฉันจะคิดอย่างไรเกี่ยวกับคุณหลังจากที่วิดีโอของฉันเผยแพร่",
  ui_story_5035_50350401_116_dialog_content = "ในอัตรานี้ เราถูกเมาถ้าเราไม่สามารถตอบคำถามสุดท้ายได้ถูกต้อง...",
  ui_story_5035_50350401_117_dialog_content = "คำถามที่ 3 ไม่มีกุญแจอยู่ใต้ทีวี",
  ui_story_5035_50350401_118_dialog_content = "อะไร นั่นเป็นคำถามหรือคำพูด?",
  ui_story_5035_50350401_119_dialog_content = "เพื่อความปลอดภัย ยังไงก็เช็ค PlayerName.",
  ui_story_5035_50350401_120_dialog_content = "ให้ฉันทำมัน!",
  ui_story_5035_50350401_121_dialog_content = "อ๊ะ!",
  ui_story_5035_50350401_122_dialog_content = "กุญแจ! นี้ดูเหมือน...ง่ายหลอกลวง",
