  ui_story_5035_50350401_125_dialog_content = "ยินดีด้วยที่ทำอะไรไม่ถูก ตอนนี้มัน <color=#FFB400>เวลาลงโทษ</color>.",
  ui_story_5035_50350401_126_dialog_content = "อะไรนะ!",
  ui_story_5035_50350401_127_dialog_content = "นี่มันบ้าไปแล้ว... คุณทำอะไรไม่ได้ ไมนอส?",
  ui_story_5035_50350401_128_dialog_content = "ใช่ มีทางลับหรือกุญแจสำรองไม่ใช่หรือ?",
  ui_story_5035_50350401_129_dialog_content = "เป็นจังหวะที่เหมาะที่สุดสำหรับการคัมแบ็ก!",
  ui_story_5035_50350401_130_dialog_content = "<color=#e8d9bb>ครืนน... ครืนน...</color>",
  ui_story_5035_50350401_131_dialog_content = "ฉันคิดว่ามีบางอย่างกำลังมาทางนี้",
  ui_story_5035_50350401_132_dialog_content = "ฉันจะเก็บเรื่องนี้ไว้สั้น ๆ ฉันแค่มีข้อเสนอแนะหนึ่งข้อ—",
  ui_story_5035_50350401_133_dialog_content = "ก๊าาาซ!",
  ui_story_5035_50350401_134_dialog_content = "<anim type=Shake><size=45>กรร!</size></anim>",
  ui_story_5035_50350401_135_dialog_content = "มันพังประตูลง วิ่งเดี๋ยวนี้!",
  ui_story_5035_50350501_1_dialog_content = "กรร...",
  ui_story_5035_50350501_2_dialog_content = "ถึงเวลาของฉันที่จะส่องแสง!",
  ui_story_5035_50350501_3_dialog_content = "กรร...",
  ui_story_5035_50350501_4_dialog_content = "(อืม Eclipsite นี้ให้ความรู้สึกนุ่มนวลเมื่อต่อย...)",
  ui_story_5035_50350501_5_dialog_content = "(มันเหมือนกับว่าฉันกำลังตีเบาะที่นุ่มมาก!)",
  ui_story_5035_50350501_6_dialog_content = "เดี๋ยวก่อน ฉันต้องจดจ่อและอย่าฟุ้งซ่าน!",
  ui_story_5035_50350501_7_dialog_content = "จู่โจม เซลลูโล!",
  ui_story_5035_50350501_8_dialog_content = "แกรห์!",
  ui_story_5035_50350501_9_dialog_content = "(มันล้มลงก่อนจะโดน! มันคือ... ตั้งใจทำเหรอ?)",
  ui_story_5035_50350501_10_dialog_content = "ไม่ได้คาดหวังว่าคุณจะดีขนาดนี้",
  ui_story_5035_50350501_11_dialog_content = "ฮึ่ม!",
  ui_story_5035_50350501_12_dialog_content = "ก็ฉันน่ะสิ!",
  ui_story_5035_50350501_13_dialog_content = "ฉันหมายถึง ฉันเป็นกัปตันทีมสำรวจ",
  ui_story_5035_50350501_14_dialog_content = "ที่นี่เรามีความก้าวหน้า! Into the Haunted House เริ่มน่าสนใจแล้ว!",
  ui_story_5035_50350501_15_dialog_content = "*Squeal* ประสบการณ์ที่ตัวละครหลักเท่านั้นที่จะเผชิญ!",
  ui_story_5035_50350501_16_dialog_content = "มาชาร์จกันเถอะ PlayerName!",
  ui_story_5035_50350501_17_dialog_content = "ได้เลย!",
  ui_story_5035_50350501_18_dialog_content = "<color=#e8d9bb>แผละ!</color>",
  ui_story_5035_50350501_19_dialog_content = "โอ๊ย...",
  ui_story_5035_50350501_20_dialog_content = "เดี๋ยวก่อน คุณ...",
  ui_story_5035_50350501_21_dialog_content = "จบเกม.",
  ui_story_5035_50350501_22_dialog_content = "?!",
  ui_story_5035_50350501_23_dialog_content = "(นั่นคือ <color=#FFB400>ของเธอ</color> เสียง.)",
  ui_story_5035_50350501_24_dialog_content = "II- จิตวิญญาณของเทปวิดีโอปรากฏขึ้นหรือไม่?",
  ui_story_5035_50350501_25_dialog_content = "ฉันขอโทษที่เรียกคุณว่าครีพหน้ากาก!",
  ui_story_5035_50350501_26_dialog_content = "อย่างที่คุณเห็น ผู้ชม นี่คือผีตัวหนึ่งที่ซ่อนอยู่ในบ้าน",
  ui_story_5035_50350501_27_dialog_content = "กล้องสั่นเล็กน้อย แต่การเปิดเผยอาถรรพณ์เป็นหน้าที่ของฉัน",
  ui_story_5035_50350501_28_dialog_content = "ฉันจะไม่ถอยด้วยความกลัวอย่างง่ายดาย และ...",
  ui_story_5035_50350501_29_dialog_content = "ฉัน... II จะก้าวเข้าไปใกล้อีกก้าวหนึ่งเพื่อให้คุณมองเห็นได้ชัดเจนยิ่งขึ้น",
  ui_story_5035_50350501_30_dialog_content = "ก-และอีกขั้น...",
  ui_story_5035_50350501_31_dialog_content = "...",
  ui_story_5035_50350501_32_dialog_content = "ได้โปรดกลับมาเดี๋ยวนี้ ลิลิก้า!",
  ui_story_5035_50350501_33_dialog_content = "รอง, PlayerName, ถ้าเรื่องเลวร้ายเกิดขึ้นกับฉัน โปรดบันทึก...",
  ui_story_5035_50350501_34_dialog_content = "พวกคุณทุกคน...",
  ui_story_5035_50350501_35_dialog_content = "*ร้องไห้...*",
  ui_story_5035_50350501_36_dialog_content = "ไม่มีทางหนีพ้น",
  ui_story_5035_50350501_37_dialog_content = "<color=#e8d9bb>ฉวัดเฉวียน...!</color>",
  ui_story_5035_50350501_38_dialog_content = "ส-ดังนั้น สุริยุปราคา *กำลัง* เลื่อยอยู่?!",
  ui_story_5035_50350501_39_dialog_content = "(เดี๋ยวก่อน ทำไมฉันถึงคาดหวังสิ่งนี้ตั้งแต่แรก?)",
  ui_story_5035_50350501_40_dialog_content = "ไปเถอะ เด็กๆ และทำให้พวกเขากรีดร้อง",
  ui_story_5035_50350502_1_dialog_content = "(นี่เป็นเรื่องแปลก แต่ฉันจะไม่มีวันเชื่อในการมีอยู่ของอาถรรพณ์)",
  ui_story_5035_50350502_2_dialog_content = "(หากเอนทิตีที่ปิดบังสามารถควบคุม Eclipsites ได้ แสดงว่าอาจเกี่ยวข้องกับ Eclipse)",
  ui_story_5035_50350502_3_dialog_content = "(แต่ฉันไม่รู้สึกถึง Darkflow จากมัน)",
  ui_story_5035_50350502_4_dialog_content = "(มันอาจเป็นอาถรรพณ์ในกำเนิดจริงๆหรือ?)",
  ui_story_5035_50350502_5_dialog_content = "น้ำวนเชี่ยวกราก!",
  ui_story_5035_50350502_6_dialog_content = "<color=#e8d9bb>ฟิ้วววว!</color>",
  ui_story_5035_50350502_7_dialog_content = "(มันกำลังหลบการโจมตีของฉัน!)",
  ui_story_5035_50350502_8_dialog_content = "อีกครั้ง! ทอร์เรนต์ด่วน...",
  ui_story_5035_50350502_9_dialog_content = "รอเดี๋ยวสิ",
  ui_story_5035_50350502_10_dialog_content = "หา?",
  ui_story_5035_50350502_11_dialog_content = "เท่าที่ฉันจะทำก่อนที่ใครบางคนจะได้รับบาดเจ็บสาหัส",
  ui_story_5035_50350502_12_dialog_content = "จริงอยู่ว่า",
  ui_story_5035_50350502_13_dialog_content = "เออ เลิกกันแล้ว",
  ui_story_5035_50350502_14_dialog_content = "มันร้อนมากในชุดนี้",
  ui_story_5035_50350502_15_dialog_content = "คอร์กอน คุมะ เพนจี้?!",
  ui_story_5035_50350502_16_dialog_content = "นี่หมายความว่าเอนทิตีที่ปิดบังคือ...",
