  ui_story_5035_50350502_21_dialog_content = "ฉันเดาเอาเองว่าไม่มีใครรู้นอกจากนายไมนอส?",
  ui_story_5035_50350502_22_dialog_content = "ไม่น่าแปลกใจที่ Minos บอกให้ฉันหยุดถ่ายทำเมื่อการต่อสู้จบลง",
  ui_story_5035_50350502_23_dialog_content = "ฉันคิดว่ามันเป็นข้อห้ามบางอย่าง แต่เขาแค่ปกป้องความลับทางการค้า!",
  ui_story_5035_50350502_24_dialog_content = "ให้ฉันได้ปกป้องตัวเอง ทั้งหมดนี้เป็นแผนของคุณนีน่าสำหรับกิจกรรมบ้านผีสิง",
