  ui_story_5035_50350502_35_dialog_content = "เข้าใจแล้ว",
  ui_story_5035_50350502_36_dialog_content = "ไม่ต้องพูดถึงพวกออโรเรียนกึ่งมนุษย์ที่เล่นสุริยุปราคา—",
