  ui_story_5035_50350502_49_dialog_content = "โฮะโฮะโฮะโฮะโฮะ!",
  ui_story_5035_50350502_50_dialog_content = "(เป็นวิธีที่น่าหัวเราะในการใช้กล้องรักษาความปลอดภัยที่หายากและมีราคาแพง...)",
  ui_story_5035_50350502_51_dialog_content = "(ดูเหมือนเธอจะปลุกความสุขแปลกๆ ขึ้นมาได้...)",
  ui_story_5035_50350502_52_dialog_content = "เข้าใจแล้ว. อย่างน้อยไอเดียก็แข็งแกร่งกว่าคอมมิชชั่นของจอนนี่",
