  ui_story_5035_50350502_61_dialog_content = "มีอะไรผิดปกติรอง? ในฐานะหัวหน้าหน่วย ฉันรู้สึกว่าคุณค่อนข้างอ่อนแอ!",
  ui_story_5035_50350502_62_dialog_content = "นั่นเป็นเพราะฉันตั้งตารอสิ่งนี้ตั้งแต่ฉันเห็นมันในกระดาษ",
  ui_story_5035_50350502_63_dialog_content = "การได้เห็นการเปิดเผยนั้นรู้สึกแย่พอๆ กับการเรียนรู้เคล็ดลับเบื้องหลังมายากล",
  ui_story_5035_50350502_64_dialog_content = "(ฉันเห็นว่านี่อาจเป็นการลดลงอย่างมากสำหรับ Vice...)",
