  ui_story_5035_50350601_13_dialog_content = "อืมพรมเปียกและแห้งมาก",
  ui_story_5035_50350601_14_dialog_content = "ขอโทษด้วยกับเรื่องนั้น! พยายามที่จะไม่ลื่น",
  ui_story_5035_50350601_15_dialog_content = "ช่วงนี้อากาศชื้นมาก เราจะปรับปรุงการระบายอากาศต่อไป",
  ui_story_5035_50350601_16_dialog_content = "ความชื้นทั้งหมดนี้จะไม่ทำงาน มันจะทำลายเครื่องประดับเล็ก ๆ ทั้งหมดที่นี่",
