  ui_story_5035_50350601_19_dialog_content = "ด้วยความเคารพ คุณนีน่ายังคงรักษาห้องไว้เหมือนเดิม",
  ui_story_5035_50350601_20_dialog_content = "ด้วยวิธีนี้แขกสามารถชื่นชมรสชาติของเจ้าของเดิมได้เช่นกัน",
  ui_story_5035_50350601_21_dialog_content = "เป็นทางเลือกที่ดีในการใช้สถานที่นี้เป็นสถานที่ถ่ายทำ",
