  ui_story_5035_50350601_24_dialog_content = "มันเป็นแค่หุ่นเชิดเหล่านี้... พวกมันดูประหลาดมาก",
  ui_story_5035_50350601_25_dialog_content = "โอ้ต้องปัดฝุ่นอย่างดีด้วย ทำความสะอาดยากเมื่อฝุ่นสะสม...",
  ui_story_5035_50350601_26_dialog_content = "อืม... คุณ Vice ได้โปรดอย่าสร้างปัญหาให้ตัวเองเกินควร คุณคือแขกของเรา",
  ui_story_5035_50350601_27_dialog_content = "ไม่เป็นไร. ตอนนี้มันสะอาดและเป็นระเบียบเรียบร้อย!",
