  ui_story_5035_50350601_30_dialog_content = "คุณลิลิก้า มายืนข้างประตูทำไม? มีอะไรให้ฉันช่วยไหม",
  ui_story_5035_50350601_31_dialog_content = "ฉัน เอ่อ กำลังรอปรากฏการณ์เหนือธรรมชาติเกิดขึ้น!",
  ui_story_5035_50350601_32_dialog_content = "(คุณรอได้แค่นี้เองเหรอ?!)",
  ui_story_5035_50350601_33_dialog_content = "อี๊ก!",
  ui_story_5035_50350601_34_dialog_content = "โธ่เอ๋ย— มีอะไรเกิดขึ้นหรือเปล่า? มีไหม",
  ui_story_5035_50350601_35_dialog_content = "ฉันไม่ได้สังเกตก่อนหน้านี้ แต่มีการ์ดซ่อนอยู่ตรงกลางของหุ่นเหล่านี้",
  ui_story_5035_50350601_36_dialog_content = "เอ่อ... เป็นอีกหนึ่งอุปกรณ์ประกอบฉากสยองขวัญของนีน่าหรือเปล่า?",
  ui_story_5035_50350601_37_dialog_content = "ฉันคิดอย่างนั้น. มีบทกวีสั้น ๆ แปลก ๆ ที่เขียนไว้",
  ui_story_5035_50350601_38_dialog_content = "เอ่อ ช่วยขยับเข้าไปใกล้กว่านี้หน่อยได้ไหม? อยากได้ติดกล้อง.",
  ui_story_5035_50350601_39_dialog_content = "ในกรณีนี้ คุณถือไว้ คุณสามารถอ่านให้ทุกคนดูได้",
  ui_story_5035_50350601_40_dialog_content = "ก-ก็ได้ ฉันจะอ่านมันแล้ว แค่บอกให้หยุดถ้าใครกลัว!",
  ui_story_5035_50350601_41_dialog_content = "“หนึ่งน้อย สองน้อย...”",
  ui_story_5035_50350601_42_dialog_content = "<color=#e8d9bb>*กล่องดนตรีไขมีเสียง*</color>",
  ui_story_5035_50350601_43_dialog_content = "“หนึ่ง ตัวเล็ก สอง ตัวเล็ก สามตัว ♪”",
  ui_story_5035_50350601_44_dialog_content = "“สี่ตัวเล็ก ห้าตัว หกตัว ♪”",
  ui_story_5035_50350601_45_dialog_content = "\"เจ็ดตัวเล็ก แปดตัว เก้าหุ่น ♪\"",
  ui_story_5035_50350601_46_dialog_content = "“เก้าหุ่น—แต่แค่แปดหัวเล็ก ♪”",
  ui_story_5035_50350601_47_dialog_content = "<color=#e8d9bb>ดริป...ดริป...</color>",
  ui_story_5035_50350601_48_dialog_content = "T-บันทึกนี้...",
  ui_story_5035_50350601_49_dialog_content = "มันห่วยเกินไปต่างหาก!",
  ui_story_5035_50350601_50_dialog_content = "ฮ่าๆ ดูเหมือนลูกเล่นของ Miss Nina จะค่อนข้างโปร่งใส",
  ui_story_5035_50350601_51_dialog_content = "เป็นการ์ดใบนี้ที่กระตุ้นการบันทึก",
  ui_story_5035_50350601_52_dialog_content = "วุ้ย... มันทำให้ฉันตกใจจริงๆ",
  ui_story_5035_50350601_53_dialog_content = "เธอก็เลยกลัวเหมือนกัน ห๊ะ ลิลิก้า?",
  ui_story_5035_50350601_54_dialog_content = "ฉันว่ามันตื่นเต้นมากกว่ากลัว",
  ui_story_5035_50350601_55_dialog_content = "ไม่ต้องห่วง. ด้วยจิตวิญญาณแห่ง Swashbuckler's Way ฉันสามารถช่วยปกป้องคุณได้หากคุณกลัว",
  ui_story_5035_50350601_56_dialog_content = "แน่นอนว่าฉันต้องเสียค่าบริการ",
  ui_story_5035_50350601_57_dialog_content = "คุณคงเห็นเองแล้วว่าทั้งหมดนี้เป็นของปลอมและทำได้ไม่ดี",
  ui_story_5035_50350601_58_dialog_content = "คุณภาพเสียงไม่ดี และจังหวะของเสียงหยดในพื้นหลังปิดอยู่ ไม่ต้องพูดถึงเพลงบัลลาดที่คล้องจองกัน",
  ui_story_5035_50350601_59_dialog_content = "มันยังคงวนซ้ำไปมาเหมือนแผ่นเสียงที่พังทลายเช่นกัน",
  ui_story_5035_50350601_60_dialog_content = "ขอขอบคุณสำหรับคำแนะนำของคุณ. ฉันจะปรับปรุงข้อตกลงนี้กับคุณนีน่าต่อไป ส่วน...",
  ui_story_5035_50350601_61_dialog_content = "<color=#e8d9bb>*หยุดเทป*</color>",
  ui_story_5035_50350601_62_dialog_content = "แปลก เหตุใดการบันทึกจึงหยุดลง",
  ui_story_5035_50350601_63_dialog_content = "ม-คงไม่ใช่เพราะจิตวิญญาณของการบันทึกได้ยินสิ่งที่เราพูดใช่ไหม?",
  ui_story_5035_50350601_64_dialog_content = "ฉันจะไปดูในห้องควบคุม ได้โปรดทุกคนอยู่ที่นี่สักครู่ได้ไหม?",
  ui_story_5035_50350601_65_dialog_content = "(ปฏิกิริยาของลิลิก้าทำได้ 180...)",
  ui_story_5035_50350601_66_dialog_content = "อย่ากลัวไปเลย ลิลิก้า มันเป็นเรื่องบังเอิญที่มันหยุดลง",
  ui_story_5035_50350601_67_dialog_content = "ไม่ใช่ว่าเราสามารถหยุดและเริ่มต้นได้ตามต้องการ",
  ui_story_5035_50350601_68_dialog_content = "ต-นั่นสินะ เช่น แม้ว่าเราจะตะโกนว่า \"เล่น!\" ตอนนี้คงไม่มีอะไร...",
  ui_story_5035_50350601_69_dialog_content = "<color=#e8d9bb>*กล่องดนตรีไขมีเสียง*</color>",
  ui_story_5035_50350601_70_dialog_content = "“หนึ่ง ตัวเล็ก สอง ตัวเล็ก สามตัว ♪”",
  ui_story_5035_50350601_71_dialog_content = "“สี่ตัวเล็ก ห้าตัวเล็ก ♪”",
  ui_story_5035_50350601_72_dialog_content = "อะ-อะแฮ่ม!!!! มันกลับมาแล้ว!",
  ui_story_5035_50350601_73_dialog_content = "... ใจเย็น ๆ! เพียงแค่ฟังคำพูด ไม่มีอะไรเปลี่ยนแปลงหลังจากคำวิจารณ์ของฉัน",
  ui_story_5035_50350601_74_dialog_content = "ฉันเดาว่าคงเป็นเพราะไมนอสสามารถแก้ไขการบันทึกได้ใช่ไหม",
  ui_story_5035_50350601_75_dialog_content = "มันคงเป็น...",
  ui_story_5035_50350601_76_dialog_content = "<color=#e8d9bb>ดริป...ดริป...</color>",
  ui_story_5035_50350601_77_dialog_content = "<color=#e8d9bb>หยด หยด... หยด...</color>",
  ui_story_5035_50350601_78_dialog_content = "ฟังนะ จังหวะการหยดเปลี่ยนไป",
  ui_story_5035_50350601_79_dialog_content = "นั่นเป็นสิ่งที่ Minos สามารถปรับได้ตามต้องการ อย่างรวดเร็วจริงๆ... ใช่ไหม?",
  ui_story_5035_50350601_80_dialog_content = "อืม... ไม่ ฉันวิ่งไม่ได้!",
  ui_story_5035_50350601_81_dialog_content = "(เธอยังคงรับผิดชอบเมื่อดันมาผลัก!)",
  ui_story_5035_50350601_82_dialog_content = "ฉันจะออกไปจากที่นี่อย่างช้าๆ ช้าๆ โดยไม่ทำให้กล้องสั่น...",
  ui_story_5035_50350601_83_dialog_content = "...",
  ui_story_5035_50350601_84_dialog_content = "ฟู่!",
  ui_story_5035_50350601_85_dialog_content = "แม้ว่าหัวใจของฉันจะอยู่ในลำคอ แต่โชคดีที่ไม่มีอะไรเกิดขึ้น",
  ui_story_5035_50350601_86_dialog_content = "ตอนนี้ฉันใจเย็นลงแล้ว ฉันมีปัญหาอื่นที่ต้องพิจารณา!",
  ui_story_5035_50350601_87_dialog_content = "แล้วการทำเพลงบัลลาดนั้นเป็นเพลงประกอบของเทปล่ะ?",
  ui_story_5035_50350601_88_dialog_content = "เมื่อกี้ลืมถ่ายโชว์รูม!",
  ui_story_5035_50350601_89_dialog_content = "คุณฟื้นตัวเร็วมาก",
  ui_story_5035_50350601_90_dialog_content = "ตี๋!",
  ui_story_5035_50350601_91_dialog_content = "หา?!",
  ui_story_5035_50350601_92_dialog_content = "อุ๊ย! ใครตบไหล่ฉัน!",
  ui_story_5035_50350601_93_dialog_content = "ขอโทษค่ะ บาบายากะ",
  ui_story_5035_50350601_94_dialog_content = "ฉันต้องขอโทษคุณแทนเธอ ฉันหวังว่ามันจะไม่เจ็บ PlayerName?",
  ui_story_5035_50350601_95_dialog_content = "ไม่เป็นไร ไม่เป็นไร ฉันตกใจมากกว่าเจ็บ",
  ui_story_5035_50350601_96_dialog_content = "ทำไมคุณมาที่นี่ด้วย Mia?",
  ui_story_5035_50350601_97_dialog_content = "ฉันมากับบาบายากะ เธอสนใจที่นี่",
  ui_story_5035_50350601_98_dialog_content = "แม้จะพยายามอย่างเต็มที่แล้ว แต่ก็ยังไม่ได้ตั๋วลดราคา...",
  ui_story_5035_50350601_99_dialog_content = "ฉันบอกคุณถึงตาฉันแล้วที่จะโต้เถียงกับสาวขายตั๋ว!",
  ui_story_5035_50350601_100_dialog_content = "เฮ้, PlayerName, Mia ก็ขี้อายเหมือนเดิมใช่ไหม?",
  ui_story_5035_50350601_101_dialog_content = "เดาว่าเป็นชะตากรรมที่เราพบคุณที่นี่!",
  ui_story_5035_50350601_102_dialog_content = "และการแสดงออกนั้นเมื่อคุณถูกแทงด้วยกรงเล็บเหล็กเหล่านี้... น่ารักมาก!",
  ui_story_5035_50350601_103_dialog_content = "บาบายากะ—และเมีย—อยู่ข้างหลังคุณ...!",
  ui_story_5035_50350601_104_dialog_content = "โอ้?! และนิพจน์นี้คืออะไร?",
  ui_story_5035_50350601_105_dialog_content = "หน้าฉัน... น่ากลัวขนาดนั้นเลยเหรอ...?",
  ui_story_5035_50350601_106_dialog_content = "เกรย์!!!",
  ui_story_5035_50350601_107_dialog_content = "อ๊าาาา!",
  ui_story_5035_50350601_108_dialog_content = "สุริยุปราคาไม่มีอะไรต้องกลัว!",
  ui_story_5035_50350601_109_dialog_content = "กฎข้อที่สองของวิถี Swashbucklers: อย่าวิ่งเมื่อมีคนมีปัญหา จงช่วยเหลือเมื่อคุณควร!",
  ui_story_5035_50350601_110_dialog_content = "แค่ดูฉันแกว่ง Coolster อย่างเจ้านาย!",
  ui_story_5035_50350702_1_dialog_content = "Pff... อะไรกับการตะโกนใส่ Eclipsites สองสามตัว? ไม่เข้าใจ ไม่เอาเลย",
  ui_story_5035_50350702_2_dialog_content = "ยอดเยี่ยมมาก คุณทรมาน! ฉันขอถ่ายรูปคุณอีกสองสามภาพจากมุมต่างๆ ได้ไหม",
  ui_story_5035_50350702_3_dialog_content = "ฮี่ฮี่ฮี่ฮี่... เป็นแขกของฉัน!",
  ui_story_5035_50350702_4_dialog_content = "แต่อย่าลืมโพสต์ต่อสาธารณะ มีอา เด็กผู้หญิงคนนั้น ดูเหมือนจะไม่ชอบไฟแก็ซ",
  ui_story_5035_50350702_5_dialog_content = "ไม่อย่างนั้น... ฉันแค่ต้องทุบกล้องของคุณกับสิ่งเล็กๆ ข้างๆ คุณ",
  ui_story_5035_50350702_6_dialog_content = "เอ่อ... ก-เข้าใจแล้ว!",
  ui_story_5035_50350702_7_dialog_content = "เฮ้ ไม่ต้องขนาดนั้น...",
  ui_story_5035_50350702_8_dialog_content = "ฉันเสียใจ. เราไม่ได้ตั้งใจจะขู่คุณ...",
  ui_story_5035_50350702_9_dialog_content = "ทุกอย่างปกติดี! ฉันเคารพความปรารถนาของอาสาสมัครเสมอ!",
  ui_story_5035_50350702_10_dialog_content = "ทุกคนสบายดีไหม",
  ui_story_5035_50350702_11_dialog_content = "ฉันได้ยินเสียงความโกลาหลจากชั้นล่าง โชคดีที่ดูเหมือนว่าจะเป็นแค่ Eclipsites สองสามตัว",
  ui_story_5035_50350702_12_dialog_content = "ความผิดปกติกับการบันทึกในโชว์รูมได้รับการซ่อมแซมแล้ว ดังนั้นหากท่านต้องการจะกลับเข้า...",
  ui_story_5035_50350702_13_dialog_content = "ไม่! เอ่อ ไม่ต้องหรอก ฮ่าๆๆ...",
  ui_story_5035_50350702_14_dialog_content = "ไปกดสถานที่ต่อไปกันเถอะ!",
  ui_story_5035_50350702_15_dialog_content = "หากเป็นกรณีนี้ ฉันจะบอกลาทุกคนในตอนนี้",
  ui_story_5035_50350702_16_dialog_content = "ตั้งแต่รู้จักกันมา ฉันเลยต้องถาม...",
  ui_story_5035_50350702_17_dialog_content = "คุณ เอ่อ... คุณทั้งคู่สนใจที่จะเข้าร่วมทีมสำรวจของเราไหม",
  ui_story_5035_50350702_18_dialog_content = "ไม่เป็นไรขอบคุณ. เพราะ... บาบายากะชอบที่จะสัมผัสที่นี่คนเดียว",
  ui_story_5035_50350702_19_dialog_content = "ยังไงก็ดูแลตัวเองดีๆนะ!",
  ui_story_5035_50350702_20_dialog_content = "เดี๋ยว. มีเรื่องอยากจะบอก",
  ui_story_5035_50350702_21_dialog_content = "PlayerName—ฉันไม่เห็น <color=#FFB400>ของเธอ</color> กับคุณ.",
  ui_story_5035_50350702_22_dialog_content = "เหมือนจะเจอ <color=#FFB400>ของเธอ</color> ต่อหน้าท่านทั้งหลาย",
  ui_story_5035_50350702_23_dialog_content = "... เธอ ใคร?",
  ui_story_5035_50350702_24_dialog_content = "ใช่แม้ว่า <color=#FFB400>เธอ</color> และฉันก็มีปัญหาในการพบปะเช่นกัน",
  ui_story_5035_50350702_25_dialog_content = "ผิดหวังนิดหน่อยที่ไม่ได้ดู <color=#FFB400>ของเธอ</color> ที่นี่กับคุณ—",
  ui_story_5035_50350702_26_dialog_content = "ก-คุณกำลังพูดถึงใครกันแน่...?",
  ui_story_5035_50350702_27_dialog_content = "ฮิฮิ! แค่ล้อเล่น! มีอากับฉันหา <color=#FFB400>ของเธอ</color> ตัวเราเอง.",
  ui_story_5035_50350702_28_dialog_content = "อย่างไรก็ตาม, PlayerNameฉันต้องเตือนคุณ—",
  ui_story_5035_50350702_29_dialog_content = "<color=#FFB400>ระวัง. อย่าให้นางจับ...</color>",
  ui_story_5035_50350702_30_dialog_content = "เพราะมีเพียงฉันเท่านั้นที่ทำได้ <color=#FFB400>ลากเธอเข้าไปในงานเลี้ยงแห่งความรัก</color>",
  ui_story_5035_50350702_31_dialog_content = "อะไร เอ่อ... คุณหมายความว่าอย่างไรโดยที่?",
  ui_story_5035_50350702_32_dialog_content = "ฮิฮิฮิ! การแสดงออกที่หายไปโดยสิ้นเชิงนั้นช่างน่ารักเหลือเกิน!",
  ui_story_5035_50350702_33_dialog_content = "ยังไงก็เจอกันใหม่นะ!",
  ui_story_5035_50350702_34_dialog_content = "เอาล่ะตอนนี้จริงๆ...",
  ui_story_5035_50350702_35_dialog_content = "ทำไมเจ้าของบ้านผีสิงไม่ชวนมาเขียนเรื่องสยอง...",
  ui_story_5035_50350702_36_dialog_content = "เธอไปซะแล้ว...",
  ui_story_5035_50350702_37_dialog_content = "(ใครในโลกที่บาบายากะพูดถึง? มันเป็นไปไม่ได้...)",
  ui_story_5035_50350702_38_dialog_content = "(แต่ดูเหมือนเธอจะไม่อยากอธิบายเพิ่มเติม...)",
  ui_story_5035_50350702_39_dialog_content = "(ไม่เป็นไรบางทีฉันอาจจะคิดออกในที่สุด)",
  ui_story_5035_50350702_40_dialog_content = "สำหรับเพื่อนๆ ทุกคนที่รับชมรายการนี้ทางทีวีในอนาคต นี่คือ Caelestite คนสุดท้ายในตำนาน",
  ui_story_5035_50350702_41_dialog_content = "และเธอเป็นสาวเพชฌฆาตที่เดินตามส่วนลึกของบ้าน",
  ui_story_5035_50350702_42_dialog_content = "คำพูดที่คลุมเครือและคลุมเครือเช่นนั้นจะเกิดผลอย่างไร...?",
  ui_story_5035_50350702_43_dialog_content = "อย่าเพิ่งแต่งหน้านะ ลิลิก้า!",
  ui_story_5035_50350702_44_dialog_content = "ฮ่าฮ่า เข้าใจแล้ว! ฉันไม่ได้บันทึกด้วยซ้ำ!",
  ui_story_5035_50350702_45_dialog_content = "เดี๋ยวก่อน อดทนไว้... ความสนุกจบลงแล้ว เราต้องเดินหน้าต่อไป",
  ui_story_5035_50350702_46_dialog_content = "มีชั้นใต้ดินรออยู่ เราไปกันเถอะ",
  ui_story_5035_50350702_47_dialog_content = "คุณดูเด็ก แต่ดูสงบและเป็นมืออาชีพมาก",
  ui_story_5035_50350702_48_dialog_content = "?!",
  ui_story_5035_50350702_49_dialog_content = "เปล่าหรอก... ก-ไอ้พวกสวอชบัคเลอร์ที่เจ๋งที่สุดก็เป็นแบบนั้น!",
  ui_story_5035_50350702_50_dialog_content = "มาเริ่มกันเลย! ไปที่ห้องใต้ดินเราไป!",
  ui_story_5035_50350702_51_dialog_content = "ฉันจะพาคุณไปต่อ",
  ui_story_5035_50350702_52_dialog_content = "เอาล่ะ! การถ่ายทำ Into the Haunted House ยังคงดำเนินต่อไป!",
  ui_story_5035_50350801_1_dialog_content = "<color=#e8d9bb>บี๊บ!</color>",
  ui_story_5035_50350801_2_dialog_content = "บ้านผีสิงหลังนี้ไม่อยู่ในสถานการณ์ที่ดีที่สุด ไปหาที่สุดท้ายกันเถอะ! ♪",
  ui_story_5035_50350801_3_dialog_content = "แผนภูมิระบุว่าจุดสุดท้ายคือชั้นใต้ดิน คุณบัตเลอร์ ขอรบกวนคุณช่วยชี้ทางให้เราอีกครั้งได้ไหม",
  ui_story_5035_50350801_4_dialog_content = "ซึ่งเมื่อผมเซ็นสัญญากับจอนนี่ พื้นที่ที่สามารถใช้ถ่ายทำในบ้านหลังนี้ได้ถูกกำหนดไว้อย่างชัดเจน",
  ui_story_5035_50350801_5_dialog_content = "และนั่นไม่รวมชั้นใต้ดิน ฉันจะคุยเรื่องค่าธรรมเนียมกับผู้กำกับอีกครั้งในวันพรุ่งนี้",
  ui_story_5035_50350801_6_dialog_content = "มาเถอะ อย่ามาทำลายหนังด้วยการพูดถึงเรื่องเงินกัน เราควรไปได้แล้ว",
  ui_story_5035_50350801_7_dialog_content = "เฮ้ ลิลิก้า คุณกำลังทำอะไรอยู่? ทำต่อไป!",
  ui_story_5035_50350801_8_dialog_content = "แบตเตอรี่ดีและฝาปิดเลนส์ปิดอยู่ สำหรับการโฟกัส...",
