  ui_story_5035_50350801_11_dialog_content = "ใช่ คุณดูเฉียบคมมาก",
  ui_story_5035_50350801_12_dialog_content = "คุณอยากเป็นตากล้องของฉันไหม มันเป็นงานที่สนุก",
  ui_story_5035_50350801_13_dialog_content = "คนถือกล้อง? นั่นไม่ใช่สิ่งที่คุณกำลังทำอยู่เหรอ? คุณต้องการช่างกล้องเพื่ออะไร?",
