  ui_story_5035_50350801_19_dialog_content = "ถ้าคุณสร้างความเสียหาย ใครจะบอกคุณว่าคุณไม่จำเป็นต้องจ่ายไนเทียมหลายสิบล้านล้านให้ฉัน",
