  ui_story_5035_50350801_110_dialog_content = "เด็กคนหนึ่งโดนทำโทษ อีกคนยืนฟังอยู่ตรงมุม...",
  ui_story_5035_50350801_111_dialog_content = "นั่นมันบิดเบี้ยวจริงๆ ฉันหวังว่ามัน... ไม่เคยเกิดขึ้นจริง",
  ui_story_5035_50350801_112_dialog_content = "ตัดสินโดยลายมือ บันทึกเหล่านี้เขียนโดยเด็ก",
  ui_story_5035_50350801_113_dialog_content = "บางทีพวกเขาอาจจะแค่สร้างเรื่องขึ้นมา?",
  ui_story_5035_50350801_114_dialog_content = "ฉันเกรงว่าจะไม่. มาดูเศษกระดาษส่วนอื่นๆ กันบ้าง",
  ui_story_5035_50350801_115_dialog_content = "มีเขียนอยู่ทั้งหมด และพวกเขาทั้งหมดพูดสิ่งที่คล้ายกัน",
  ui_story_5035_50350801_116_dialog_content = "\"นี่เป็นสิ่งเดียวที่คุณต้องจำไว้\"",
  ui_story_5035_50350801_117_dialog_content = "\"เด็กซนจะเป็น <color=#FFB400>ลงโทษ</color> โดยคุณหญิง...\"",
  ui_story_5035_50350801_118_dialog_content = "คุณจะเขียนเรื่องที่สร้างขึ้นมาหลายครั้งหรือไม่?",
  ui_story_5035_50350801_119_dialog_content = "O-แน่นอนไม่",
  ui_story_5035_50350801_120_dialog_content = "ไม่เป็นไรหลายครั้งฉันจะเหนื่อยเขียนครั้งเดียว ฉันจำไม่ได้ด้วยซ้ำว่าฉันอายุเท่าไหร่ครั้งสุดท้ายที่ฉันเขียนอะไรจริงๆ ... อาจจะสิบ?",
  ui_story_5035_50350801_121_dialog_content = "การคัดลอกบางสิ่งหลายครั้งนี้เป็นสิ่งที่ซ้ำซากจำเจ ใครจะอยากทำแบบนั้นบ้าง?",
  ui_story_5035_50350801_122_dialog_content = "ยกเว้นว่า...",
  ui_story_5035_50350801_123_dialog_content = "เว้นแต่จะบังคับ ฉันเข้าใจแล้ว นี่คือการลงโทษ",
  ui_story_5035_50350801_124_dialog_content = "ลงโทษเด็กด้วยการเลียนแบบทั้งหมดนั่น? มันจะไม่เป็น...",
  ui_story_5035_50350801_125_dialog_content = "คุณบัตเลอร์ คุณรู้จักเจ้าของคนก่อนมากแค่ไหน?",
  ui_story_5035_50350801_126_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5035_50350801_127_dialog_content = "คุณบัตเลอร์?",
  ui_story_5035_50350801_128_dialog_content = "ฉันพบอย่างอื่น มาดูที่นี้.",
  ui_story_5035_50350801_129_dialog_content = "โอ้? โน๊ตบุ๊ค?! มันมีสิ่งประเภทเดียวกันกับเศษกระดาษเหล่านั้นหรือไม่?",
  ui_story_5035_50350801_130_dialog_content = "ไม่ สมุดบันทึกนี้ค่อนข้างใหม่ และเพิ่งถูกทิ้งไว้ที่นี่",
  ui_story_5035_50350801_131_dialog_content = "ด้านหน้าเขียนว่า \"Crew Work Record\" และเห็นได้ชัดว่าโปรดิวเซอร์เป็นคนเขียน",
  ui_story_5035_50350801_132_dialog_content = "ผู้ผลิต? นั่นไม่ใช่คุณเหรอ?",
  ui_story_5035_50350801_133_dialog_content = "ฉันจะเขียนมันได้อย่างไร? อาจมีทีมงานภาพยนตร์คนอื่นอยู่ที่นี่ในอดีต",
  ui_story_5035_50350801_134_dialog_content = "อาจจะ. มันเขียนว่าอะไรกันแน่?",
  ui_story_5035_50350801_135_dialog_content = "\"ที่ตั้ง: ห้องนอน\"",
  ui_story_5035_50350801_136_dialog_content = "\"ที่นี่เป็นที่ทิ้งขยะ หน้าต่างและแผ่นฐานทั้งหมดมีลมพัด และหนาวมากจนฉันตัวสั่น\"",
  ui_story_5035_50350801_137_dialog_content = "“ฉันตั้งตารอที่จะดูทีวีจริงๆ ระหว่างรอผู้กำกับ แต่เศษเหล็กที่ไร้ประโยชน์นั้นไม่สามารถจับสัญญาณได้เลย”",
  ui_story_5035_50350801_138_dialog_content = "“และที่แย่ที่สุดคือผู้กำกับไม่แม้แต่จะปรากฏตัว แต่ Eclipsites ก็ปรากฏตัว”",
  ui_story_5035_50350801_139_dialog_content = "“อุปกรณ์ประกอบฉากของเราครึ่งหนึ่งได้รับความเสียหาย และลูกเรือสามคนได้รับบาดเจ็บ ฉันได้บอกผู้กำกับไปแล้วว่าไม่มีทางที่เราจะถ่ายทำที่นี่ได้”",
  ui_story_5035_50350801_140_dialog_content = "ดูเหมือนว่าพวกเขายังอยู่ในห้องนอน",
  ui_story_5035_50350801_141_dialog_content = "ฉันเดาว่าการเจอ Eclipsites ในสถานที่นี้ค่อนข้างธรรมดา... ไม่น่าแปลกใจเลยที่มันออกสู่ตลาดด้วยราคาที่ต่ำเช่นนี้",
  ui_story_5035_50350801_142_dialog_content = "รายการถัดไปยังกล่าวถึงสถานที่ที่คุ้นเคย",
  ui_story_5035_50350801_143_dialog_content = "\"ที่ตั้ง: โชว์รูม\"",
  ui_story_5035_50350801_144_dialog_content = "“ฉันพอแล้ว ถ้าผู้กำกับยืนยันจะถ่ายทำต่อที่นี่ ฉันจะลาออกและกลับบ้าน”",
  ui_story_5035_50350801_145_dialog_content = "\"เพลงบัลลาดที่น่าขนลุกจะไม่หยุด และเสียงหยดที่พระเจ้าทอดทิ้งซึ่งดูเหมือนจะเป็นไปตามจังหวะของมัน\"",
  ui_story_5035_50350801_146_dialog_content = "\"นี่เป็นส่วนหนึ่งของสุนทรียศาสตร์พิเศษของเจ้าของหรือไม่ ถ้าใช่ พวกเขาสมควรได้รับการตบหัว\"",
  ui_story_5035_50350801_147_dialog_content = "“ฉันมาเพื่อถ่ายหนังสยองขวัญ ไม่ได้มาเพื่อเจอผี”",
  ui_story_5035_50350801_148_dialog_content = "เราเคยเจอเหตุการณ์เดียวกันนี้ในโชว์รูม! ทั้งเพลงบัลลาดและเสียงหยดน้ำ เขาได้ยินหมดแล้ว!",
  ui_story_5035_50350801_149_dialog_content = "คุณสาบานไหมว่าคุณไม่ได้เขียนสิ่งนี้ ไมนอส?",
  ui_story_5035_50350801_150_dialog_content = "มันจะไม่น่ากลัวยิ่งขึ้นถ้าฉันเขียนมัน?",
  ui_story_5035_50350801_151_dialog_content = "ม-บางที...",
  ui_story_5035_50350801_152_dialog_content = "แต่แล้วอะไรล่ะ? ใครมีสมุดบันทึกเล่มนั้นมาที่ชั้นใต้ดินด้วย?",
  ui_story_5035_50350801_153_dialog_content = "อ้อ ขอโทษ ถามโง่ๆ เราพบสมุดบันทึกที่นี่",
  ui_story_5035_50350801_154_dialog_content = "ใช่. นี่คือรายการถัดไป",
  ui_story_5035_50350801_155_dialog_content = "\"ที่ตั้ง: ชั้นใต้ดิน\"",
  ui_story_5035_50350801_156_dialog_content = "...",
  ui_story_5035_50350801_157_dialog_content = "อะไร ต่อไป...",
  ui_story_5035_50350801_158_dialog_content = "ดูด้วยตัวคุณเอง",
  ui_story_5035_50350801_159_dialog_content = "ฮะ? อะไรในโลก...",
  ui_story_5035_50350801_160_dialog_content = "...",
  ui_story_5035_50350801_161_dialog_content = "\"เธออยู่ที่นี่\"",
  ui_story_5035_50350801_162_dialog_content = "แค่นี้เองเหรอ",
  ui_story_5035_50350801_163_dialog_content = "ใครอยู่นี่?",
  ui_story_5035_50350801_164_dialog_content = "คิดว่าน่าจะเป็น \"มาดาม\" ที่พูดถึงในเศษกระดาษมั้ย...?",
  ui_story_5035_50350801_165_dialog_content = "ไม่มีข้อมูลอื่น นี่คือทุกอย่างในห้องใต้ดิน",
  ui_story_5035_50350801_166_dialog_content = "ฉันเกรงว่าเราต้องจินตนาการถึงสิ่งที่อาจเกิดขึ้นที่นี่ในอดีต",
  ui_story_5035_50350801_167_dialog_content = "มีอะไรอีกไหมที่คุณอยากเห็น?",
  ui_story_5035_50350801_168_dialog_content = "พูดตรงๆ ฉันอยากออกไปจากที่นี่...",
  ui_story_5035_50350801_169_dialog_content = "ม-ฉันด้วย!",
  ui_story_5035_50350801_170_dialog_content = "รอสักครู่! รอก่อน! ทำไมทุกคนอารมณ์ไม่ดีอย่างนี้?",
  ui_story_5035_50350801_171_dialog_content = "เราเกือบจะห่อเข้าไปในบ้านผีสิงแล้ว! แน่นอนว่านั่นน่าจะเป็นสาเหตุของการเฉลิมฉลอง!",
  ui_story_5035_50350801_172_dialog_content = "ไม่กลัวหรือ พอเห็นหมดแล้ว...?",
  ui_story_5035_50350801_173_dialog_content = "มันทำให้รู้สึกไม่สบายใจเล็กน้อย แต่ยิ่งมีเหตุผลมากขึ้นที่ฉันต้องการอยู่ในเชิงบวก!",
  ui_story_5035_50350801_174_dialog_content = "ไม่เช่นนั้นเราจะกลัวตายก่อนที่สัตว์ประหลาดจะปรากฏตัว!",
  ui_story_5035_50350801_175_dialog_content = "มาถ่ายรูปหมู่กันเถอะ!",
  ui_story_5035_50350801_176_dialog_content = "อะไรนี่? บางทีเราควรออกไปก่อน...",
  ui_story_5035_50350801_177_dialog_content = "แน่นอนที่นี่! มันจะไม่เป็นที่จดจำอย่างอื่น",
  ui_story_5035_50350801_178_dialog_content = "ไม่เลว. ขอสำเนาหน่อยได้ไหม ฉันสามารถใช้มันเพื่อโปรโมตภาพยนตร์เรื่องใหม่",
  ui_story_5035_50350801_179_dialog_content = "ขอสำเนาด้วยครับ มันจะช่วยฉันได้เมื่อฉันเจรจากับเจ้าของบ้าน",
  ui_story_5035_50350801_180_dialog_content = "ดู? ทุกคนอยู่บนเรือ มาเร็ว!",
  ui_story_5035_50350801_181_dialog_content = "ดี. ต้องการให้ฉันไปรับคุณไหม",
  ui_story_5035_50350801_182_dialog_content = "ไม่ไม่ไม่! ภาพถ่ายหมู่ต้องการทุกคนในช็อต",
  ui_story_5035_50350801_183_dialog_content = "เป็นอย่างไรบ้าง—ทุกคนมาหาฉัน ยกเว้น PlayerName.",
  ui_story_5035_50350801_184_dialog_content = "บีบเข้าไป... ยืนใกล้ขึ้นอีกนิด",
  ui_story_5035_50350801_185_dialog_content = "แบบนี้โอเคมั้ย?",
  ui_story_5035_50350801_186_dialog_content = "ใช่! ยอดเยี่ยม! ตอนนี้, PlayerNameวางกล้องบนชั้นวางนั้นแล้วชี้มาที่เรา",
  ui_story_5035_50350801_187_dialog_content = "กดปุ่มชัตเตอร์แล้ววิ่งมาหาเรา เข้าใจแล้ว?",
  ui_story_5035_50350801_188_dialog_content = "อา ฉันคิดว่าฉันเห็นสิ่งที่คุณได้รับ",
  ui_story_5035_50350801_189_dialog_content = "ให้ข้าดู... ตรงนี้น่าจะทำ ชี้มาที่พวกนาย...",
  ui_story_5035_50350801_190_dialog_content = "นี่คือปุ่มชัตเตอร์ใช่ไหม",
  ui_story_5035_50350801_191_dialog_content = "ใช่! ให้นับถอยหลังก่อน เราจะได้เตรียมตัว",
  ui_story_5035_50350801_192_dialog_content = "ได้เลย ฉันเข้าใจแล้ว ทุกคน ดูนี่สิ!",
  ui_story_5035_50350801_193_dialog_content = "นับถอยหลัง! 3... 2... 1...",
  ui_story_5035_50350801_194_dialog_content = "<color=#e8d9bb>แซ่บ!</color>",
  ui_story_5035_50350801_195_dialog_content = "อ๊าก!",
  ui_story_5035_50350801_196_dialog_content = "ว-เกิดอะไรขึ้น? ไฟฟ้าดับ?",
  ui_story_5035_50350801_197_dialog_content = "อุ๊ย มีคนมาเหยียบฉัน",
  ui_story_5035_50350801_198_dialog_content = "โอ้ขอโทษ! เอ่อ เดี๋ยวก่อน ฉันไม่ได้เหยียบใคร!",
  ui_story_5035_50350801_199_dialog_content = "อ๊ะ!",
  ui_story_5035_50350801_200_dialog_content = "มีอะไรหยดลงบนพวกคุณหรือไม่?",
  ui_story_5035_50350801_201_dialog_content = "ของเหลวเยือกแข็งบางชนิด...",
  ui_story_5035_50350801_202_dialog_content = "ใช่ ฉันก็รู้สึกอย่างนั้นเหมือนกัน...",
  ui_story_5035_50350801_203_dialog_content = "คุณด้วย? โอ้เยี่ยมมาก!!",
  ui_story_5035_50350801_204_dialog_content = "ยอดเยี่ยม?!",
  ui_story_5035_50350801_205_dialog_content = "นั่นหมายความว่าคราวนี้มีบางอย่างปรากฏขึ้นอย่างแน่นอน!",
  ui_story_5035_50350801_206_dialog_content = "อะไรนะ นั่นเป็นสิ่งที่ดี!",
  ui_story_5035_50350801_207_dialog_content = "PlayerName! เปิดกล้องมองกลางคืนอย่างรวดเร็ว!",
  ui_story_5035_50350801_208_dialog_content = "ว้าว มันทำได้เหรอ ฉันควรเปิดเครื่องอย่างไร?",
  ui_story_5035_50350801_209_dialog_content = "ควรมีปุ่มสี่เหลี่ยมอยู่ใต้ปุ่มชัตเตอร์โดยตรง กดเลย!",
  ui_story_5035_50350801_210_dialog_content = "ใต้ปุ่มชัตเตอร์...",
  ui_story_5035_50350801_211_dialog_content = "หวาา!",
  ui_story_5035_50350801_212_dialog_content = "อย่างรวดเร็ว! ฉันคิดว่าฉันเห็นบางอย่างที่นั่น! ที่นั่น!",
  ui_story_5035_50350801_213_dialog_content = "ฉันเข้าใจแล้ว!",
  ui_story_5035_50350801_214_dialog_content = "<color=#e8d9bb>เปรี๊ยะ!</color>",
  ui_story_5035_50350801_215_dialog_content = "โอ้! ฉันมองเห็น...",
  ui_story_5035_50350801_216_dialog_content = "มันคืออะไร? อะไรอยู่ตรงนั้น!",
  ui_story_5035_50350801_217_dialog_content = "ท-นั่นคือไมนอส ฉันคิดว่า",
  ui_story_5035_50350801_218_dialog_content = "ไมนอส? เขาไม่ได้อยู่ข้างๆเราเหรอ?",
  ui_story_5035_50350801_219_dialog_content = "เอ่อ เขา...",
  ui_story_5035_50350801_220_dialog_content = "เขายืนอยู่คนเดียวหันหน้าเข้ามุม...",
  ui_story_5035_50350801_221_dialog_content = "เดี๋ยวนะ... หันหน้าเข้ามุมเหรอ?",
  ui_story_5035_50350801_222_dialog_content = "พวกคุณยังจำได้ไหม? ที่เราเพิ่งพบเขียนบนกระดาษ...",
  ui_story_5035_50350801_223_dialog_content = "หา?",
  ui_story_5035_50350801_224_dialog_content = "“เด็กดื้อจะโดนนายทำโทษ”",
  ui_story_5035_50350801_225_dialog_content = "คนหนึ่งถูกลงโทษ อีกคน... ยืนอยู่ที่มุมห้องและฟัง...",
  ui_story_5035_50350801_226_dialog_content = "บ้าไปแล้ว...",
  ui_story_5035_50350801_227_dialog_content = "แต่ไมนอสตอนนี้ดูเหมือน...",
