  ui_story_5035_50350801_236_dialog_content = "<color=#e8d9bb>พลัก!</color>",
  ui_story_5035_50350801_237_dialog_content = "อ๊าาา!",
  ui_story_5035_50350801_238_dialog_content = "<size=45>อ๊ะ!</size>",
  ui_story_5035_50350801_239_dialog_content = "<size=55>อ่าฮะ!</size>",
  ui_story_5035_50350801_240_dialog_content = "<color=#e8d9bb>ฟึบ!</color>",
  ui_story_5035_50350801_241_dialog_content = "<color=#e8d9bb>*เสียงฝีเท้า*</color>",
  ui_story_5035_50350801_242_dialog_content = "<color=#e8d9bb>*ฝีเท้าใกล้เข้ามา*</color>",
  ui_story_5035_50350801_243_dialog_content = "ทำไมกล้องถึงอยู่บนพื้น? คุณกำลังทำอะไรอยู่?",
  ui_story_5035_50350801_244_dialog_content = "ที่นี่, PlayerName.",
  ui_story_5035_50350801_245_dialog_content = "โอ้... เอ่อ... คุณไม่ใช่แค่...",
  ui_story_5035_50350801_246_dialog_content = "ฟิวส์ขาด ฉันเพิ่งซ่อมมัน",
  ui_story_5035_50350801_247_dialog_content = "อ๋อ งั้นเหรอ?",
  ui_story_5035_50350801_248_dialog_content = "คุณจึงยืนอยู่ตรงมุมห้อง...",
