  ui_story_5035_50350801_250_dialog_content = "...",
  ui_story_5035_50350801_251_dialog_content = "รู้ไหม การซ่อมแซมฟิวส์ขาดในความมืดไม่ใช่เรื่องง่าย ฉันน่าจะเปิดไฟให้เร็วขึ้นถ้าคุณไม่ส่งเสียงดัง",
  ui_story_5035_50350801_252_dialog_content = "แล้วเกิดอะไรขึ้น? คุณเห็นอะไรไหม",
  ui_story_5035_50350801_253_dialog_content = "เอ่อ เราเห็น... เอ่อ...",
  ui_story_5035_50350801_254_dialog_content = "โอ้ มันดำสนิท เราจะเห็นอะไรได้อย่างไร?",
