  ui_story_5035_50350801_256_dialog_content = "อร๊ายยย แย่แล้ว! อีกครั้ง?!",
  ui_story_5035_50350801_257_dialog_content = "ทำไมคุณถึงตื่นเต้นกับเรื่องนี้!",
  ui_story_5035_50350801_258_dialog_content = "โอ้ อะไรก็ได้ ลืมมันไปเถอะ เดาว่าวันนี้ฉันไม่มีอะไรน่าสนใจอีกแล้วสำหรับ Into the Haunted House",
  ui_story_5035_50350801_259_dialog_content = "*ยะ-w* ฉันเหนื่อย ถ่ายรูปหมู่กันอีกสักรูป แล้วค่อยกลับไปพักผ่อน",
  ui_story_5035_50350801_260_dialog_content = "กับรูปหมู่ตลอดเลยฮะ...",
