  ui_story_5035_50350801_262_dialog_content = "ขณะที่คุณอยู่ที่นั้น ให้ตรวจสอบว่ากล้องไม่ได้รับความเสียหาย ถ้ามี PlayerNameคุณอาจต้อง...",
  ui_story_5035_50350801_263_dialog_content = "อะไรนะ!",
  ui_story_5035_50350801_264_dialog_content = "เอฟ-ไฟน์. ทุกคน มารวมตัวกัน!",
