  ui_story_5035_50350801_269_dialog_content = "3... 2... 1...",
  ui_story_5035_50350801_270_dialog_content = "<color=#e8d9bb>ตูม...</color>",
  ui_story_5035_50350901_1_dialog_content = "เข้าไปในบ้านผีสิง—ถูกห่อ!",
  ui_story_5035_50350901_2_dialog_content = "ขอแสดงความยินดีทุกคน! ไมนอส ฉันจะพัฒนารูปภาพเหล่านี้ได้ที่ไหน",
  ui_story_5035_50350901_3_dialog_content = "ฉันต้องการให้ทุกคนถ่ายรูปหมู่ของเรา!",
  ui_story_5035_50350901_4_dialog_content = "มากับฉัน. สำนักงานของฉันมีห้องมืดที่ทำงาน",
  ui_story_5035_50350901_5_dialog_content = "พวกคุณที่เหลือก็มาด้วย ฉันจะจัดห้องของคุณสำหรับคืนนี้",
  ui_story_5035_50350901_6_dialog_content = "เช่นกัน... คืนนี้มีอะไรเกิดขึ้นมากมาย เราน่าจะไตร่ตรองรายละเอียดอีกครั้งหลังจากที่สงบสติอารมณ์ได้แล้ว",
  ui_story_5035_50350901_7_dialog_content = "คุณถูก. ฉันรู้สึกเหมือนฉันไม่ได้ใช้สมองเลยวันนี้",
  ui_story_5035_50350901_8_dialog_content = "ทุกสิ่งที่เกิดขึ้นนั้นต้องการการไตร่ตรองอย่างยาวนานและลึกซึ้ง แต่คืนนี้สายเกินไปแล้ว ไปนอนกันเถอะ ♪",
  ui_story_5035_50350901_9_dialog_content = "โอ้ ฉันเพิ่งจำได้ ที่ห้องใต้ดินก่อนหน้านี้ เมื่อไฟดับ มีใครพูดอะไรแปลกๆ บ้างไหม?",
  ui_story_5035_50350901_10_dialog_content = "แปลก?",
  ui_story_5035_50350901_11_dialog_content = "บางอย่างในแนว \"ใครบางคนต้องถูกลงโทษ\"? ฉันไม่รู้จักเสียง",
  ui_story_5035_50350901_12_dialog_content = "ฮะ? ใครจะพูดอะไรแบบนั้น?",
  ui_story_5035_50350901_13_dialog_content = "ฉันไม่ได้ยินอะไรเลย",
  ui_story_5035_50350901_14_dialog_content = "อะไร คนอื่นไม่ได้ยินเหรอ?",
  ui_story_5035_50350901_15_dialog_content = "ไม่สามารถมีอื่น ๆ ...",
  ui_story_5035_50350901_16_dialog_content = "อ๊ะ! หยุดแกล้งฉันสักที!!",
  ui_story_5035_50350901_17_dialog_content = "ออกไปจากที่นี่กันเถอะ!",
  ui_story_5035_50350901_18_dialog_content = "ว้าว! ไมนอส ห้องคุณเป็นระเบียบมาก!",
  ui_story_5035_50350901_19_dialog_content = "ดูสิ่งที่คุณสัมผัส มีอุปกรณ์ลูกเรือมากมายที่นี่",
  ui_story_5035_50350901_20_dialog_content = "โอเค เข้าใจแล้ว แล้วห้องมืดอยู่ไหนล่ะ?",
  ui_story_5035_50350901_21_dialog_content = "อ่า ใช่... แค่ผ่านประตูเล็กๆ นั้น คุณรู้วิธีการใช้สารเคมีหรือไม่?",
  ui_story_5035_50350901_22_dialog_content = "แน่นอน! ฉันเป็นช่างภาพมืออาชีพ—",
  ui_story_5035_50350901_23_dialog_content = "—ผู้ชื่นชอบอี...",
  ui_story_5035_50350901_24_dialog_content = "คุณรู้หรือไม่ว่าคุณกำลังพูดอะไร",
  ui_story_5035_50350901_25_dialog_content = "ฮ่าๆๆ จะใช้เวลาสักครู่ในการพัฒนารูปภาพ พวกคุณรอฉันด้วย",
  ui_story_5035_50350901_26_dialog_content = "วุ้ย ฉันเหนื่อย ฉันต้องการพัก!",
  ui_story_5035_50350901_27_dialog_content = "การเยี่ยมชมบ้านผีสิง Andersen ครั้งนี้คุ้มค่าจริงๆ! การเดินทางที่น่าตื่นเต้นจริงๆ!",
  ui_story_5035_50350901_28_dialog_content = "คุณยังคิดว่าหลังจากที่กลัวแค่ไหน...",
  ui_story_5035_50350901_29_dialog_content = "อะไร ฉันสามารถเพลิดเพลินและกลัวสิ่งเหนือธรรมชาติในเวลาเดียวกัน",
  ui_story_5035_50350901_30_dialog_content = "ค่อนข้างจะเพราะกลัวสิ่งเหนือธรรมชาติที่ฉันรักความลึกลับของพวกเขา!",
  ui_story_5035_50350901_31_dialog_content = "มันเป็นอย่างนั้นเหรอ",
  ui_story_5035_50350901_32_dialog_content = "แน่นอน! คุณนีน่าซื้อบ้านหลังนี้มาเพื่อเอาใจนักล่าผี",
  ui_story_5035_50350901_33_dialog_content = "เราควรจะขอบคุณเธอที่ก่อตั้งบ้านผีสิง Andersen อย่างระมัดระวัง มันจะกลายเป็นเพลงฮิตอย่างมหาศาล!",
  ui_story_5035_50350901_34_dialog_content = "พวกคุณคิดว่าสิ่งที่เกิดขึ้นคืนนี้เป็นเพียงส่วนหนึ่งของการจัดตั้งบ้านผีสิง?",
  ui_story_5035_50350901_35_dialog_content = "หา?",
  ui_story_5035_50350901_36_dialog_content = "แน่นอนว่าคุณนีน่าได้เตรียมการบางอย่างไว้แล้ว",
  ui_story_5035_50350901_37_dialog_content = "แต่เท่าที่เราประสบในคืนนี้ หลายสิ่งหลายอย่างไม่ได้เป็นส่วนหนึ่งของการเตรียมการเหล่านั้น",
  ui_story_5035_50350901_38_dialog_content = "คุณหมายถึง เหมือนไฟฟ้าดับในห้องใต้ดินใช่หรือไม่",
  ui_story_5035_50350901_39_dialog_content = "ใช่. ฉันบอกคุณแล้ว ห้องใต้ดินไม่เคยเป็นส่วนหนึ่งของบ้านผีสิง",
  ui_story_5035_50350901_40_dialog_content = "บางทีมันอาจจะเป็นเพียงอุบัติเหตุ?",
  ui_story_5035_50350901_41_dialog_content = "อุบัติเหตุเป็นส่วนหนึ่งของเหตุการณ์เหนือธรรมชาติ!",
  ui_story_5035_50350901_42_dialog_content = "นั่นคือสิ่งที่ผมคิดเช่นกัน",
  ui_story_5035_50350901_43_dialog_content = "การเผชิญเหตุการณ์ที่ไม่สามารถอธิบายได้ อุบัติเหตุ หรือเรื่องบังเอิญคือคำตอบที่ดีที่สุด",
  ui_story_5035_50350901_44_dialog_content = "อย่างแน่นอน! อุบัติเหตุมักจะเกิดขึ้นรอบตัวฉันและ PlayerName...",
