  ui_story_5035_50350901_46_dialog_content = "โอ้? ขัดแย้งอะไร?",
  ui_story_5035_50350901_47_dialog_content = "มีเรื่องล่าสุดในหนังสือพิมพ์ ฉันไม่แน่ใจว่ามีใครเห็นหรือไม่",
  ui_story_5035_50350901_48_dialog_content = "บางอย่างเกี่ยวกับการหายตัวไปอย่างลึกลับของดาราหนังสยองขวัญ",
  ui_story_5035_50350901_49_dialog_content = "โอ้! ฉันคิดว่าฉันเคยเห็นพาดหัวข่าวนั้นแล้ว!",
  ui_story_5035_50350901_50_dialog_content = "\"ดาราหนังสยองขวัญบี-ฮอลโลว์\" หายตัว!",
  ui_story_5035_50350901_51_dialog_content = "เรื่องแบบนั้นเกิดขึ้นที่อัมบราตัน แต่...",
  ui_story_5035_50350901_52_dialog_content = "การแสดงผาดโผนการประชาสัมพันธ์นี้กรีดร้องใช่หรือไม่?",
  ui_story_5035_50350901_53_dialog_content = "คุณรู้ไหม นักแสดงสาวได้แสดงในภาพยนตร์เรื่องล่าสุดที่ถ่ายทำโดยทีมงานของจอนนี่",
  ui_story_5035_50350901_54_dialog_content = "ฮะ?! บรรพบุรุษของฉัน?",
  ui_story_5035_50350901_55_dialog_content = "ถูกตัอง. เพียงแต่ในตอนนั้น มิสซูสยังไม่ได้ซื้อบ้านผีสิง และฉันก็ไม่ได้เป็นส่วนหนึ่งของทีม",
  ui_story_5035_50350901_56_dialog_content = "ฉันอ่านเกี่ยวกับเรื่องนี้ในบันทึกของลูกเรือ",
  ui_story_5035_50350901_57_dialog_content = "แล้วเกิดอะไรขึ้น? เธอหายไปได้ยังไง?",
  ui_story_5035_50350901_58_dialog_content = "ฉันไม่รู้. บันทึกเพิ่งกล่าวว่านักแสดงหญิงเป็นส่วนหนึ่งของการถ่ายทำและไม่มีอะไรมากไปกว่านี้",
  ui_story_5035_50350901_59_dialog_content = "แล้วอะไรคือสิ่งที่ขัดแย้งกัน?",
  ui_story_5035_50350901_60_dialog_content = "คุณจำสมุดบันทึกลูกเรือที่เราพบในห้องใต้ดินได้หรือไม่?",
  ui_story_5035_50350901_61_dialog_content = "ทั้งหมดที่เกี่ยวข้องกับภาพยนตร์เรื่องที่แล้ว",
  ui_story_5035_50350901_62_dialog_content = "โอ้! หนังที่นางเอกหายตัวไป!",
  ui_story_5035_50350901_63_dialog_content = "ถูกต้อง. การถ่ายทำภาพยนตร์สั้นลง น่าจะเป็นเพราะเธอหายตัวไป",
  ui_story_5035_50350901_64_dialog_content = "ฉันแน่ใจว่าได้ดูตารางการถ่ายภาพที่อยู่ในบันทึกย่อแล้ว",
  ui_story_5035_50350901_65_dialog_content = "ยกเว้นเหตุการณ์ไม่คาดฝันใดๆ การถ่ายทำควรจะเสร็จสิ้นในวันนี้",
  ui_story_5035_50350901_66_dialog_content = "คุณเห็นปัญหาตอนนี้หรือไม่?",
  ui_story_5035_50350901_67_dialog_content = "คุณกำลังพูดถึงเวลา?",
  ui_story_5035_50350901_68_dialog_content = "ใช่. เท่าที่ครอบครัวและเพื่อนของนักแสดงเป็นกังวล เธอยังอยู่ในการถ่ายทำ",
  ui_story_5035_50350901_69_dialog_content = "ลูกเรือไม่มีทางติดต่อกับญาติของเธอ และไม่เหมือนกับว่าตำแหน่งของเธอจะถูกเปิดเผยต่อสาธารณะ",
  ui_story_5035_50350901_70_dialog_content = "จึงไม่มีใครรู้ว่าเธอหายไป",
  ui_story_5035_50350901_71_dialog_content = "พูดแบบนี้แล้วเหมือน...",
  ui_story_5035_50350901_72_dialog_content = "<color=#e8d9bb>ตบมือตบมือ!</color>",
  ui_story_5035_50350901_73_dialog_content = "อัศจรรย์! ช่างเป็นเหตุผลอันยอดเยี่ยมเสียนี่กระไร!",
  ui_story_5035_50350901_74_dialog_content = "คุณมาเมื่อไหร่ ลิลิก้า? ถ่ายรูปเสร็จแล้วเหรอ?",
  ui_story_5035_50350901_75_dialog_content = "ใช่. ฉันแค่รอให้พวกมันแห้ง",
  ui_story_5035_50350901_76_dialog_content = "ยังไงก็ไปต่อครับ ถ้าไม่มีใครรู้ว่านักแสดงสาวคนนั้นหายตัวไป แล้วหนังสือพิมพ์ท้องถิ่นรายงานเรื่องนี้ได้อย่างไร?",
  ui_story_5035_50350901_77_dialog_content = "มีความเป็นไปได้เพียงสองอย่างเท่านั้น",
  ui_story_5035_50350901_78_dialog_content = "ทีมงานหรือแม้แต่ตัวนักแสดงเองก็เล่าให้หนังสือพิมพ์ฟังเกี่ยวกับการหายตัวไป",
  ui_story_5035_50350901_79_dialog_content = "อุ๊ย! ใช่! พวกเขาเป็นคนเดียวที่รู้!",
  ui_story_5035_50350901_80_dialog_content = "ถูกต้อง. แต่แล้วมีเหตุผลอะไรที่พวกเขาต้องทำอย่างนั้น?",
  ui_story_5035_50350901_81_dialog_content = "ลูกเรือจะไม่ได้รับอะไรเลยหากมีข่าวการหายตัวไป มันไม่คุ้มค่าที่จะไปสื่อมวลชนเพียงเพื่อการประชาสัมพันธ์เชิงลบ",
  ui_story_5035_50350901_82_dialog_content = "สำหรับนักแสดงสาว ทำไมเธอถึงต้องการรั่วไหลข่าวการหายตัวไปของเธอ?",
  ui_story_5035_50350901_83_dialog_content = "นั่นคือสิ่งที่ฉันเคยสงสัยเช่นกัน แต่ยังไม่สามารถออกกำลังกายได้",
  ui_story_5035_50350901_84_dialog_content = "ดังนั้น... ฉันไม่คิดว่ามันเป็นไปได้มากที่นักแสดงจะทำด้วยตัวเอง",
  ui_story_5035_50350901_85_dialog_content = "เธอไม่ค่อยเป็นที่รู้จักมากนัก ดังนั้นข่าวการหายตัวไปของเธอจึงไม่สำคัญมากนัก",
