  ui_story_5035_50351101_9_dialog_content = "เอ๋...?",
  ui_story_5035_50351101_10_dialog_content = "น่าทึ่งมาก! เรามีรูปถ่ายเป็นหลักฐานที่ชัดเจน!",
  ui_story_5035_50351101_11_dialog_content = "นั่นคือวิธีที่ฉันกลิ้ง นักล่าผีที่ยิ่งใหญ่ที่สุดของโลก! ฉันทำให้มันดูง่าย!",
  ui_story_5035_50351101_12_dialog_content = "ไปจัดการมันกับลูกเรือกันเถอะ!",
  ui_story_5035_50351101_13_dialog_content = "เดี๋ยวนะ เราไม่ควรจะคิดให้มากกว่านี้หน่อยหรือ? ถ้าจะบอกว่ามีผีจริงๆ...",
  ui_story_5035_50351101_14_dialog_content = "และทำไมเราไปที่ลูกเรือ?",
  ui_story_5035_50351101_15_dialog_content = "พวกเขาจงใจซ่อนภาพนิ่ง อาจเป็นเพราะพวกเขารู้ถึงการดำรงอยู่ของ White Lady",
  ui_story_5035_50351101_16_dialog_content = "นี้ยังคงเป็นเพียงการเก็งกำไรอย่างไรก็ตาม เรายังเชื่อมโยงลูกเรือกับไวท์เลดี้ไม่ได้",
  ui_story_5035_50351101_17_dialog_content = "คุณจะเตือนพวกเขาโดยการกระทำที่หุนหันพลันแล่นเท่านั้น ขอแนะนำว่าอย่ารีบร้อนอะไร",
  ui_story_5035_50351101_18_dialog_content = "ฮึ่ม ถ้าเบาะแสที่เรามีตอนนี้ยังไม่เพียงพอที่จะผูก White Lady กับลูกเรือ...",
  ui_story_5035_50351101_19_dialog_content = "เกิดอะไรขึ้นถ้าเราเพิ่มนักแสดงที่หายไปลงในส่วนผสม?",
  ui_story_5035_50351101_20_dialog_content = "<color=#e8d9bb>ฟิ้วว—</color>",
  ui_story_5035_50351101_21_dialog_content = "ตาดา! ดูหน้าที่แท้จริงของฉันสิ!",
  ui_story_5035_50351101_22_dialog_content = "แทบไม่เห็นความแตกต่างจากเมื่อก่อน",
  ui_story_5035_50351101_23_dialog_content = "ฉันกำลังจะตายจริงๆ ที่จะถามถึงสาเหตุของเคราปลอม",
  ui_story_5035_50351101_24_dialog_content = "แต่เดี๋ยวก่อน คุณพูดว่าอะไรนะ? นางเอกหาย?!",
  ui_story_5035_50351101_25_dialog_content = "ถูกตัอง! \"ดาราหนังสยองขวัญบี-ฮอลโลว์\" ที่หายตัวไป? เป็นลิลิก้า!",
  ui_story_5035_50351101_26_dialog_content = "อะไรนะ!",
  ui_story_5035_50351101_27_dialog_content = "หา?",
  ui_story_5035_50351101_28_dialog_content = "เฮ้อ...",
  ui_story_5035_50351101_29_dialog_content = "นั่นทำให้สิ่งต่าง ๆ ง่ายขึ้น บอกเราหน่อยว่าการหายตัวไปทั้งหมดเกี่ยวกับอะไร",
  ui_story_5035_50351101_30_dialog_content = "ให้ฉันเริ่มต้นด้วยหนังสยองขวัญเรื่องสุดท้ายที่จอนนี่กำกับ",
  ui_story_5035_50351101_31_dialog_content = "ฉันชอบหนังมาโดยตลอด โดยเฉพาะหนังสยองขวัญ",
  ui_story_5035_50351101_32_dialog_content = "ดังนั้นฉันจึงอยู่เหนือดวงจันทร์เมื่อจอนนี่ขอให้ฉันร่วมแสดงในภาพยนตร์เรื่องใหม่ของเขา",
  ui_story_5035_50351101_33_dialog_content = "สถานที่สำหรับถ่ายทำ—อย่างที่คุณรู้—ถูกวางแผนสำหรับบ้านหลังนี้",
  ui_story_5035_50351101_34_dialog_content = "ทุกอย่างเป็นไปตามแผน แต่เมื่อเราไปถึงชั้นใต้ดิน...มีอุบัติเหตุเกิดขึ้น",
  ui_story_5035_50351101_35_dialog_content = "อุบัติเหตุ? อุบัติเหตุแบบไหน?",
  ui_story_5035_50351101_36_dialog_content = "มันเป็นบิตของระเบียบ อย่างแรก ฉันได้ยินเสียงหยดน้ำ แล้วก็เสียงระฆังก้องกังวาน",
  ui_story_5035_50351101_37_dialog_content = "โอ้ และฉันไม่สามารถลืมเทียนได้! ฉันเห็นเทียนวางโดยไม่มีเหตุผลทั่วห้องใต้ดิน",
  ui_story_5035_50351101_38_dialog_content = "จากนั้น... มีบางอย่างปรากฏขึ้น ฉันไม่สามารถมองมันได้ดีนัก แต่ก็ไม่ใช่ใครซักคน",
  ui_story_5035_50351101_39_dialog_content = "มันต้องการจะฆ่าฉัน ความปรารถนาที่จะทำเช่นนั้นนั้นแข็งแกร่งอย่างน่ากลัว",
  ui_story_5035_50351101_40_dialog_content = "ฉันถูกทำร้ายและบาดเจ็บสาหัส แย่จริง ๆ ที่ฉันคิดว่าฉันกำลังจะตายที่นั่น",
  ui_story_5035_50351101_41_dialog_content = "แต่โชคดีที่ทักษะที่ยิ่งใหญ่ที่สุดของฉันมักหนีไม่พ้น",
  ui_story_5035_50351101_42_dialog_content = "ฉันวิ่งเป็นเวลานานมากในความมืดของคืน ฉันวิ่งและวิ่ง และในที่สุดก็กลับมาที่อัมบราตัน ที่ซึ่งแพทย์สามารถช่วยฉันได้",
  ui_story_5035_50351101_43_dialog_content = "ฉันพักรักษาตัวในคลินิกของเขาเป็นเวลาสองวันเต็ม แต่หลังจากนั้น เหตุการณ์ที่เลวร้ายที่สุดก็จบลง และฉันก็ตื่นขึ้นอีกครั้ง",
  ui_story_5035_50351101_44_dialog_content = "ผ่านพ้นสิ่งที่ต้องเคย...สะเทือนใจ",
  ui_story_5035_50351101_45_dialog_content = "ตอนเราอยู่ในห้องใต้ดิน คุณบอกให้ผมเอากล้องไปถ่าย...",
  ui_story_5035_50351101_46_dialog_content = "อย่างแท้จริง. เผื่อมีอุบัติเหตุอีก อย่างน้อยความจริงก็จะถูกบันทึกไว้ในกล้อง",
  ui_story_5035_50351101_47_dialog_content = "ฉันไม่อยากจะเชื่อเลยว่าคุณกลับมา ที่เอาความกล้า",
  ui_story_5035_50351101_48_dialog_content = "ถ้ามันขึ้นอยู่กับฉัน ฉันจะไม่กลับมาภายในหนึ่งไมล์จากที่นี่ไปตลอดชีวิต",
  ui_story_5035_50351101_49_dialog_content = "ตอนแรกฉันไม่แม้แต่จะกลับ ผีน่ากลัวมาก ทำไมต้องเอาตัวเองกลับมาทำร้าย?",
  ui_story_5035_50351101_50_dialog_content = "แต่แล้วฉันก็ได้ข่าวแปลกๆ ว่าจอนนี่และทีมของเขากำลังจะไปถ่ายทำที่เดิมต่อ",
