  ui_story_5035_50351101_55_dialog_content = "หรือบางทีก่อนหน้านี้ คุณช่วยชี้แนะการใช้เหตุผลของฉัน",
  ui_story_5035_50351101_56_dialog_content = "ดังนั้น... ฉันไม่คิดว่ามันเป็นไปได้มากที่นักแสดงจะทำด้วยตัวเอง",
  ui_story_5035_50351101_57_dialog_content = "มาเน้นที่ความเป็นไปได้อื่น ๆ แล้ว หากเป็นทีมงานที่รั่วไหลเรื่องราว แรงจูงใจของพวกเขาคืออะไร?",
  ui_story_5035_50351101_58_dialog_content = "ฮิฮิ... ฉันจะไม่เรียกว่าเป็นการชี้นำคุณ เหมือนกับช่วยให้คุณแยกแยะตัวเลือกที่ไม่ถูกต้องบางอย่างออก",
