  ui_story_5035_50351101_63_dialog_content = "มันคือการตั้งค่าทั้งหมด หลอกดาราสาวไม่สงสัยอย่างผมให้มีส่วนร่วม...",
  ui_story_5035_50351101_64_dialog_content = "ไม่ว่าการหลอกหลอนที่มนุษย์สร้างขึ้นจะฉลาดและชาญฉลาดเพียงใด แต่ก็ไม่มีที่ไหนที่ใกล้จะมีผลกระทบเท่ากับการหลอกหลอนที่เกิดขึ้นจริง",
  ui_story_5035_50351101_65_dialog_content = "พวกเขาจะทำทุกอย่างเพื่อสร้างหนังสยองขวัญที่ไม่เหมือนใคร",
