  ui_story_5035_50351102_1_dialog_content = "<color=#e8d9bb>กริ๊ง... กริ๊ง...</color>",
  ui_story_5035_50351102_2_dialog_content = "เฮ้ เมื่อกี้คุณได้ยินเสียงเอะอะโวยวายที่ชั้นบนรึเปล่า?",
  ui_story_5035_50351102_3_dialog_content = "ใช่! ฉันได้ยินบางอย่างแน่นอน",
  ui_story_5035_50351102_4_dialog_content = "อาจเป็นเพียงผู้เยี่ยมชมบ้านผีสิง เป็นเรื่องปกติที่พวกเขาจะตื่นตระหนก",
  ui_story_5035_50351102_5_dialog_content = "หึหึหึ ฉันหวังว่าฉันจะได้สนุกที่นี่เช่นกัน",
  ui_story_5035_50351102_6_dialog_content = "อย่าเป็นคนงี่เง่า เรามาทำงานหาเงินกัน",
  ui_story_5035_50351102_7_dialog_content = "หากคุณมีเวลาฝันกลางวัน คุณก็มีเวลาย้ายอุปกรณ์ไปที่ทางเข้า ผู้กำกับรออยู่",
  ui_story_5035_50351102_8_dialog_content = "<color=#e8d9bb>กริ๊ง... กริ๊ง...</color>",
  ui_story_5035_50351102_9_dialog_content = "คุณได้ยินไหม ที่นี่มีผีจริงๆ!",
  ui_story_5035_50351102_10_dialog_content = "อืม. แน่นอนพวกเขาจะพูดอย่างนั้น มิฉะนั้นพวกเขาจะให้ใครซื้อตั๋วได้อย่างไร?",
  ui_story_5035_50351102_11_dialog_content = "ใครจะรู้? มันอาจจะจริงก็ได้ ฉันรู้สึกสยองอยู่ตลอดเวลา",
  ui_story_5035_50351102_12_dialog_content = "เกือบเหมือน... มีคนตามฉันมา",
  ui_story_5035_50351102_13_dialog_content = "Pff ใครจะมีเวลาวิ่งตามคุณ?",
  ui_story_5035_50351102_14_dialog_content = "ไม่ได้ยินเหรอ? ผู้หญิงที่สร้างสถานที่นี้ขึ้นเป็นครั้งแรกมักกังวลว่าสิ่งชั่วช้าจะแอบเข้ามาและพยายามจะฆ่าเธอ",
  ui_story_5035_50351102_15_dialog_content = "ถ้าไอ้เลวนั่นจับผิดคนล่ะก็...",
  ui_story_5035_50351102_16_dialog_content = "เฮ้ คุณมาก—",
  ui_story_5035_50351102_17_dialog_content = "อ๊าาา!",
  ui_story_5035_50351102_18_dialog_content = "ไม่ไม่ไม่! ไม่ใช่ฉัน! สัญญา!",
  ui_story_5035_50351102_19_dialog_content = "อย่าขยับ!",
  ui_story_5035_50351102_20_dialog_content = "ฮะ? อ้อ เป็นคนจริง",
  ui_story_5035_50351102_21_dialog_content = "ใช่ ฉันกำลังคุยกับคุณ! คุณเป็นส่วนหนึ่งของทีมที่น่ากลัว!",
  ui_story_5035_50351102_22_dialog_content = "ฉันเห็นผ่านโครงร่างของคุณแล้ว!",
  ui_story_5035_50351102_23_dialog_content = "หลอกดาราสาวยากจนใช้ชีวิตเป็นเครื่องต่อรองเพื่อสนองความต้องการอันเลวร้ายของคุณเอง!",
  ui_story_5035_50351102_24_dialog_content = "มันคือ... มันเป็นอาชญากร...",
  ui_story_5035_50351102_25_dialog_content = "ความผิดมากเราสามารถเขียนนวนิยายได้",
  ui_story_5035_50351102_26_dialog_content = "ถูกตัอง! เราสามารถเขียนนวนิยายได้!",
  ui_story_5035_50351102_27_dialog_content = "เฮ้อ... เมื่อกี้เธอจำมันไม่ได้เหรอ? ทำไมคุณทิ้งบอลในช่วงเวลาวิกฤติเช่นนี้...",
  ui_story_5035_50351102_28_dialog_content = "โทษไมนอส! คำที่จำยากมาก!",
  ui_story_5035_50351102_29_dialog_content = "คุณเป็นคนเดียวที่อยากให้ฉันช่วยเขียน \"คำปราศรัยเปิดที่ฟังดูฉลาด\" บางอย่าง!",
  ui_story_5035_50351102_30_dialog_content = "ดีแล้ว ลืมมันไปซะ! ไม่เป็นไร!",
  ui_story_5035_50351102_31_dialog_content = "อย่างไรก็ตามคุณมาก! หลังจากทำร้ายฉันมาก ตอนนี้พวกเขากำลังจะทำแบบเดียวกันกับนักแสดงหน้าใหม่!",
  ui_story_5035_50351102_32_dialog_content = "ฉันมีหลักฐานเพียงพอที่จะพิสูจน์ว่าที่นี่มีผีสิงจริงๆ!",
  ui_story_5035_50351102_33_dialog_content = "เมื่อคุณกล้าที่จะกลับมา การแสดงนี้แสดงว่าคุณต้องรู้เรื่องผีและต้องการใช้มันเพื่อตัวคุณเอง!",
  ui_story_5035_50351102_34_dialog_content = "มันสิ้นสุดสำหรับคุณ! พรุ่งนี้คุณจะถูกลงโทษโดย Istvan Gang!",
  ui_story_5035_50351102_35_dialog_content = "แต่ก่อนหน้านั้นฉันมีแซนด์วิชสนับมือรอคุณอยู่!",
  ui_story_5035_50351102_36_dialog_content = "พร้อมเผชิญความเดือดดาลของเหยื่อแล้วหรือยัง!!",
  ui_story_5035_50351102_37_dialog_content = "การลงโทษ? แซนวิชสนับมือ? ตอนนี้เรากำลังมีปัญหา!",
  ui_story_5035_50351102_38_dialog_content = "ฮึ่ม! ตอนนี้สายเกินไปสำหรับความเสียใจ!",
  ui_story_5035_50351102_39_dialog_content = "โอ้โห!!",
  ui_story_5035_50351102_40_dialog_content = "เอ่อ ฉันขอถามคำถามสั้นๆ ได้ไหม",
  ui_story_5035_50351102_41_dialog_content = "ใคร เอ่อ คุณเป็นใครกันแน่?",
  ui_story_5035_50351102_42_dialog_content = "ฮะ? คุณไม่รู้จักฉันเหรอ เราเคย...",
  ui_story_5035_50351102_43_dialog_content = "เอ๊ะ? รอสักครู่.",
  ui_story_5035_50351102_44_dialog_content = "เธอ...",
  ui_story_5035_50351102_45_dialog_content = "คุณเป็นใครน่ะ",
  ui_story_5035_50351102_X45_dialog_content = "โอ้! ไม่ใช่เหรอ...",
  ui_story_5035_50351102_X46_dialog_content = "รู้จักคนพวกนี้บ้างมั้ย สโมกกี้?",
  ui_story_5035_50351102_X47_dialog_content = "เลสเตอร์กับคอนสแตนติน!",
  ui_story_5035_50351102_X48_dialog_content = "PlayerName! คุณมาหรือยัง",
  ui_story_5035_50351102_X49_dialog_content = "บ้านผีสิง Andersen เป็นที่นิยมจริงๆ",
  ui_story_5035_50351102_X50_dialog_content = "มีความเข้าใจผิดหรือไม่? ทำไมคุณถึงเป็นลูกเรือสองคน?",
  ui_story_5035_50351102_46_dialog_content = "เกิดอะไรขึ้น??",
  ui_story_5035_50351102_47_dialog_content = "ฉันกำลังจะถามมันพอดี! คุณเล่าให้เราฟังพอสมควรแล้ว แต่ฉันไม่คิดว่าเราจะรู้จักกันด้วยซ้ำ!",
  ui_story_5035_50351102_48_dialog_content = "นี่มันเรื่องอะไรกัน? ไม่ได้ถ่ายหนังด้วยกันเหรอ?",
  ui_story_5035_50351102_49_dialog_content = "พุทโธ่! ฉันขอโทษ! ฉันคิดว่าคุณเป็นสมาชิกของทีมงานภาพยนตร์ แต่ดูเหมือนว่าฉันคิดผิด!",
  ui_story_5035_50351102_50_dialog_content = "ฉันเสียใจอย่างสุดซึ้ง!",
  ui_story_5035_50351102_51_dialog_content = "อะไร เราเป็นสมาชิกของลูกเรือ! เว้นแต่ฉันจะถูกไล่ออก!",
  ui_story_5035_50351102_52_dialog_content = "เรากำลังเคลื่อนย้ายอุปกรณ์ประกอบฉาก นั่นไม่ใช่สิ่งที่ลูกเรือจะทำอย่างนั้นเหรอ?",
  ui_story_5035_50351102_53_dialog_content = "อุปกรณ์ประกอบฉาก?",
  ui_story_5035_50351102_54_dialog_content = "<color=#e8d9bb>กริ๊ง... กริ๊ง...</color>",
  ui_story_5035_50351102_55_dialog_content = "ได้ ฉันจะกัด โลงศพกับระฆังคืออะไร?",
  ui_story_5035_50351102_56_dialog_content = "ใช่... นั่นเป็นข้อเสียเปรียบที่โชคร้ายของการทำงานในหนังสยองขวัญ",
  ui_story_5035_50351102_57_dialog_content = "เธอเป็นผู้ดูแลสคริปต์ ส่วนฉันเป็นช่างภาพ",
  ui_story_5035_50351102_58_dialog_content = "แล้วถ้าเราเป็นลูกเรือล่ะ? นั่นไม่ได้เปลี่ยนความจริงที่ว่าเราไม่รู้จักคุณ",
  ui_story_5035_50351102_59_dialog_content = "ฮะ? แต่ผู้ควบคุมบทและช่างภาพคนก่อนคือ...",
  ui_story_5035_50351102_60_dialog_content = "เกิดอะไรขึ้น? พวกเขาเปลี่ยนพนักงานหรือไม่?",
  ui_story_5035_50351102_61_dialog_content = "เราเพิ่งได้งานเหล่านี้เมื่อเร็ว ๆ นี้ แต่เราไม่ใช่มือสมัครเล่น—",
  ui_story_5035_50351102_62_dialog_content = "ตายจริง!",
  ui_story_5035_50351102_63_dialog_content = "ว-มันคืออะไร?",
  ui_story_5035_50351102_64_dialog_content = "ถ้าพวกเขามีสมาชิกลูกเรือใหม่ เกิดอะไรขึ้นกับคนเก่า?",
  ui_story_5035_50351102_65_dialog_content = "อืมม...",
  ui_story_5035_50351102_66_dialog_content = "<color=#e8d9bb>แผละ!</color>",
  ui_story_5035_50351102_67_dialog_content = "!!!",
  ui_story_5035_50351102_68_dialog_content = "<color=#e8d9bb>แผละ!</color>",
  ui_story_5035_50351102_69_dialog_content = "<color=#e8d9bb>แผละ!</color>",
  ui_story_5035_50351102_70_dialog_content = "<color=#e8d9bb>แผละ!</color>",
  ui_story_5035_50351102_71_dialog_content = "<color=#e8d9bb>สแลม!!!</color>",
  ui_story_5035_50351102_72_dialog_content = "นั่นเสียงอะไร...? เกิดอะไรขึ้น?",
  ui_story_5035_50351102_73_dialog_content = "ประตูนั่นเอง พวกเขาทั้งหมดเพียงแค่กระแทกปิด",
  ui_story_5035_50351102_74_dialog_content = "มีคนต้องการดักจับเราที่นี่",
  ui_story_5035_50351102_75_dialog_content = "ใครจะอยากทำแบบนั้น...?",
  ui_story_5035_50351102_76_dialog_content = "ลิลิก้า...ลิลิก้า...",
  ui_story_5035_50351102_77_dialog_content = "ดาวดวงดีของฉัน...",
  ui_story_5035_50351102_78_dialog_content = "ในที่สุดฉันก็ได้พบคุณ",
  ui_story_5035_50351102_79_dialog_content = "(หลังจากที่เสียงน่าขนลุกจางหายไป ร่างของผู้กำกับจอนนี่ก็ค่อยๆ ปรากฏขึ้นต่อหน้าเรา)",
  ui_story_5035_50351102_80_dialog_content = "(เขายืนอยู่ข้างราวบันไดที่ชั้นถัดไป มองมาที่เรา)",
  ui_story_5035_50351102_81_dialog_content = "(ความแตกต่างของความสูงทำให้การจ้องมองอย่างถี่ถ้วนของเขาเข้มข้นขึ้น โดยกดลงมาที่เราจากพื้นด้านบน)",
  ui_story_5035_50351102_82_dialog_content = "(ความตึงเครียดตัดผ่านอากาศ หักเพียงเสียงกัดฟันเล็กน้อยเท่านั้น)",
  ui_story_5035_50351102_83_dialog_content = "ไดเร็กต์-หรือจอน-นี่",
  ui_story_5035_50351102_84_dialog_content = "ฉันต้องยอมรับว่าคุณทำได้ดีมาก",
  ui_story_5035_50351102_85_dialog_content = "ฉันชอบสิ่งที่เราถ่ายด้วยกันมาก มันค่อนข้างจะเป็นงานที่ดีที่สุดของฉัน",
  ui_story_5035_50351102_86_dialog_content = "น่าเสียดายที่คุณไม่มีสิ่งที่จะทำได้ในอุตสาหกรรมนี้",
  ui_story_5035_50351102_87_dialog_content = "คุณไม่เข้าใจแนวคิดของ <color=#FFB400>จบ</color> ภาพยนตร์.",
  ui_story_5035_50351102_88_dialog_content = "นั่นเป็นเหตุผลที่คุณกำลังค้นหาทุกที่สำหรับฉัน? ดูหนังให้จบ?",
  ui_story_5035_50351102_89_dialog_content = "ไม่อีกแล้ว.",
  ui_story_5035_50351102_90_dialog_content = "หนังเรื่องนั้นทำเสร็จตั้งแต่วันที่คุณวิ่งมาหาเรา",
  ui_story_5035_50351102_91_dialog_content = "ไม่ว่าคุณจะทำอะไร มันถูกกำหนดไว้สำหรับถังต่อรองราคาที่ร้านภาพยนตร์ลดราคา น่าขยะแขยงสิ่งนั้น",
  ui_story_5035_50351102_92_dialog_content = "มีเหตุผลอื่นที่ฉันกำลังมองหาคุณ",
  ui_story_5035_50351102_93_dialog_content = "ฉันอยากรู้ว่าคุณมองเห็นในความมืดมากแค่ไหน",
  ui_story_5035_50351102_94_dialog_content = "คนที่มองเห็นมากเกินไปไม่สามารถพูดได้",
  ui_story_5035_50351102_95_dialog_content = "ไม่อนุญาตให้พูด? คุณกำลังเกี่ยวกับอะไร...?",
  ui_story_5035_50351102_96_dialog_content = "ผู้อำนวยการ! ผู้กำกับจอนนี่!",
  ui_story_5035_50351102_97_dialog_content = "อยู่นี่ไง! ฉันมองหาคุณมาตลอด",
  ui_story_5035_50351102_98_dialog_content = "ฉันกำลังดูสคริปต์และต้องการหารือเกี่ยวกับบรรทัดเหล่านี้กับคุณ",
  ui_story_5035_50351102_99_dialog_content = "เส้นไหน? ให้ฉันดู.",
  ui_story_5035_50351102_100_dialog_content = "ที่นี่...",
  ui_story_5035_50351102_101_dialog_content = "ไม่นะ! เธอไม่รู้อะไรเลย!",
  ui_story_5035_50351102_102_dialog_content = "โกลดี้!! หยุด!",
  ui_story_5035_50351102_103_dialog_content = "ฮะ? อะไร...?",
  ui_story_5035_50351102_104_dialog_content = "ชู—",
  ui_story_5035_50351102_105_dialog_content = "คุณห่อแล้ว",
  ui_story_5035_50351102_106_dialog_content = "เธอ...",
  ui_story_5035_50351102_107_dialog_content = "อ่าฮะ—!",
  ui_story_5035_50351201_1_dialog_content = "เขา... เขาฆ่าโกลดี้!",
  ui_story_5035_50351201_2_dialog_content = "...",
  ui_story_5035_50351201_3_dialog_content = "ฉันกลัวดังนั้น",
  ui_story_5035_50351201_4_dialog_content = "การเพิ่มอีกหนึ่งตัวในการนับร่างกายไม่มีความหมายสำหรับเขา",
  ui_story_5035_50351201_5_dialog_content = "ลูกเรือของการถ่ายทำครั้งสุดท้ายทั้งหมดได้พบกับอุบัติเหตุที่โชคร้าย ใช่ไหม จอนนี่?",
  ui_story_5035_50351201_6_dialog_content = "ทั้งหมด...?",
  ui_story_5035_50351201_7_dialog_content = "น่าสนใจครับ คุณโปรดิวเซอร์ อะไรทำให้คุณพูดแบบนั้น?",
  ui_story_5035_50351201_8_dialog_content = "ลิลิกาเข้าใจผิดเมื่อเธอคิดว่าลูกเรือทั้งหมดอยู่ในนั้น",
  ui_story_5035_50351201_9_dialog_content = "ทั้งหมดนี้เป็นความคิดของคุณตั้งแต่ต้นจนจบ",
  ui_story_5035_50351201_10_dialog_content = "ไม่มีแม้แต่เอกสารเดียวในเอกสารทั้งหมดที่คุณทิ้งไว้",
  ui_story_5035_50351201_11_dialog_content = "ฉันคิดว่าเป็นเพราะคุณซ่อนการมีอยู่ของผี",
  ui_story_5035_50351201_12_dialog_content = "เป็นที่ชัดเจนว่าสิ่งที่คุณซ่อนไว้ไม่ใช่เรื่องเหนือธรรมชาติ",
  ui_story_5035_50351201_13_dialog_content = "มันคือลูกเรือเนื้อและเลือดที่แท้จริงที่จะอยู่ในภาพ",
  ui_story_5035_50351201_14_dialog_content = "บันทึกบุคลากรสามารถแก้ไขได้ แต่รูปถ่ายไม่โกหก",
  ui_story_5035_50351201_15_dialog_content = "พวกเขาจะเปิดเผยว่าคุณเปลี่ยนลูกเรือทั้งหมดของคุณ",
  ui_story_5035_50351201_16_dialog_content = "เพราะคุณฆ่าพวกเขาทั้งหมด",
  ui_story_5035_50351201_17_dialog_content = "อืม อืม... ฉันรู้ว่านี่เป็นทางเลือกที่เหมาะสมที่จะร่วมงานกับคุณ คุณโปรดิวเซอร์ คุณเป็นคนช่างสังเกตจริงๆ",
  ui_story_5035_50351201_18_dialog_content = "ฉันรู้สึกขอบคุณจริง ๆ ที่คุณทำงานออกมา หมายความว่าฉันไม่ต้องไปต่อแล้ว ระบายความซ้ำซากจำเจที่น่าเบื่อ",
  ui_story_5035_50351201_19_dialog_content = "คุณพูดถูก อดีตลูกเรือของฉันทุกคนประสบอุบัติเหตุ... ทั้งหมดยกเว้นแกะดำของนางเอกซึ่งตอนนี้อยู่ที่นี่",
