  ui_story_5035_50351201_135_dialog_content = "แพตตี้ชอบบ้านผีสิง",
  ui_story_5035_50351201_136_dialog_content = "แพตซี่เองก็เช่นกัน!",
  ui_story_5035_50351201_137_dialog_content = "เราจึงอยากมาเยี่ยมเยียน",
  ui_story_5035_50351201_138_dialog_content = "เอาล่ะ แต่ฉันเกรงว่าจะไม่มีเวลาเล่นกับคุณในตอนนี้",
  ui_story_5035_50351201_139_dialog_content = "จับมือฉันไว้!",
  ui_story_5035_50351201_140_dialog_content = "ฉันต้องการซ้าย",
  ui_story_5035_50351201_141_dialog_content = "ดังนั้นฉันจะใช้สิทธิ",
  ui_story_5035_50351201_142_dialog_content = "วิ่ง!!",
  ui_story_5035_50351302_1_dialog_content = "กร๊าาาซ!!",
  ui_story_5035_50351302_2_dialog_content = "ฮยา!",
  ui_story_5035_50351302_3_dialog_content = "<color=#e8d9bb>ทุบ! ตี! ประณาม!</color>",
  ui_story_5035_50351302_4_dialog_content = "ฮึ่ม นั่นคือทั้งหมดที่?",
  ui_story_5035_50351302_5_dialog_content = "เป็นความผิดพลาดของคุณที่คิดว่าฉันเป็นแค่ thespian! สำหรับตัวฉันที่ขี้โวยวาย คนพวกนี้เป็นแค่คนเดินถนน",
  ui_story_5035_50351302_6_dialog_content = "ทำได้ดีมาก ซาดี! เราดูแล Eclipsites ทั้งหมดที่ไล่ตามเรา!",
  ui_story_5035_50351302_7_dialog_content = "ต่อไป... ห๊ะ?",
  ui_story_5035_50351302_8_dialog_content = "ทุกคนไปไหนกันหมด?",
  ui_story_5035_50351302_9_dialog_content = "หา?",
  ui_story_5035_50351302_10_dialog_content = "ฉันแค่ติดตามคุณ ไม่ได้ติดตามใครเลยเหรอ?",
  ui_story_5035_50351302_11_dialog_content = "แต่ฉัน... ฉันตามคุณมา!",
  ui_story_5035_50351302_12_dialog_content = "...",
  ui_story_5035_50351302_13_dialog_content = "<color=#e8d9bb>สับเปลี่ยน สับเปลี่ยน...</color>",
  ui_story_5035_50351302_14_dialog_content = "เงียบจัง...",
  ui_story_5035_50351302_15_dialog_content = "ชู่ว! เก็บมันลง.",
  ui_story_5035_50351302_16_dialog_content = "ยิ่งเงียบ ยิ่งฟังเราง่ายขึ้น",
  ui_story_5035_50351302_17_dialog_content = "บางทีที่นี่อาจจะปลอดภัยแล้ว?",
  ui_story_5035_50351302_18_dialog_content = "ไม่มีสุริยุปราคาและไม่มีผีด้วยเสียงหยดที่น่าขนลุกของเธอ",
  ui_story_5035_50351302_19_dialog_content = "ใครจะรู้? อาจมีบางอย่างรอเราอยู่ที่มุมนั้น",
  ui_story_5035_50351302_20_dialog_content = "อย่าพยายามทำให้ฉันกลัว ฉันมีความกล้าในโพดำ",
  ui_story_5035_50351302_21_dialog_content = "แต่ตอนนี้ที่คุณพูดถึงมันแล้ว... จะเป็นความคิดที่ดีไม่ใช่เหรอที่เราจะหยุดเดินเตร่ไปมาอย่างไร้จุดหมาย?",
  ui_story_5035_50351302_22_dialog_content = "จะเป็นอย่างไรถ้าเราเจอสุริยุปราคาเหล่านั้น หรือแม้แต่——",
  ui_story_5035_50351302_23_dialog_content = "ฉันไม่คิดว่าเราทำสิ่งนี้ได้ด้วยตัวเอง",
  ui_story_5035_50351302_24_dialog_content = "...ฉันคิดว่าคุณพูดถูก",
  ui_story_5035_50351302_25_dialog_content = "แล้วเราจะหาห้องซ่อนกันดีไหม?",
  ui_story_5035_50351302_26_dialog_content = "ดู! ฉันคิดว่าเราสามารถเปิดประตูตรงนั้นได้!",
  ui_story_5035_50351302_27_dialog_content = "ชู่ว! เงียบๆ...",
  ui_story_5035_50351302_28_dialog_content = "<color=#e8d9bb>*เอี๊ยดด*</color>",
  ui_story_5035_50351302_29_dialog_content = "เราล็อคมันได้ไหม",
  ui_story_5035_50351302_30_dialog_content = "ให้ฉันได้ดู... โอ้! ฉันคิดว่าเราทำได้!",
  ui_story_5035_50351302_31_dialog_content = "รีบล็อกเลยดีกว่า",
  ui_story_5035_50351302_32_dialog_content = "อื้ม!",
  ui_story_5035_50351302_33_dialog_content = "<color=#e8d9bb>ปัง</color>",
  ui_story_5035_50351302_34_dialog_content = "*เฮ้อ*—เอาละ... เข้าใจแล้ว เข้าใจแล้ว",
  ui_story_5035_50351302_35_dialog_content = "เฮ้อ...",
  ui_story_5035_50351302_36_dialog_content = "อย่างน้อยที่สุดเราก็สามารถหายใจได้! ฉันกลัวตายไปครึ่งหนึ่ง",
  ui_story_5035_50351302_37_dialog_content = "เรามาพักที่นี่กันซักพักเถอะ เราสามารถเข้าร่วมกับคนอื่นๆ ได้ทันทีที่เราได้ยินการเคลื่อนไหวของพวกเขา",
  ui_story_5035_50351302_38_dialog_content = "ใช่ เรามาพักผ่อนกันเถอะ",
  ui_story_5035_50351302_39_dialog_content = "แต่กลับ...",
  ui_story_5035_50351302_40_dialog_content = "ไม่เห็นบางอย่างเกี่ยวกับห้องนี้เลยเหรอ?",
  ui_story_5035_50351302_41_dialog_content = "หืมม?",
  ui_story_5035_50351302_42_dialog_content = "มันทำ! นี่ไม่ใช่โชว์รูมเหรอ?",
  ui_story_5035_50351302_43_dialog_content = "เรากลับมาที่นี่ได้อย่างไร...?",
  ui_story_5035_50351302_44_dialog_content = "ถ้าผมจำไม่ผิด โชว์รูมที่เราได้ยินเสียงน้ำหยดครั้งแรกไม่ใช่เหรอ?",
  ui_story_5035_50351302_45_dialog_content = "อืม... อย่าพูดแบบนั้นสิ ฉันควรจะพักผ่อนตอนนี้อย่างไร",
  ui_story_5035_50351302_46_dialog_content = "คิดอย่างอื่นแล้วเลิกคิด",
  ui_story_5035_50351302_47_dialog_content = "ฉันรู้ มาบันทึกวิดีโอที่นี่เพื่อเป็นที่ระลึกกันเถอะ!",
  ui_story_5035_50351302_48_dialog_content = "ตอนนี้?? คุณมีความสามารถพิเศษในการเลือกเวลาผิด...",
  ui_story_5035_50351302_49_dialog_content = "ไม่เคยผิดเวลา! กล้องมีไว้เพื่อบันทึกช่วงเวลาทุกประเภท!",
  ui_story_5035_50351302_50_dialog_content = "ไม่ว่าคุณจะมีความสุขหรือหวาดกลัว การบันทึกทั้งหมดก็คุ้มค่า",
  ui_story_5035_50351302_51_dialog_content = "และอย่างไรก็ตาม กล้องสามารถตรวจจับร่องรอยของ White Lady ได้ ดีกว่าไม่เห็นอะไรเลยเหรอ?",
  ui_story_5035_50351302_52_dialog_content = "อืม ถูก...",
  ui_story_5035_50351302_53_dialog_content = "<color=#e8d9bb>สับ-!</color>",
  ui_story_5035_50351302_54_dialog_content = "อ้ากกก!!!",
  ui_story_5035_50351302_55_dialog_content = "...?! เกิดอะไรขึ้นน่ะ?",
  ui_story_5035_50351302_56_dialog_content = "ประตู! บางสิ่งบางอย่างเพียงแค่...",
  ui_story_5035_50351302_57_dialog_content = "<color=#e8d9bb>สับ-!</color>",
  ui_story_5035_50351302_58_dialog_content = "ประตูกำลังถูกเปิดออก!",
  ui_story_5035_50351302_59_dialog_content = "<color=#e8d9bb>สับ-!</color>",
  ui_story_5035_50351302_60_dialog_content = "นั่นใครน่ะ?!",
  ui_story_5035_50351302_61_dialog_content = "ลิลิกากับซาดี? Ahaha ช่างเป็นการค้นพบที่ได้ผลจริงๆ!",
  ui_story_5035_50351302_62_dialog_content = "มาเถอะ นางเอกของฉัน! การถ่ายทำกำลังจะเริ่มขึ้น",
  ui_story_5035_50351302_63_dialog_content = "ผู้กำกับจอนนี่?!",
  ui_story_5035_50351302_64_dialog_content = "ฉันเตือนคุณแล้ว! อยู่ด้านหลัง!",
  ui_story_5035_50351302_65_dialog_content = "ภัยคุกคาม? โอ้เรายากไหม",
  ui_story_5035_50351302_66_dialog_content = "ตอนนี้ฉันยิ่งอยากรู้มากขึ้นไปอีก",
  ui_story_5035_50351302_67_dialog_content = "สมมุติว่าฉันไม่อยู่... คุณจะทำอย่างไร?",
  ui_story_5035_50351302_68_dialog_content = "คุณจะทำอะไรกับฉันกันแน่!!",
  ui_story_5035_50351302_69_dialog_content = "<color=#e8d9bb>สับ-!</color>",
  ui_story_5035_50351302_70_dialog_content = "หวาา!",
  ui_story_5035_50351302_71_dialog_content = "จอนนี่! ฉันจับทั้งหมดนี้ในกล้องแล้ว!",
  ui_story_5035_50351302_72_dialog_content = "คุณรู้ไหมว่าจะเกิดอะไรขึ้นถ้าสิ่งนี้ออกไป? หยุดในขณะที่คุณยังทำได้!",
  ui_story_5035_50351302_73_dialog_content = "คุณได้รับมันในเทป?",
  ui_story_5035_50351302_74_dialog_content = "ยอดเยี่ยม ยอดเยี่ยมจริงๆ! เธอเก่งมาก ลิลิก้า เฉียบขาดจริงๆ",
  ui_story_5035_50351302_75_dialog_content = "แต่เทปนี้จะไม่ออก อันที่จริง ฉันจะตัดต่อบางส่วนให้เป็นภาพยนตร์!",
  ui_story_5035_50351302_76_dialog_content = "มันจะทำให้หนังดูไร้ที่ติมากขึ้น",
  ui_story_5035_50351302_77_dialog_content = "เธอ... เธอ...",
  ui_story_5035_50351302_78_dialog_content = "แล้วก็นะ...",
  ui_story_5035_50351302_79_dialog_content = "ใครจะเชื่อว่าหนังมีจริง?",
  ui_story_5035_50351302_80_dialog_content = "<color=#e8d9bb>สับ-!</color>",
  ui_story_5035_50351302_81_dialog_content = "อ๊าา!",
  ui_story_5035_50351302_82_dialog_content = "อ๊าาา!",
  ui_story_5035_50351302_83_dialog_content = "ใช่! แค่นั้นแหละ! ทำต่อไป!",
  ui_story_5035_50351302_84_dialog_content = "อย่าปล่อยให้เสียงกรีดร้องหยุด!",
  ui_story_5035_50351302_85_dialog_content = "<color=#e8d9bb>ปัง—!</color>",
  ui_story_5035_50351302_86_dialog_content = "AHHHHHHHHHHHHHHHHHHHHHHHHHH!",
  ui_story_5035_50351302_87_dialog_content = "ควรทำเคล็ดลับอีกครั้ง",
  ui_story_5035_50351302_88_dialog_content = "ฮ่าฮ่า... ฮ่าฮ่าฮ่าฮ่าฮ่า!!",
  ui_story_5035_50351302_89_dialog_content = "อ๊าาาาา!",
  ui_story_5035_50351302_90_dialog_content = "?!",
  ui_story_5035_50351302_91_dialog_content = "หา?",
  ui_story_5035_50351302_92_dialog_content = "โอ้ มันมาจากที่นั่น",
  ui_story_5035_50351302_93_dialog_content = "เริ่มแล้ว เริ่มได้!",
  ui_story_5035_50351302_94_dialog_content = "โอ้ไม่ไม่ไม่! กล้องไม่หมุนเลย",
  ui_story_5035_50351302_95_dialog_content = "ไม่ ไม่ ไม่ ไม่ ฉันไม่พลาดแม้แต่นัดเดียว ไม่เลย...",
  ui_story_5035_50351302_96_dialog_content = "แฮ่ก... แฮ่ก...",
  ui_story_5035_50351302_97_dialog_content = "แฮ่ก... แฮ่ก...",
  ui_story_5035_50351302_98_dialog_content = "เขาไปแล้ว?",
  ui_story_5035_50351302_99_dialog_content = "น-น่าจะได้แหละ",
  ui_story_5035_50351302_100_dialog_content = "ฉันไม่ค่อยแน่ใจว่าเกิดอะไรขึ้น แต่... คุณได้ยินเสียงนั้นไหม",
  ui_story_5035_50351302_101_dialog_content = "ใช่. ฉันแค่คิดเกี่ยวกับมัน ฟังดูห่างเหินไปหน่อย น่าจะมาจากชั้นล่างที่ไหนสักแห่ง",
  ui_story_5035_50351302_102_dialog_content = "แล้วไม่ใช่เหรอ... ฟังดูคุ้นๆ นะ?",
  ui_story_5035_50351302_103_dialog_content = "ใช่! มันฟังดูเหมือน PlayerName.",
  ui_story_5035_50351401_1_dialog_content = "<color=#e8d9bb>สามนาทีที่แล้ว</color>",
  ui_story_5035_50351401_2_dialog_content = "วุ้ยในที่สุดก็สูญเสีย Eclipsites ทุกคนสบายดีไหม",
  ui_story_5035_50351401_3_dialog_content = "ยังอยู่ในชิ้นเดียว แม้ว่าจะดูเหมือนว่าเราสูญเสียมากกว่าแค่สุริยุปราคา",
  ui_story_5035_50351401_4_dialog_content = "หา?",
  ui_story_5035_50351401_5_dialog_content = "คุณถูก! ลิลิก้ากับซาดีอยู่ไหน!",
  ui_story_5035_50351401_6_dialog_content = "เราต้องแยกจากกันในความโกลาหลทั้งหมด ฉันไม่รู้ว่าตอนนี้พวกเขาจะอยู่ที่ไหน",
  ui_story_5035_50351401_7_dialog_content = "นี้ไม่ดี. สองคนนี้ไม่พร้อมที่จะจัดการกับปัญหาได้ดีที่สุด เราต้องกลับไปหาพวกเขา!",
  ui_story_5035_50351401_8_dialog_content = "พวกเขาน่าจะยังอยู่บนชั้นสอง",
  ui_story_5035_50351401_9_dialog_content = "คุณสามารถมองหาพวกเขาด้วยความสามารถทางจิตของคุณได้ไหม PlayerName?",
  ui_story_5035_50351401_10_dialog_content = "ฉันกำลังดำเนินการอยู่...",
  ui_story_5035_50351401_11_dialog_content = "รอเดี๋ยวสิ",
  ui_story_5035_50351401_12_dialog_content = "หา? อะไรเหรอ?",
  ui_story_5035_50351401_13_dialog_content = "เมื่อเรามาถึงที่นี่ครั้งแรก... อยู่ที่ทางเดินหรือเปล่า?",
  ui_story_5035_50351401_14_dialog_content = "ปรากฏเมื่อไร!",
  ui_story_5035_50351401_15_dialog_content = "เราไม่สามารถพลาดสิ่งที่ยิ่งใหญ่ได้",
  ui_story_5035_50351401_16_dialog_content = "ไม่ ไม่ ไม่! แพตตี้ไม่เคยเห็นมาก่อน",
  ui_story_5035_50351401_17_dialog_content = "นี่คืออะไร? โลงศพ?",
  ui_story_5035_50351401_18_dialog_content = "อ๋อ ลูกเรือส่งมาแค่นี้เองเหรอ?",
  ui_story_5035_50351401_19_dialog_content = "แต่ใครย้ายมาที่นี่?",
  ui_story_5035_50351401_20_dialog_content = "มันไม่สำคัญ ขอเพียงแค่ลืมมันสำหรับตอนนี้ การค้นหาลิลิกาและซาดีสำคัญกว่า",
  ui_story_5035_50351401_21_dialog_content = "ไปรอบ ๆ มันกันเถอะ",
  ui_story_5035_50351401_22_dialog_content = "อ่าใช่ เพียงแค่ไปรอบ ๆ",
  ui_story_5035_50351401_23_dialog_content = "นำไปสู่, PlayerName.",
  ui_story_5035_50351401_24_dialog_content = "ม-ฉัน?",
  ui_story_5035_50351401_25_dialog_content = "อืมมม!",
  ui_story_5035_50351401_26_dialog_content = "แต่กลับ...",
  ui_story_5035_50351401_27_dialog_content = "โอเค ได้! ฉันไปก่อนนะ! มันเป็นแค่พร็อพ มีอะไรต้องกลัว?",
  ui_story_5035_50351401_28_dialog_content = "พยายามที่จะให้ทัน! ยิ่งพบเร็ว—",
  ui_story_5035_50351401_29_dialog_content = "<color=#e8d9bb>ตูม!</color>",
  ui_story_5035_50351401_30_dialog_content = "อ่าฮะ—!",
  ui_story_5035_50351401_31_dialog_content = "หา?",
  ui_story_5035_50351401_32_dialog_content = "โอ้ มันมาจากที่นั่น",
  ui_story_5035_50351401_33_dialog_content = "เสียงนั้น! มันมาจากภายในโลงศพ!",
  ui_story_5035_50351401_34_dialog_content = "ฉันได้ยินมันด้วย!",
  ui_story_5035_50351401_35_dialog_content = "แน่ใจนะว่าเป็นแค่อุปกรณ์ประกอบฉาก?",
  ui_story_5035_50351401_36_dialog_content = "*สะอื้น*",
  ui_story_5035_50351401_37_dialog_content = "ช่วยด้วย...ผี...",
  ui_story_5035_50351401_38_dialog_content = "เราจะทำอย่างไร? เราไม่สามารถเดินขึ้นไปได้อย่างแน่นอน!",
  ui_story_5035_50351401_39_dialog_content = "เราควรหาเส้นทางอื่นหรือไม่? แม้ว่าการหันหลังให้กับมันเล็กน้อย...",
  ui_story_5035_50351401_40_dialog_content = "อาจเป็นการดีที่สุดที่จะตรวจสอบซ้ำ",
  ui_story_5035_50351401_41_dialog_content = "ฉันจะไปเปิดมัน",
  ui_story_5035_50351401_42_dialog_content = "เปิดโลงศพ?!",
  ui_story_5035_50351401_43_dialog_content = "อย่างน้อยที่สุด เราก็จะได้รู้ว่าเรากำลังเผชิญกับอะไร",
  ui_story_5035_50351401_44_dialog_content = "แค่ระวัง...",
  ui_story_5035_50351401_45_dialog_content = "มันจะดี",
  ui_story_5035_50351401_46_dialog_content = "ฉันพร้อม",
  ui_story_5035_50351401_47_dialog_content = "<color=#e8d9bb>ตูม!</color>",
  ui_story_5035_50351401_48_dialog_content = "ใกล้เข้ามาอีกนิด...",
  ui_story_5035_50351401_49_dialog_content = "<color=#e8d9bb>ตูม!</color>",
  ui_story_5035_50351401_50_dialog_content = "อีกหน่อย...",
  ui_story_5035_50351401_51_dialog_content = "<color=#e8d9bb>แบมแบม!</color>",
  ui_story_5035_50351401_52_dialog_content = "...",
  ui_story_5035_50351401_53_dialog_content = "<color=#e8d9bb>แบมแบมแบมแบม!!!</color>",
  ui_story_5035_50351401_54_dialog_content = "*หายใจลึก ๆ*",
  ui_story_5035_50351401_55_dialog_content = "เสียงรุนแรงมาก! มันสัมผัสได้ว่าเรากำลังใกล้เข้ามา!",
  ui_story_5035_50351401_56_dialog_content = "กลับมา!",
  ui_story_5035_50351401_57_dialog_content = "ฉันขอโทษ แต่ฉันไปต่อไม่ได้แล้ว",
  ui_story_5035_50351401_58_dialog_content = "หา?",
  ui_story_5035_50351401_59_dialog_content = "มีบางอย่างอยู่ในนั้น สิ่งที่สามารถฆ่าฉันได้",
  ui_story_5035_50351401_60_dialog_content = "ฉันรู้แล้ว ไม่ใช่พร็อพ แต่เป็นโลงศพจริง...",
  ui_story_5035_50351401_61_dialog_content = "เกิดอะไรขึ้นกับเรื่องไร้สาระเหล่านี้ในวันนี้ ??",
  ui_story_5035_50351401_62_dialog_content = "เอาล่ะ เรามาเปลี่ยนเส้นทางและอยู่ห่างจากมันเสียที",
  ui_story_5035_50351401_63_dialog_content = "มีทางออกอื่นอีกไหม?",
  ui_story_5035_50351401_64_dialog_content = "เมื่อเห็นว่ามันเพิ่งปรากฏที่นี่จากที่ไหนก็ไม่รู้ มันจะไม่ปรากฏที่อื่นด้วยหรือ?",
  ui_story_5035_50351401_65_dialog_content = "สิ่งที่คุณพูดก็คือ...",
  ui_story_5035_50351401_66_dialog_content = "เราจะต้องเปิดมัน ทุกคนพร้อมกัน",
  ui_story_5035_50351401_67_dialog_content = "เรากำลังทำสิ่งนี้อย่างจริงจังหรือไม่?",
  ui_story_5035_50351401_68_dialog_content = "การรู้ว่าเรากำลังเผชิญอะไรอยู่จะปลอดภัยกว่า แทนที่จะปล่อยให้รอเราอยู่ในความมืด",
  ui_story_5035_50351401_69_dialog_content = "คิดว่าไงบ้าง",
  ui_story_5035_50351401_70_dialog_content = "คุณไม่ผิด...",
  ui_story_5035_50351401_71_dialog_content = "ฉัน... ฉันกลัว แต่...",
  ui_story_5035_50351401_72_dialog_content = "อยากรู้จริงๆว่ามีอะไรอยู่ในนั้น...",
  ui_story_5035_50351401_73_dialog_content = "ฮือ ๆ ๆ",
  ui_story_5035_50351401_74_dialog_content = "โอเค ไปกันเลย! พร้อมกันทุกคน!",
  ui_story_5035_50351401_75_dialog_content = "มันเป็นอันตรายถึงตายเพียงเล็กน้อย ไม่มีอะไรที่เราไม่เคยเจอมาก่อน!",
  ui_story_5035_50351401_76_dialog_content = "ถูกตัอง! ไม่มีอะไรต้องกลัว ไม่มีอะไรเลย...",
  ui_story_5035_50351401_77_dialog_content = "ไม่เป็นอะไร. ตอนนี้ให้จดจ่อและอยู่ใกล้ ๆ",
  ui_story_5035_50351401_78_dialog_content = "พร้อมที่จะตอบสนองต่อสิ่งที่เกิดขึ้นทันทีทันใด",
  ui_story_5035_50351401_79_dialog_content = "พร้อมกันแล้ว ก้าวหน้า...",
  ui_story_5035_50351401_80_dialog_content = "หยุด! หยุดตรงนั้น!",
  ui_story_5035_50351401_81_dialog_content = "หา?",
  ui_story_5035_50351401_82_dialog_content = "ผู้กำกับจอนนี่?!",
  ui_story_5035_50351401_83_dialog_content = "อย่าขยับ! ขอเวลาฉันหน่อยได้ไหม ฉันขอร้อง!",
  ui_story_5035_50351401_84_dialog_content = "ไม่มีทางเป็นไปได้ที่ภาพนี้จะถูกทำซ้ำ! ฉันพลาดโอกาสนี้ไม่ได้",
  ui_story_5035_50351401_85_dialog_content = "หนึ่งนาที! เพียง 60 วินาทีสั้นๆ เชื่อฉัน! ฉันเป็นมืออาชีพหลังจากทั้งหมด",
  ui_story_5035_50351401_86_dialog_content = "คุณหมายความว่าอย่างไรโดยที่?",
  ui_story_5035_50351401_87_dialog_content = "ตอนนี้คุณทำอะไรอยู่ จอนนี่?",
  ui_story_5035_50351401_88_dialog_content = "อีกด้วย!!! โลงศพนี้คืออะไร?",
  ui_story_5035_50351401_89_dialog_content = "แสงสว่าง อยากได้แสงจากมุมนี้",
  ui_story_5035_50351401_90_dialog_content = "ขยับกล้องเข้าไปใกล้อีกนิด...",
  ui_story_5035_50351401_91_dialog_content = "ที่นั่น! แค่นั้นแหละ.",
  ui_story_5035_50351401_92_dialog_content = "และสุดท้าย ไมค์! แย่แล้ว ปุ่มค้างอีกแล้ว!",
  ui_story_5035_50351401_93_dialog_content = "พรุ่งนี้คุณจะไปที่กองเศษเหล็กแล้วเพื่อน",
  ui_story_5035_50351401_94_dialog_content = "ผู้ดูแลสคริปต์อยู่ที่ไหน สคริปต์!!",
  ui_story_5035_50351401_95_dialog_content = "ลืมมันไปเถอะ ฉันจะทำมันเอง",
  ui_story_5035_50351401_96_dialog_content = "อีกแค่วินาทีเดียวเท่านั้น นี่ไง!",
  ui_story_5035_50351401_97_dialog_content = "ฉันต้องจุดไฟ แอสเตอร์ชอบกลิ่นของมันที่แผดเผา",
  ui_story_5035_50351401_98_dialog_content = "<color=#e8d9bb>ฟิ้วว—</color>",
  ui_story_5035_50351401_99_dialog_content = "เอาล่ะ โยน! ขอโทษที่ให้รอนาน",
  ui_story_5035_50351401_100_dialog_content = "ตอนนี้ เราจะถ่ายทำบทสรุปอันน่าตื่นเต้นของ One Cut of Screams!",
  ui_story_5035_50351401_101_dialog_content = "ฉันเชื่อว่าฉากนี้จะทำให้หนังของฉันสมบูรณ์แบบ เป็นผลงานที่ทั้งมีศิลปะและมีพลังในเชิงพาณิชย์อย่างแท้จริง และจะทำให้อาชีพของทุกคนในห้องนี้",
  ui_story_5035_50351401_102_dialog_content = "ฉันรู้สึกอ่อนน้อมถ่อมตนที่ได้รับเกียรติที่ได้ร่วมงานกับพวกคุณทุกคนและ <color=#FFB400>แอสเตอร์</color>ในผลงานชิ้นเอกที่มีวิสัยทัศน์นี้",
  ui_story_5035_50351401_103_dialog_content = "แอสเตอร์?",
  ui_story_5035_50351401_104_dialog_content = "ไม่นะ ชื่อนั้นอีกแล้ว...",
  ui_story_5035_50351401_105_dialog_content = "ดังนั้นโดยไม่ต้องกังวลใจอีกต่อไป...",
  ui_story_5035_50351401_106_dialog_content = "เตรียมตัวพบกับ my <color=#FFB400>นางเอก</color>!",
  ui_story_5035_50351401_107_dialog_content = "นางเอก?!!",
  ui_story_5035_50351401_108_dialog_content = "One Cut of Screams ฉากสุดท้าย ฉากที่หนึ่ง เทคหนึ่ง —",
  ui_story_5035_50351401_109_dialog_content = "การกระทำ!",
  ui_story_5035_50351401_110_dialog_content = "<color=#e8d9bb>กริ๊ง... กริ๊ง...</color>",
  ui_story_5035_50351401_111_dialog_content = "อะแฮ่มๆๆๆ!!!!!!",
  ui_story_5035_50351401_112_dialog_content = "โลงศพ! เสียงระฆังบนโลงศพดังขึ้น!",
  ui_story_5035_50351401_113_dialog_content = "<color=#e8d9bb>ปัง! ปัง!</color>",
  ui_story_5035_50351401_114_dialog_content = "แปลก. คราวนี้ไม่มีใครเข้าใกล้...",
  ui_story_5035_50351401_115_dialog_content = "<color=#e8d9bb>ปัง ปัง — ปัง ปัง!</color>",
  ui_story_5035_50351401_116_dialog_content = "อร๊ายยย!!!!",
  ui_story_5035_50351401_117_dialog_content = "ฝาปิด! ฝาโลงศพคือ...",
  ui_story_5035_50351401_118_dialog_content = "<color=#e8d9bb>ปัง-!!</color>",
  ui_story_5035_50351401_119_dialog_content = "*ไอ...ไอ*",
  ui_story_5035_50351401_120_dialog_content = "มีบางอย่างกำลังออกมา!",
  ui_story_5035_50351401_121_dialog_content = "ม-มันคืออะไรเหรอครับ?",
  ui_story_5035_50351401_122_dialog_content = "มัน... SS-เธอ...",
  ui_story_5035_50351401_123_dialog_content = "สตรีชุดขาวที่ปรากฎอยู่ข้างหลังเราในครั้งนั้น...",
