  ui_story_5035_50351401_125_dialog_content = "*โฮก*",
  ui_story_5035_50351401_126_dialog_content = "เรื่องนี้ทำให้ฉันนึกถึงฉากหนึ่งในภาพยนตร์เรื่องอื่นของจอนนี่",
  ui_story_5035_50351401_127_dialog_content = "ฉากอะไร?",
  ui_story_5035_50351401_128_dialog_content = "สัตว์ประหลาดปีนออกจากโลงศพเพียงเพื่อลากใครบางคนเข้าไป",
