  ui_story_5035_50351401_130_dialog_content = "สุดท้ายเลือดสาดกระเซ็นเลนส์กล้อง และ \"จุดจบ\" ก็ปรากฏบนหน้าจอท่ามกลางสีแดงสดทั้งหมด",
  ui_story_5035_50351401_131_dialog_content = "ลากเข้าโลง...",
  ui_story_5035_50351401_132_dialog_content = "เดี๋ยวนะ หมายความว่าเรา...",
  ui_story_5035_50351401_133_dialog_content = "ถ่ายฉากเดียวกัน?!",
  ui_story_5035_50351401_134_dialog_content = "เธอ เธอกำลังมา!",
  ui_story_5035_50351401_135_dialog_content = "แกรรรรรรรร!!",
  ui_story_5035_50351401_136_dialog_content = "เธอกำลังมา! รีบวิ่ง! วิ่ง!",
  ui_story_5035_50351401_137_dialog_content = "กรี๊ด!!",
  ui_story_5035_50351401_138_dialog_content = "เธอกำลังตามทัน!",
  ui_story_5035_50351401_139_dialog_content = "ใกล้แค่ไหน?",
  ui_story_5035_50351401_140_dialog_content = "ฉันไม่รู้! ฉันไม่มองย้อนกลับไป!",
  ui_story_5035_50351401_141_dialog_content = "เอ๊ะ กลิ่นอะไร",
  ui_story_5035_50351401_142_dialog_content = "แพตซี่จะเป็นลม",
  ui_story_5035_50351401_143_dialog_content = "ไม่นะ! ถ้าเราไปต่อในทิศทางนี้...",
  ui_story_5035_50351401_144_dialog_content = "ว่าไง",
  ui_story_5035_50351401_145_dialog_content = "ถ้าจอนนี่ล็อกประตูไว้ข้างหน้า นี่คงเป็นทางตัน",
  ui_story_5035_50351401_146_dialog_content = "อะไร?! ดังนั้นสิ่งที่เราจะทำในขณะนี้?!",
