  ui_story_5035_50351401_148_dialog_content = "กรี๊ด!!",
  ui_story_5035_50351401_149_dialog_content = "ไม่เห็นจะเป็นแฟนกันเลย!",
  ui_story_5035_50351401_150_dialog_content = "ทางเลือกเดียวของเราคือทุบประตูที่ปลายทางเดิน",
  ui_story_5035_50351401_151_dialog_content = "ไม่เป็นไร ไม่ยากเกินไปที่จะพังประตู!",
  ui_story_5035_50351401_152_dialog_content = "มันไม่ง่ายอย่างนั้น ฉันเสริมความแข็งแกร่งให้ประตูบ้านผีสิงทุกบานให้ทนทานต่อแสง",
  ui_story_5035_50351401_153_dialog_content = "เสริมแกร่ง! ทำไมบนโลกนี้คุณถึงเลือกที่จะทำสิ่งที่ไม่จำเป็นโดยสิ้นเชิง!",
  ui_story_5035_50351401_154_dialog_content = "ฉันคิดว่าแขกบางคนอาจจะทำปฏิกิริยาเกินจริงและทำให้อาคารเสียหายได้",
  ui_story_5035_50351401_155_dialog_content = "ฉันไม่เคยคาดหวังว่าจะต้องทำลายพวกเขาด้วยตัวเอง",
