  ui_story_5035_50351401_158_dialog_content = "ถูกตัอง! คุณไม่ได้เสริมกำลังกำแพงใช่ไหม",
  ui_story_5035_50351401_159_dialog_content = "ไม่ แต่พวกมันค่อนข้างแข็งแกร่งในตัวเอง และการฝ่าฟันอาจต้องใช้เวลาสักระยะ",
