  ui_story_5035_50351401_188_dialog_content = "<color=#e8d9bb>ผัวะ!</color>",
  ui_story_5035_50351401_189_dialog_content = "ไมนอส!!",
  ui_story_5035_50351401_190_dialog_content = "เราจะช่วยพา Vice ออกไป ลูกสุนัข!",
  ui_story_5035_50351401_191_dialog_content = "โฮะโฮะโฮะ! โฮะโฮะโฮะ!",
  ui_story_5035_50351401_192_dialog_content = "เธอแข็งแกร่งเกินไป... ฉันไม่สามารถเป็นอิสระได้",
  ui_story_5035_50351401_193_dialog_content = "พวกเราทำอะไรได้บ้าง...? มันต้องมีอะไรแน่ๆ...",
  ui_story_5035_50351401_194_dialog_content = "ใช่! นั่นคือรูปลักษณ์! เราต้องการโคลสอัพที่นี่! ใกล้ชิด!",
  ui_story_5035_50351401_195_dialog_content = "ไอ้เหี้ย!",
  ui_story_5035_50351401_196_dialog_content = "ชู—",
  ui_story_5035_50351401_197_dialog_content = "อย่าคุยกับฉัน! พูดคุยกับตัวละครในภาพยนตร์",
  ui_story_5035_50351401_198_dialog_content = "นี่คือผลงานชิ้นเอกที่คุณกำลังจะสร้างโดยแลกกับชีวิตของคุณ! ความเป็นมืออาชีพของคุณอยู่ที่ไหน",
  ui_story_5035_50351401_199_dialog_content = "เธอ...",
  ui_story_5035_50351401_200_dialog_content = "ให้มืออาชีพจัดการเถอะ!",
  ui_story_5035_50351401_201_dialog_content = "<color=#e8d9bb>ปัง! ปัง! ปัง!</color>",
  ui_story_5035_50351401_202_dialog_content = "อ่าฮะ! ใครเปิดแฟลช!",
  ui_story_5035_50351401_203_dialog_content = "งานนี้เสียทั้งฉาก!!",
  ui_story_5035_50351401_204_dialog_content = "กราาาา...",
  ui_story_5035_50351401_205_dialog_content = "เธอปล่อยแล้ว!",
  ui_story_5035_50351401_206_dialog_content = "ตอนนี้! หนีไปจากเธอ!",
  ui_story_5035_50351401_207_dialog_content = "ใช่!",
  ui_story_5035_50351401_208_dialog_content = "เมื่อกี้คือลิลิก้าเหรอ?",
  ui_story_5035_50351401_209_dialog_content = "ตัวเลือกภาพยนตร์ของคุณช่างน่าสงสาร จอนนี่",
  ui_story_5035_50351401_210_dialog_content = "สถานที่ที่ดีที่สุดในการถ่ายภาพฉากนี้คือจุดที่ฉันยืน และคุณเรียกตัวเองว่ามืออาชีพจริงๆ!",
  ui_story_5035_50351401_211_dialog_content = "ลิลิก้า...",
  ui_story_5035_50351401_212_dialog_content = "ฉันไม่เคยคิดเลยว่าคุณจะมาหาฉันโดยสมัครใจ",
  ui_story_5035_50351401_213_dialog_content = "คุณสอนฉันว่านักแสดงมักจะถ่ายทำเสร็จเสมอ",
  ui_story_5035_50351401_214_dialog_content = "ฉันเชื่อว่าฉันเป็นหนี้คุณตอนจบ!",
  ui_story_5035_50351401_215_dialog_content = "อา... ดียิ่งขึ้นไปอีก",
  ui_story_5035_50351401_216_dialog_content = "ฉันแค่กังวลว่าฉากนั้นสั้นเกินไป",
