  ui_story_5035_50351401_218_dialog_content = "คุณกังวลเรื่องอะไร",
  ui_story_5035_50351401_219_dialog_content = "ไมนอส! โชคดีที่คุณไม่เป็นไร!",
  ui_story_5035_50351401_220_dialog_content = "...",
  ui_story_5035_50351401_221_dialog_content = "แน่นอนฉันเป็น ฉันไม่ได้คาดหวังว่าจะถูกโลงศพตี",
  ui_story_5035_50351401_222_dialog_content = "ฉันเป็นผู้ผลิตภาพยนตร์เรื่องนี้ ถ้าผู้กำกับจอนนี่อยากต่อสู้ในรายการ เขาจะได้มันมา",
  ui_story_5035_50351401_223_dialog_content = "คุณทุกคนทุ่มเทมาก!",
  ui_story_5035_50351401_224_dialog_content = "ฉันจะปล่อยให้พวกคุณที่เหลือ ฉันแสดงเสร็จแล้ว",
  ui_story_5035_50351401_225_dialog_content = "ให้ฉันแนะนำตัวเองอีกครั้ง: นี่คือ Super Sadie Swashbuckler 666 นักต้มตุ๋นที่ไม่เคยพาดพิงถึงใคร",
  ui_story_5035_50351401_226_dialog_content = "วันนี้ฉันจะทุบตีคุณจนกัดฝุ่นและทนทุกข์กับสิ่งที่เป็นอยู่!",
  ui_story_5035_50351401_227_dialog_content = "\"อาชญากร Jonny Caught\" เอกสารจะกล่าวว่าบนอัฒจันทร์ที่จัดแสดงในวันพรุ่งนี้!",
  ui_story_5035_50351401_228_dialog_content = "ว้าว ฉันไม่รู้ว่าคุณจะคล้องจองกันได้ด้วย!",
