  ui_story_5035_50351401_230_dialog_content = "เอาล่ะทุกคน เตรียมตัวให้พร้อม!",
  ui_story_5035_50351401_231_dialog_content = "ผีที่มองเห็นและจับต้องได้ไม่มีอะไรน่ากลัว! มันเป็นแค่สัตว์ประหลาดตัวอื่น!",
