  ui_story_5035_50351401_233_dialog_content = "มีนางเอกเพียงคนเดียวเท่านั้น นั่นคือฉัน!",
  ui_story_5035_50351401_234_dialog_content = "ตอนนี้เมื่อทุกคนมีความกระตือรือร้นแล้ว ไม่มีอะไรจะดีไปกว่านี้แล้ว!",
