  ui_story_5035_50351401_236_dialog_content = "การกระทำ!",
  ui_story_5035_50351402_1_dialog_content = "<color=#e8d9bb>ตี! ตุ๊ด!</color>",
  ui_story_5035_50351402_2_dialog_content = "กรี๊สสสสส!!",
  ui_story_5035_50351402_3_dialog_content = "<color=#e8d9bb>วู้—!!</color>",
  ui_story_5035_50351402_4_dialog_content = "พวกคุณสบายดีไหม!",
  ui_story_5035_50351402_5_dialog_content = "*แค่ก*",
  ui_story_5035_50351402_6_dialog_content = "อ๊ากก...",
  ui_story_5035_50351402_7_dialog_content = "เอ่อ ฉันไม่รู้สึกถึงร่างกายของฉันจริงๆ",
