  ui_story_5035_50351402_9_dialog_content = "ยังเลย...",
  ui_story_5035_50351402_10_dialog_content = "แต่ดูเหมือนเธอจะอ่อนแอลงอย่างมาก",
  ui_story_5035_50351402_11_dialog_content = "กร๊าก...กร๊าก...",
  ui_story_5035_50351402_12_dialog_content = "เราเอาชนะความลึกลับทุกออนซ์จากเธอในการสู้รบครั้งนั้น",
  ui_story_5035_50351402_13_dialog_content = "ใช่ เธอปลดปล่อย Darkflow ที่แข็งแกร่งออกมา ตอนนี้เธอเหมือนกับ Eclipsite แบบเก่าทั่วไป",
  ui_story_5035_50351402_14_dialog_content = "บางทีเธออาจเป็นเพียง Eclipsite พิเศษบางอย่างในตอนแรก",
  ui_story_5035_50351402_15_dialog_content = "เราใกล้จะถึงจุดสิ้นสุดแล้ว ใครจะทนได้นานกว่ากัน เธอหรือเรา",
