  ui_story_5035_50351402_18_dialog_content = "!!!",
  ui_story_5035_50351402_19_dialog_content = "อ๊ะ เทียนนั่น!",
  ui_story_5035_50351402_20_dialog_content = "มันทำให้ Astor แข็งแกร่งขึ้น",
