  ui_story_5035_50351402_22_dialog_content = "อดใจรออีกนิด...",
  ui_story_5035_50351402_23_dialog_content = "กราาาา...",
  ui_story_5035_50351402_24_dialog_content = "ไปหาพวกเขา! ไปและบริโภคพวกมัน! กินเพียงชิ้นเดียวและความแข็งแรงทั้งหมดของคุณจะได้รับการฟื้นฟู",
