  ui_story_5035_50351402_26_dialog_content = "กราร์...",
  ui_story_5035_50351402_27_dialog_content = "อนิจจาฉันไม่สามารถช่วย ฉันมีเรื่องที่เร่งด่วนกว่าจะเข้าร่วม",
  ui_story_5035_50351402_28_dialog_content = "ฉันต้องจับทุกการเคลื่อนไหวของคุณ",
