  ui_story_5035_50351402_33_dialog_content = "คุณรู้สึกไหม? ความอบอุ่นที่คุณสูญเสียไปนานแล้ว",
  ui_story_5035_50351402_34_dialog_content = "ตราบใดที่ความร้อนยังเพิ่มขึ้นในตัวคุณ คุณก็ยังไม่ตายอย่างแท้จริง",
  ui_story_5035_50351402_35_dialog_content = "อย่างน้อยคุณก็ยังมีชีวิตอยู่! ฉันทำให้คุณมีชีวิตอีกครั้ง!",
  ui_story_5035_50351402_36_dialog_content = "เพียงแค่มองไปที่พวกเขา คนเหล่านั้นมีพลังชีวิตที่คุณต้องการ แต่ไม่แสดงความคารวะหรือขอบคุณสำหรับสิ่งนั้น",
