  ui_story_5035_50351402_41_dialog_content = "เราต้องดับเทียน มิฉะนั้นเธอจะฟื้นกำลัง!",
  ui_story_5035_50351402_42_dialog_content = "โอเค แยกย้ายกันไป ไวซ์กับฉันจะทำให้เธอเสียสมาธิ ขณะที่พวกคุณที่เหลือก็คิดหาวิธีดับเทียน",
  ui_story_5035_50351402_43_dialog_content = "เข้าใจแล้ว!",
  ui_story_5035_50351402_44_dialog_content = "คุณหันเหความสนใจของเธอ? คุณสองคนจะไม่เป็นไรไหม",
