  ui_story_5035_50351402_58_dialog_content = "ถ้าคุณไม่ต้องการให้เกิดขึ้น คุณควรมอบเทียนให้!",
  ui_story_5035_50351402_59_dialog_content = "ไม่ใช่อุปกรณ์ประกอบฉากในภาพยนตร์ อย่าให้ความสนใจมากเกินไป",
  ui_story_5035_50351402_60_dialog_content = "เลิกเสียเวลากับเขาได้แล้วทั้งสองคน! Minos และ Vice สามารถระงับ Astor ได้ชั่วคราวเท่านั้น",
