  ui_story_5035_50351402_63_dialog_content = "*ไอ* นั่นอะไรน่ะ?",
  ui_story_5035_50351402_64_dialog_content = "ก๊าาาซ!",
  ui_story_5035_50351402_65_dialog_content = "สุริยุปราคา?! หมดแล้วหมดเลย!",
