  ui_story_5035_50351402_79_dialog_content = "ไวซ์!",
  ui_story_5035_50351402_80_dialog_content = "ไม่นะ ดูเหมือนว่าพวกเขาจะสูญเสียพลังไปที่นั่นเช่นกัน",
