  ui_story_5035_50351402_86_dialog_content = "มาวิ่งกันเถอะ PlayerName.",
  ui_story_5035_50351402_87_dialog_content = "เผ่น?",
  ui_story_5035_50351402_88_dialog_content = "ใช่. ฉันวิ่งหนีเก่งมาก! แค่ตามฉันมา",
  ui_story_5035_50351402_89_dialog_content = "ตราบใดที่เราออกไปจากที่นี่ เราสามารถเปิดเผยตัวตนที่แท้จริงของจอนนี่สู่โลกได้! เขาต้องถูกลงโทษ!",
  ui_story_5035_50351402_90_dialog_content = "เราจะ... ออกไปจากที่นี่ได้จริงๆ เหรอ...?",
  ui_story_5035_50351402_91_dialog_content = "แม้ว่าเราจะออกไปจากที่นี่แล้วคนอื่นๆ ที่ยังอยู่ในบ้านล่ะ?",
  ui_story_5035_50351402_92_dialog_content = "คนอื่น ๆ...",
  ui_story_5035_50351402_93_dialog_content = "ทุกคน โปรดฟัง!!",
  ui_story_5035_50351402_94_dialog_content = "ตีพวกเขาอย่างแรง! ไม่แสดงความเมตตา!",
  ui_story_5035_50351402_95_dialog_content = "เอ๊ะ? นั่นใครน่ะ?!",
  ui_story_5035_50351402_96_dialog_content = "กรร!",
  ui_story_5035_50351402_97_dialog_content = "ฉันกำลังแสดง Eclipsite วันนี้! อย่ามาดูถูกงานของฉันนะ!",
  ui_story_5035_50351402_98_dialog_content = "เกิดอะไรขึ้น? สุริยุปราคากำลังต่อสู้กันเอง?",
  ui_story_5035_50351402_99_dialog_content = "Eclipsites บางตัวเป็นพนักงานบ้านผีสิงในชุด!",
  ui_story_5035_50351402_100_dialog_content = "เกรี้ยวกราด!!!",
  ui_story_5035_50351402_101_dialog_content = "ดังเกินไป ดังเกินไป!",
  ui_story_5035_50351402_102_dialog_content = "ความพิเศษที่ไร้จุดหมายเหล่านี้มาจากไหน? ออกจากชุดของฉัน!",
  ui_story_5035_50351402_103_dialog_content = "เรากำลังถ่ายทำกันอยู่นี่ เข้าใจมั้ย? กล้องมันกลิ้ง!",
  ui_story_5035_50351402_104_dialog_content = "เร็ว! ตอนนี้! ในขณะที่ชายคนนั้นยังมึนงง!",
  ui_story_5035_50351402_105_dialog_content = "คุณได้ยินใช่มั้ย? PlayerName ต้องการเทียนเล่มนั้น",
  ui_story_5035_50351402_106_dialog_content = "รู้แล้วน่า!",
  ui_story_5035_50351402_107_dialog_content = "มันคืออะไร",
  ui_story_5035_50351402_108_dialog_content = "ก๊อทชา! ฉันกลืนมัน!",
  ui_story_5035_50351402_109_dialog_content = "PlayerNameคุณต้องการสิ่งเหล่านี้หรือไม่?",
  ui_story_5035_50351402_110_dialog_content = "ว้าว! คุณสามารถคว้าเทียนได้!",
  ui_story_5035_50351402_111_dialog_content = "เฮ้! วางมันลง!",
  ui_story_5035_50351402_112_dialog_content = "ฮิฮิ! คุณจับฉันไม่ได้!",
  ui_story_5035_50351402_113_dialog_content = "ฟาดไปอีกตัว!",
  ui_story_5035_50351402_114_dialog_content = "นกกระจอกน้อยเจ้าปัญหา! ฉันจะไปหาคุณเร็ว ๆ นี้!",
  ui_story_5035_50351402_115_dialog_content = "เรายังไม่เสร็จ จอนนี่",
  ui_story_5035_50351402_116_dialog_content = "ซาดี? ดูที่คุณ เคยเป็นคนที่ไม่แน่นอนใช่มั้ย?",
  ui_story_5035_50351402_117_dialog_content = "ถึงกระนั้น คุณก็สามารถคว้าเทียนได้เพียงสองเล่มเท่านั้น ส่วนอื่นๆ ยังสว่างอยู่",
  ui_story_5035_50351402_118_dialog_content = "กลับมาหาฉัน แอสเตอร์! กลับมาหาข้าและกลืนกินนกกระจอกเหล่านี้",
  ui_story_5035_50351402_119_dialog_content = "แกรรรรรรรร!!",
  ui_story_5035_50351402_120_dialog_content = "จึงมีเทียนอื่นๆ",
  ui_story_5035_50351402_121_dialog_content = "ชอบอันนี้?",
  ui_story_5035_50351402_122_dialog_content = "!!!",
  ui_story_5035_50351402_123_dialog_content = "เดี๋ยวก่อน คุณได้มันมาเมื่อไหร่!",
  ui_story_5035_50351402_124_dialog_content = "ดูเหมือนนายจะลืมไปแล้วว่าฉันเป็นคนขี้ขลาด!",
  ui_story_5035_50351402_125_dialog_content = "แอสเตอร์มาแล้ว! เป่าเทียนเร็ว!",
  ui_story_5035_50351402_126_dialog_content = "ได้สิ",
  ui_story_5035_50351402_127_dialog_content = "ถึงตาคุณห่อ จอนนี่",
  ui_story_5035_50351402_128_dialog_content = "*เป่าเทียน*",
  ui_story_5035_50351402_129_dialog_content = "กร๊าก...กร๊าก...รา...",
  ui_story_5035_50351402_130_dialog_content = "กราร์...",
  ui_story_5035_50351402_131_dialog_content = "ยอดเยี่ยม! เธอกำลังสูญเสียพลังของเธอ!",
  ui_story_5035_50351402_132_dialog_content = "ดูเหมือนว่าเราเป็นคนที่เหลืออยู่",
  ui_story_5035_50351402_133_dialog_content = "อย่าก้าวไปข้างหน้าของตัวเอง เธอยังไม่หมดแรง และใครจะว่าจอนนี่ยังไม่มีเทียนเล่มอื่นซ่อนอยู่",
  ui_story_5035_50351402_134_dialog_content = "แต่ถึงแม้นางจะอ่อนแอ เรามาจบเรื่องนี้กันเถอะ!",
  ui_story_5035_50351402_135_dialog_content = "เข้าใจแล้ว!",
  ui_story_5035_50351402_136_dialog_content = "Rapid Tor—",
  ui_story_5035_50351402_137_dialog_content = "ไม่!!!",
  ui_story_5035_50351402_138_dialog_content = "คุณไม่สามารถทำเช่นนี้ได้! ไม่มีทาง! ไม่ได้อย่างแน่นอน!",
  ui_story_5035_50351402_139_dialog_content = "นี่เป็นตอนจบที่แย่มาก! หนังของฉันไม่จบแบบนี้!",
  ui_story_5035_50351402_140_dialog_content = "ผู้ชายคนนี้ต้องการปกป้อง Astor?",
  ui_story_5035_50351402_141_dialog_content = "เราเพิ่งจะโจมตี เขาไม่กลัวตายเหรอ?",
  ui_story_5035_50351402_142_dialog_content = "ดูสิ่งที่คนที่น่ากลัวเหล่านี้ทำกับคุณ! ชุดที่น่ารักของคุณฉีกขาด",
  ui_story_5035_50351402_143_dialog_content = "โอ้ แอสเตอร์! My Astor นางเอกของฉัน...",
  ui_story_5035_50351402_144_dialog_content = "ฉันรู้ว่าคุณต้องเหนื่อย คุณต้องหนาวมากเพราะไฟดับไปทีละดวง",
  ui_story_5035_50351402_145_dialog_content = "โลกนี้ช่างโหดร้ายเสมอมา ไม่มีใครแบ่งปันความอบอุ่นกับคุณ",
  ui_story_5035_50351402_146_dialog_content = "แต่อย่ากลัวเลย แอสเตอร์ของฉัน คุณมีฉัน.",
  ui_story_5035_50351402_147_dialog_content = "มาสัมผัสความอบอุ่นของฉัน",
  ui_story_5035_50351402_148_dialog_content = "กินฉัน แอสเตอร์ แล้วคุณจะมีเรี่ยวแรงที่จะเผชิญหน้าพวกมัน",
  ui_story_5035_50351402_149_dialog_content = "เขา... เขากำลังเคลื่อนเข้าหาเธอ!",
  ui_story_5035_50351402_150_dialog_content = "... เขาบ้า",
  ui_story_5035_50351402_151_dialog_content = "เราควรจะหยุดเขาไหม?",
  ui_story_5035_50351402_152_dialog_content = "ยังไง...? โดยการจบเขาออก?",
  ui_story_5035_50351402_153_dialog_content = "ลิลิก้า!",
  ui_story_5035_50351402_154_dialog_content = "ฮะ? เขาโทรหาฉันเหรอ?",
  ui_story_5035_50351402_155_dialog_content = "หยิบกล้องขึ้นมาสิ ลิลิก้า! ต้องถ่ายฉากที่กำลังจะแฉ!",
  ui_story_5035_50351402_156_dialog_content = "ขอร้องล่ะ ถ่ายเลย คุณต้องถ่ายมัน",
  ui_story_5035_50351402_157_dialog_content = "ว-คุณกำลังพยายามทำอะไรในครั้งนี้?",
  ui_story_5035_50351402_158_dialog_content = "ต้องแก้ไขเป็นภาพที่เราถ่ายไว้ก่อนหน้านี้",
  ui_story_5035_50351402_159_dialog_content = "ใช่ ใช่ ใช่ สิ่งนี้จะทำให้ตอนจบสมบูรณ์แบบ ดีเกินคาด!",
  ui_story_5035_50351402_160_dialog_content = "งานสุดท้ายของฉัน ผลงานชิ้นโบแดงของฉัน ซึ่งจะนำ Astor ไปสู่จุดสูงสุด อนิจจา ไม่มีใครเหมาะสมกับบทนำมากไปกว่าฉันแล้ว",
  ui_story_5035_50351402_161_dialog_content = "มีเพียงแอสเตอร์และตัวฉันเท่านั้นที่สามารถถ่ายทำบางสิ่งที่คุ้มค่าที่จะเป็นจุดสุดยอดในอาชีพการงานของฉัน",
  ui_story_5035_50351402_162_dialog_content = "คุณบ้า! จะเสียสละตัวเอง?!",
  ui_story_5035_50351402_163_dialog_content = "เปิดกล้องของคุณ!!!",
  ui_story_5035_50351402_164_dialog_content = "ฉันรู้สึกได้ ลมหายใจอันเยือกเย็นของ Astor มาถึงฉันแล้ว",
  ui_story_5035_50351402_165_dialog_content = "ด่วนเลย! นี่คือศิลปะที่สมบูรณ์! ต้องไม่พลาดนัดเดียว!",
  ui_story_5035_50351402_166_dialog_content = "อย่าตลกเลย คุณไม่สามารถเรียกศิลปะนี้",
  ui_story_5035_50351402_167_dialog_content = "อะไรนะ!",
  ui_story_5035_50351402_168_dialog_content = "ใคร! ใครพูด!",
  ui_story_5035_50351402_169_dialog_content = "ศิลปะควรแสดงออกจากความหลงใหลและความพยายาม",
  ui_story_5035_50351402_170_dialog_content = "การหลอกลวงผู้อื่นไม่ใช่การอุทิศตน",
  ui_story_5035_50351402_171_dialog_content = "และการพึมพำกับศพไม่ใช่อารมณ์",
  ui_story_5035_50351402_172_dialog_content = "ที่นี่ไม่มีอะไรที่เรียกว่า \"ศิลปะ\"",
  ui_story_5035_50351402_173_dialog_content = "ฉันไม่เห็นอะไรนอกจากการตระหนักถึงความทะเยอทะยานที่น่าสมเพชของคุณ",
  ui_story_5035_50351402_174_dialog_content = "โกลดี้?! คุณยังมีชีวิตอยู่?!",
  ui_story_5035_50351402_175_dialog_content = "เพื่อที่ฉันจะได้มีตอนจบสำหรับคุณ",
  ui_story_5035_50351402_176_dialog_content = "หนึ่งที่จะตอบสนองผู้ชมจริงๆ",
  ui_story_5035_50351402_177_dialog_content = "คุณจำเทียนเล่มนี้ได้ไหม มันถูกเผาไหม้มาเป็นเวลานานและน่าจะเป็นครั้งแรกที่คุณจุดไฟ",
  ui_story_5035_50351402_178_dialog_content = "ฉันนำมันกลับมาให้คุณ",
  ui_story_5035_50351402_179_dialog_content = "ไม่!!! ไม่ใช่ตอนนี้!",
  ui_story_5035_50351402_180_dialog_content = "เร็วเข้า แอสเตอร์! เราหมดเวลาแล้ว!",
  ui_story_5035_50351402_181_dialog_content = "ดันอีก! เฉือนคอของฉันด้วยขากรรไกรล่างของคุณ!",
  ui_story_5035_50351402_182_dialog_content = "กินฉัน! กินฉันเดี๋ยวนี้!",
  ui_story_5035_50351402_183_dialog_content = "เร็วเข้า!",
  ui_story_5035_50351402_184_dialog_content = "ขอบคุณสำหรับการทำงานหนักของคุณจอนนี่",
  ui_story_5035_50351402_185_dialog_content = "นี่คือจุดจบ.'",
  ui_story_5035_50351402_186_dialog_content = "*เป่าเทียนเล่มสุดท้าย*",
  ui_story_5035_50351402_187_dialog_content = "ไม่!",
  ui_story_5035_50351402_188_dialog_content = "แอสเตอร์! แอสเตอร์! ยังอยู่มั้ย!",
  ui_story_5035_50351402_189_dialog_content = "ฉันอยู่ที่นี่! ฟังให้ดี นี่ฉันเอง!",
  ui_story_5035_50351402_190_dialog_content = "ตอบฉัน! ได้โปรดฉันขอให้คุณตอบฉัน!",
  ui_story_5035_50351402_191_dialog_content = "เราใกล้จะเสร็จแล้ว แอสเตอร์! ใกล้จะสร้างผลงานชิ้นเอก!",
  ui_story_5035_50351402_192_dialog_content = "<anim type=Shake><size=50>แอสเตอร์! แอสเตอร์—!!!</size></anim>",
  ui_story_5035_50351501_1_dialog_content = "<color=#e8d9bb>*ฝูงชนพึมพำ*</color>",
  ui_story_5035_50351501_2_dialog_content = "คุณได้ยินไหม บ้านนี้เพิ่งมีเสียงดัง",
  ui_story_5035_50351501_3_dialog_content = "ฉันได้ยินสิ่งที่ฟังดูเหมือนคำราม แต่ไม่ว่ามันจะเป็นอะไร มันไม่ปกติอย่างแน่นอน",
  ui_story_5035_50351501_4_dialog_content = "(ฉันอยากรู้จริงๆ ว่าเกิดอะไรขึ้นกับ Minos และ PlayerName ในนั้น?)",
  ui_story_5035_50351501_5_dialog_content = "(เปล่านะ! ถ้าเข้าไปจะไม่มีใครดูแลทางเข้า)",
  ui_story_5035_50351501_6_dialog_content = "ฉันได้ยินมาว่าที่นี่เพิ่งเปิดเป็นบ้านผีสิง",
  ui_story_5035_50351501_7_dialog_content = "โอ้คุณพูดถูก! เช็คป้าย!",
  ui_story_5035_50351501_8_dialog_content = "(เอ่อ...เสียงกรีดร้องของพวกเขาดูจะดึงดูดใจนักท่องเที่ยวอย่างคาดไม่ถึง...!)",
  ui_story_5035_50351501_9_dialog_content = "วันนี้เป็นการเปิดบ้านผีสิง Andersen Haunted House! ต้องการสัมผัสกับความตื่นเต้นที่น่ากลัวหรือไม่?",
  ui_story_5035_50351501_10_dialog_content = "บ้านผีสิงเหรอ? ดังนั้นเอฟเฟกต์เสียงเหล่านั้นก็แค่ทำให้ผู้คนหวาดกลัว?",
  ui_story_5035_50351501_11_dialog_content = "อะไรก็ตาม. เข้าไปชมกันเลยครับ. เราสามารถประกันตัวได้ถ้ามันน่าเบื่อ",
  ui_story_5035_50351501_12_dialog_content = "ประสบการณ์นี้ฟรีใช่ไหมครับคุณผู้หญิง",
  ui_story_5035_50351501_13_dialog_content = "อืม...",
  ui_story_5035_50351501_14_dialog_content = "รอก่อน! อย่าให้ใครเข้ามาอีก",
  ui_story_5035_50351501_15_dialog_content = "เอ๊ะ? เจน? คุณไปไหนมา...?",
  ui_story_5035_50351501_16_dialog_content = "(อืม และข้างหลังเจนคือ... รถม้าของกิลด์อัมบราตัน?!)",
  ui_story_5035_50351501_17_dialog_content = "<color=#e8d9bb>โว้ว...</color>",
  ui_story_5035_50351501_18_dialog_content = "สถานที่แห่งนี้ไม่ใช่เรื่องง่ายที่จะหา",
  ui_story_5035_50351501_19_dialog_content = "ดูไม่เหมือนทรัพย์สินของ Andersen",
  ui_story_5035_50351501_20_dialog_content = "นั่น... ลุงอิสต์วานเหรอ!",
  ui_story_5035_50351501_21_dialog_content = "โอ้ สวัสดีตอนบ่ายนีน่า",
  ui_story_5035_50351501_22_dialog_content = "สาวน้อย ดูเหมือนว่าคุณยังไม่รู้ว่าเกิดอะไรขึ้นในบ้านของคุณ",
  ui_story_5035_50351501_23_dialog_content = "ขอแสดงความยินดีกับการเปิดงาน Miss Nina",
  ui_story_5035_50351501_24_dialog_content = "(เชโอลก็อยู่ที่นี่ด้วย มันไม่ใช่... ปัญหาเรื่องใบอนุญาติธุรกิจของฉันใช่ไหม)",
  ui_story_5035_50351501_25_dialog_content = "เอ่อ ทุกคนได้โปรดรอสักครู่ได้ไหม ต้องติดต่อผู้รับผิดชอบ...",
  ui_story_5035_50351501_26_dialog_content = "คุณหมายถึง ไมนอส ? เขาอยู่ที่นี่แล้ว",
  ui_story_5035_50351501_27_dialog_content = "วันที่ดีทุกคน",
  ui_story_5035_50351501_28_dialog_content = "เขาอยู่ที่นี่",
  ui_story_5035_50351501_29_dialog_content = "ปล่อยฉันไป!!!",
  ui_story_5035_50351501_30_dialog_content = "ทุกคนควรสละชีวิตเพื่อหนังของฉัน!",
  ui_story_5035_50351501_31_dialog_content = "ฮึ่ม! แค่รอจนกว่าคุณจะเห็นว่าผมวาร์ปทุกช็อตของคุณในเทปได้อย่างไร!",
  ui_story_5035_50351501_32_dialog_content = "ฉันจะทำลายรูปลักษณ์และชื่อเสียงของคุณ!",
  ui_story_5035_50351501_33_dialog_content = "ฉันเข้าใจว่านี่คือตัวสร้างปัญหา?",
  ui_story_5035_50351501_34_dialog_content = "ใช่ ชาโดว์ลอร์ด",
  ui_story_5035_50351501_35_dialog_content = "เขาทำลายล้างทุกหนทุกแห่งภายในและเกือบจะทำร้ายแขกบางคน",
  ui_story_5035_50351501_36_dialog_content = "ไร้สาระ! มันคือศิลปะ!",
  ui_story_5035_50351501_37_dialog_content = "และเขาเป็นผู้กำกับที่ใช้ Eclipsite เพื่อถ่ายทำภาพยนตร์ของเขา!",
  ui_story_5035_50351501_38_dialog_content = "เขาไปไกลถึงขนาดฆ่าลูกเรือของตัวเองครั้งสุดท้ายที่เขาถ่ายทำที่นี่!",
  ui_story_5035_50351501_39_dialog_content = "ฉันอยู่ได้เพียงเพราะวิ่งหนีเก่ง! ฉันจะมีหลักฐานด้วย ถ้าเทปไม่เสียหาย",
  ui_story_5035_50351501_40_dialog_content = "หุบปากนะ!",
  ui_story_5035_50351501_41_dialog_content = "ระวังเท้าของเขานะ ลิลิก้า!",
  ui_story_5035_50351501_42_dialog_content = "<color=#e8d9bb>แผละ!</color>",
  ui_story_5035_50351501_43_dialog_content = "อ๊าาา!",
  ui_story_5035_50351501_44_dialog_content = "อะไรจะดีไปกว่าการสอนบทเรียนของเขาด้วยไม้เท้าดีๆ",
  ui_story_5035_50351501_45_dialog_content = "พาเขาออกไป. ตั้งข้อหาเขาเพราะเป็นการก่อกวนในที่สาธารณะ",
  ui_story_5035_50351501_46_dialog_content = "โอ้ และริบทรัพย์สินทั้งหมดของเขา",
  ui_story_5035_50351501_47_dialog_content = "ได้เลย",
  ui_story_5035_50351501_48_dialog_content = "แต่นายอิสต์วาน!",
  ui_story_5035_50351501_49_dialog_content = "วางใจได้เลย",
  ui_story_5035_50351501_50_dialog_content = "เราไม่ปฏิบัติตามขั้นตอนที่เข้มงวดใน Umbraton เพราะบ่อยครั้งที่กฎหมายปกป้องคนชั่วร้าย",
  ui_story_5035_50351501_51_dialog_content = "ส่วนข้อกล่าวหาของหญิงสาวคนนี้ต่อเขา...",
  ui_story_5035_50351501_52_dialog_content = "ไปและทำการสอบสวนอย่างละเอียด เจน",
  ui_story_5035_50351501_53_dialog_content = "ลงมือให้เร็วที่สุดเท่าที่จะทำได้ แล้ว Istvan Gang จะจัดการที่เหลือเอง",
  ui_story_5035_50351501_54_dialog_content = "เข้าใจแล้ว",
  ui_story_5035_50351501_55_dialog_content = "เดี๋ยว! ว-นี่มันเกิดอะไรขึ้นกันแน่เนี่ย!",
  ui_story_5035_50351501_56_dialog_content = "ผู้กำกับจอนนี่ได้รับสิ่งที่เขาสมควรได้รับ",
  ui_story_5035_50351501_57_dialog_content = "แต่สำหรับนีน่า ความจริงยังไม่ปรากฏ",
  ui_story_5035_50351501_58_dialog_content = "หึหึ... ถ้าอยากรู้ล่ะสิ คุณนีน่า—",
  ui_story_5035_50351501_59_dialog_content = "ถ้าอย่างนั้นก็รอการเปิดตัว Into the Haunted House ที่น่าตื่นเต้นได้เลย!",
  ui_story_5035_50351501_60_dialog_content = "<color=#e8d9bb>Umbraton Outskirts: บ้านผีสิง Andersen (หลายวันต่อมา)</color>",
  ui_story_5035_50351501_61_dialog_content = "<color=#e8d9bb>*ฝูงชนพึมพำ*</color>",
  ui_story_5035_50351501_62_dialog_content = "ว้าว ที่นี่คนเยอะมาก!",
  ui_story_5035_50351501_63_dialog_content = "ไม่เห็นจะจบแถวไหน!",
  ui_story_5035_50351501_64_dialog_content = "(ฉันกับรองกลับมาที่บ้านผีสิง Andersen คราวนี้ตามคำเชิญของ Minos)",
  ui_story_5035_50351501_65_dialog_content = "(เขายืนกรานที่จะชดเชยเหตุการณ์ครั้งที่แล้ว แต่เมื่อพิจารณาถึงความนิยมของธุรกิจในตอนนี้...)",
  ui_story_5035_50351501_66_dialog_content = "ไม่มีใครสามารถบีบที่นั่นได้อย่างแน่นอน!",
  ui_story_5035_50351501_67_dialog_content = "คุณมาที่นี่เพื่อออกจากงานด้วย PlayerName?",
  ui_story_5035_50351501_68_dialog_content = "ดูเหมือนว่าจิตใจที่ยิ่งใหญ่ของเราคิดเหมือนกันในวันนี้",
  ui_story_5035_50351501_69_dialog_content = "บัคขึ้น โดฟ! อย่าเผลอหลับก่อนที่เราจะเข้าไป!",
  ui_story_5035_50351501_70_dialog_content = "สวัสดีตอนเช้าพวก!",
  ui_story_5035_50351501_71_dialog_content = "มาเพราะตั๋วครึ่งราคาด้วยเหรอ?",
  ui_story_5035_50351501_72_dialog_content = "ครึ่งราคา? วันนี้ต้องจองตั๋วบ้านผีสิงล่วงหน้า คุณคิดว่าพวกเขาเสนอตั๋วครึ่งราคาจริงหรือไม่?",
  ui_story_5035_50351501_73_dialog_content = "หา?",
  ui_story_5035_50351501_74_dialog_content = "พวกคุณไม่รู้เหรอ? คุณยังไม่ได้ดู Into the Haunted House หรือยัง? มันได้รับความนิยมอย่างมากใน Umbraton!",
  ui_story_5035_50351501_75_dialog_content = "บ้านผีสิง Andersen นี้เป็นสถานที่จริงที่พวกเขายิงมัน!",
  ui_story_5035_50351501_76_dialog_content = "กลายเป็นไวรัลไปแล้ว! ถ้าคุณไม่ดู แสดงว่าคุณหมดห่วง!",
  ui_story_5035_50351501_77_dialog_content = "เวนดี้... เธอก็รู้นี่ PlayerName และรองอยู่ในนั้น?",
  ui_story_5035_50351501_78_dialog_content = "ฮะ?! ร-จริงเหรอ!",
  ui_story_5035_50351501_79_dialog_content = "เวนดี้หลบเลี่ยงการแสดง เธอบอกว่าเธอจะดูมันหลังจากมาที่นี่เท่านั้น",
  ui_story_5035_50351501_80_dialog_content = "Pepi และคนอื่นๆ ต่างก็อยากที่จะสปอยล์ แต่เธอไม่ยอมให้พวกเขา",
  ui_story_5035_50351501_81_dialog_content = "ฉันอยากมาสัมผัสประสบการณ์สยองขวัญด้วยตัวเอง!",
  ui_story_5035_50351501_82_dialog_content = "มันเยี่ยมมาก PlayerName! ดูเหมือนว่านีน่าและไมนอสไม่จำเป็นต้องกังวลเกี่ยวกับการขายตั๋วอีกต่อไป",
  ui_story_5035_50351501_83_dialog_content = "โอ้? สายตาของฉันหลอกลวงฉันไหม?",
  ui_story_5035_50351501_84_dialog_content = "ว้าว! ช่างเป็นการพบกันที่วิเศษจริงๆ!",
  ui_story_5035_50351501_85_dialog_content = "กลุ่มเพื่อนที่กล้าหาญ รอดชีวิตจากภยันตรายที่น่ากลัว แล้วพบกันใหม่ในสถานที่เดิม!",
  ui_story_5035_50351501_86_dialog_content = "ฉันควรบันทึกไว้: นี่ไม่ใช่สคริปต์! ฉันไม่ได้ตั้งค่านี้เพื่อเรตติ้งเท่านั้น!",
  ui_story_5035_50351501_87_dialog_content = "ไมนอสชวนเธอมาด้วยเหรอ ลิลิก้า?",
  ui_story_5035_50351501_88_dialog_content = "ชู่ PlayerName... ฉันกำลังถ่ายทำ! ถ่ายทำ!",
  ui_story_5035_50351501_89_dialog_content = "สวัสดีผู้ชม! ยินดีต้อนรับสู่ \"Into the Haunted House: The Aftershow\"!",
  ui_story_5035_50351501_90_dialog_content = "ซาดี นางเอกของเรากำลังจะพาเราไปรอบๆ บ้านผีสิง",
  ui_story_5035_50351501_91_dialog_content = "เฮ้ โย่ นี่คือ Super Sadie Swashbuckler 666 เต็มใจให้บริการคุณ!",
  ui_story_5035_50351501_92_dialog_content = "ยินดีด้วย ซาดี! คุณทำให้มันกลายเป็นไฟแก็ซ!",
  ui_story_5035_50351501_93_dialog_content = "ฉันแค่กำลังพยายามมุ่งสู่การเป็นเจ้าชู้ตัวจริง",
  ui_story_5035_50351501_94_dialog_content = "โอ้? คุณไม่คิดว่าการเป็นนักแสดงเสียเวลาอีกต่อไปแล้วเหรอ?",
  ui_story_5035_50351501_95_dialog_content = "ฉันคิดออกแล้ว",
  ui_story_5035_50351501_96_dialog_content = "ช่วยเหลือผู้อ่อนแอ ต่อสู้เพื่อความยุติธรรม และใช้ชีวิตอย่างอิสระ! นั่นคือจิตวิญญาณแห่งการโต้เถียงที่แท้จริง",
  ui_story_5035_50351501_97_dialog_content = "ฉันไม่หมกมุ่นอยู่กับการเป็นเจ้าชู้อีกต่อไปแล้ว",
  ui_story_5035_50351501_98_dialog_content = "น่าทึ่งมาก ซาดี! ฉันดีใจที่คุณได้มารับรู้นี้!",
  ui_story_5035_50351501_99_dialog_content = "ม-ไม่เป็นอะไร",
  ui_story_5035_50351501_100_dialog_content = "ยอดเยี่ยม! บรรยากาศแบบนี้สมบูรณ์แบบ! ตัด!",
  ui_story_5035_50351501_101_dialog_content = "ดูเหมือนว่าทุกคนมาถึงแล้ว",
  ui_story_5035_50351501_102_dialog_content = "คราวที่แล้วสถานการณ์ทำให้ฉันไม่สามารถเป็นเจ้าภาพที่สมบูรณ์แบบได้ ดังนั้น ได้โปรดอนุญาตให้ฉันทำสิ่งนี้ให้กับคุณ",
  ui_story_5035_50351501_103_dialog_content = "สำรวจบ้านผีสิงที่ได้รับการปรับปรุงใหม่ แล้วมารับประทานอาหารกลางวันที่คฤหาสน์ Andersen!",
  ui_story_5035_50351501_104_dialog_content = "ทั้ง Minos และ Sanae สาวใช้ของฉันนั้นยอดเยี่ยมมากในครัว!",
  ui_story_5035_50351501_105_dialog_content = "ฮ่า ๆ คุณให้เครดิตฉันมากเกินไปนางสาว",
  ui_story_5035_50351501_106_dialog_content = "คุณทั้งคู่สบายดีอีกครั้ง ฉันเข้าใจ",
  ui_story_5035_50351501_107_dialog_content = "คุณสามารถพูดได้ว่า ความเข้าใจผิดของเราได้รับการแก้ไขแล้ว",
  ui_story_5035_50351501_108_dialog_content = "โชคดีที่ฉันมีเทปของลิลิก้า มิฉะนั้น คำอธิบายของฉันจะดูอ่อนแอเล็กน้อย",
  ui_story_5035_50351501_109_dialog_content = "ฮ่าๆๆๆ! ในกรณีนั้น โปรดคอยติดตามโครงการในอนาคตของฉัน!",
  ui_story_5035_50351501_110_dialog_content = "รู้ไหม ฉันแค่คิดว่าฉันอาจมีพรสวรรค์ในการกำกับมากกว่าการแสดง!",
  ui_story_5035_50351501_111_dialog_content = "โอ้จริงเหรอ? คิดจะเปลี่ยนอาชีพ?",
  ui_story_5035_50351501_112_dialog_content = "ฉันกำลังพิจารณามัน! แต่การกำกับมีเรื่องยุ่งยากมากมาย และฉันก็ไม่รู้ด้วยซ้ำว่าจะเริ่มจากตรงไหน...",
  ui_story_5035_50351501_113_dialog_content = "ช่างเป็นเรื่องบังเอิญ! ไม่น่าเชื่อว่าทุกคนจะอยู่ที่นี่!",
  ui_story_5035_50351501_114_dialog_content = "ท่าทางวันนี้จะโชคดี!",
  ui_story_5035_50351501_115_dialog_content = "โอ้! โกลดี้! มันเป็นตลอดไป!",
  ui_story_5035_50351501_116_dialog_content = "ไปทำอะไรมา? คุณกำลังทำงานในโครงการอื่นหรือไม่?",
  ui_story_5035_50351501_117_dialog_content = "ฉันขอพักการแสดงสักครู่ ฉันเคย—",
  ui_story_5035_50351501_118_dialog_content = "รอสักครู่! รอ รอ รอ รอ รอ...",
  ui_story_5035_50351501_119_dialog_content = "(ทำไมเธอดูคุ้นเคยจัง!)",
  ui_story_5035_50351501_120_dialog_content = "โอ้! ฉันรู้! คือเธอ!!",
  ui_story_5035_50351501_121_dialog_content = "มันคือโกลดี้!!!",
  ui_story_5035_50351501_122_dialog_content = "พวกคุณได้ยินไหม? มันคือโกลดี้!",
  ui_story_5035_50351501_123_dialog_content = "อะไร จริงหรือ โกลดี้อยู่ที่นี่จริงๆเหรอ!",
  ui_story_5035_50351501_124_dialog_content = "<color=#e8d9bb>*ฝูงชนพึมพำ*</color>",
  ui_story_5035_50351501_125_dialog_content = "ว้าว! ทุกคนเริ่มตื่นเต้น!",
  ui_story_5035_50351501_126_dialog_content = "โกลดี้! ที่นี่! ฉันชอบที่จะถามคำถามคุณสองสามข้อ!",
  ui_story_5035_50351501_127_dialog_content = "ยินดีที่ได้พบคุณ! ฉันชื่อบรั่นดี ฝึกงานที่ The Daily Scoop!",
  ui_story_5035_50351501_128_dialog_content = "มีความกังวลเกี่ยวกับฉากใน Into the Haunted House ที่คุณต้องเผชิญกับอันตรายที่น่ากลัวเช่นนี้ พวกเขาเกิดขึ้นจริงเหรอ?",
  ui_story_5035_50351501_129_dialog_content = "ฉันคิดว่าทุกคนคงได้เห็นรายงานล่าสุดเกี่ยวกับเหตุการณ์นี้แล้ว",
  ui_story_5035_50351501_130_dialog_content = "เราติดอยู่กับอุบายของจอนนี่จริงๆ",
  ui_story_5035_50351501_131_dialog_content = "คุณเอาชีวิตรอดจากสิ่งที่ดูเหมือนจะเป็นความตายที่หลีกเลี่ยงไม่ได้ของคุณได้อย่างไร?",
  ui_story_5035_50351501_132_dialog_content = "ก็... มันอาจฟังดูแปลกๆ นิดหน่อย แต่ที่ฉันทำคือ...",
  ui_story_5035_50351501_133_dialog_content = "<color=#FFB400>ไม่มีอะไรจริงๆ.</color>",
  ui_story_5035_50351501_134_dialog_content = "ในขณะนั้น จู่ๆ พื้นใต้ตัวฉันก็เคลื่อนตัวออกไป และขยะต่างๆ ที่อยู่บนหัวฉันก็ตกลงมาพร้อมๆ กัน มันน่ากลัว",
  ui_story_5035_50351501_135_dialog_content = "ฉันไม่รู้ว่า——บางทีของที่ตกลงมาบางอันก็ใหญ่เกินไป——แต่มันติดอยู่เหนือฉันและไม่ได้แตะต้องฉันด้วยซ้ำ!",
  ui_story_5035_50351501_136_dialog_content = "อิฐก้อนหนึ่งติดอยู่ที่มุมของกำแพง คานตกลงบนเสาหิน และแผ่นไม้ตกลงบนคาน ป้องกันไม่ให้สิ่งของชิ้นเล็กๆ ตกลงมา",
  ui_story_5035_50351501_137_dialog_content = "ฉันลงเอยด้วยรังไหมในพื้นที่ที่เป็นโพรงซึ่งก่อตัวขึ้นจากขยะที่ตกลงมา และมีพื้นที่เพียงพอสำหรับฉันที่จะยืนขึ้น",
  ui_story_5035_50351501_138_dialog_content = "หา?",
  ui_story_5035_50351501_139_dialog_content = "จากนั้นฉันก็เริ่มหาทางออกทีละชิ้น เหมือนกับการรื้อบล็อกของเล่น มันค่อนข้างสนุกจริงๆ!",
  ui_story_5035_50351501_140_dialog_content = "ทันทีที่ฉันคลี่คลายตัวเอง ฉันก็ได้ยินเสียงความโกลาหลและตามเสียงนั้นไป",
  ui_story_5035_50351501_141_dialog_content = "ระหว่างทาง ฉันบังเอิญพบเทียนไขที่ผู้กำกับทำหล่น มันช่วยส่องสว่างเส้นทางของฉัน",
  ui_story_5035_50351501_142_dialog_content = "และที่เหลือถ้าคุณได้ดูการแสดง",
  ui_story_5035_50351501_143_dialog_content = "มีอะไรจะถามอีกไหม",
  ui_story_5035_50351501_144_dialog_content = "ม- นั่นคือสิ่งที่เกิดขึ้นจริงเหรอ?!",
  ui_story_5035_50351501_145_dialog_content = "โชคแบบนั้นสามารถอธิบายได้ว่าเป็นปาฏิหาริย์เท่านั้น!",
  ui_story_5035_50351501_146_dialog_content = "บางทีอาจเป็นปาฏิหาริย์ แต่แล้วอีกครั้ง ปาฏิหาริย์เกิดขึ้นทุกวัน",
  ui_story_5035_50351501_147_dialog_content = "ความจริงที่ว่าเราเกิดมาในโลกนี้เป็นปาฏิหาริย์ในตัวเอง!",
  ui_story_5035_50351501_148_dialog_content = "ว้าว คุณมีดาราดังจริงๆด้วย...",
  ui_story_5035_50351501_149_dialog_content = "ฮึก! ในที่สุดฉันก็ทำสำเร็จ!",
  ui_story_5035_50351501_150_dialog_content = "โกลดี้ ฉันดีใจที่คุณไม่เป็นไร!",
  ui_story_5035_50351501_151_dialog_content = "ฉันตัดสินใจแล้ว! ฉันจะเริ่มถ่ายทำฉากนี้กับคุณ!",
  ui_story_5035_50351501_152_dialog_content = "ว้าว ผู้เข้าร่วมหลักทั้งหมดอยู่ด้วย ให้ฉันสัมภาษณ์คุณ!",
  ui_story_5035_50351501_153_dialog_content = "หลังจากที่ Into the Haunted House ออกอากาศ มีคำถามหนึ่งคำถามในใจของทุกคน",
  ui_story_5035_50351501_154_dialog_content = "เลดี้แอสเตอร์ที่ปีนออกมาจากโลงศพนั้นเป็นผีจริงๆเหรอ?",
  ui_story_5035_50351501_155_dialog_content = "อา ฉันรู้ว่าสิ่งนี้กำลังจะมา การพูดทางเทคนิค—",
  ui_story_5035_50351501_156_dialog_content = "คุณควรเข้าไปข้างในและค้นหาด้วยตัวคุณเอง",
